-- Run after 007-custom-sources.sql. Bilingual tutorials, admin edits and revision audit.
begin;
create table if not exists public.tutorial_catalog (
 id text primary key check(id ~ '^[a-z0-9-]{1,80}$'),
 body jsonb not null,
 revision integer not null default 1 check(revision>0),
 updated_at timestamptz not null default now(),
 updated_by uuid references auth.users(id) on delete set null
);
create table if not exists public.tutorial_changes (
 change_id bigint generated always as identity primary key,
 tutorial_id text not null references public.tutorial_catalog(id),
 actor_id uuid references auth.users(id) on delete set null,
 revision integer not null,
 previous_body jsonb not null,
 new_body jsonb not null,
 created_at timestamptz not null default now()
);
alter table public.tutorial_catalog enable row level security;
alter table public.tutorial_changes enable row level security;
revoke all on public.tutorial_catalog,public.tutorial_changes from public,anon,authenticated;
revoke all on sequence public.tutorial_changes_change_id_seq from public,anon,authenticated;

create or replace function public.tutorial_require_text(p_value jsonb,p_max integer) returns void
language plpgsql immutable set search_path='' as $fn$
begin
 if p_value is null or jsonb_typeof(p_value)<>'string' or length(btrim(p_value#>>'{}')) not between 1 and p_max then
  raise exception 'Tutorial text is missing or too long.' using errcode='22023';
 end if;
end;
$fn$;
revoke all on function public.tutorial_require_text(jsonb,integer) from public,anon,authenticated;

create or replace function public.validate_tutorial_body(p_id text,p_body jsonb) returns void
language plpgsql immutable set search_path='' as $fn$
declare lang text; v jsonb; s jsonb; b jsonb; item jsonb; cell jsonb; row_value jsonb; typ text; cols integer; ord numeric;
begin
 if p_id is null or p_id !~ '^[a-z0-9-]{1,80}$' or jsonb_typeof(p_body) is distinct from 'object' or p_body->>'id' is distinct from p_id or length(p_body::text)>300000 then
  raise exception 'Invalid tutorial ID or payload.' using errcode='22023';
 end if;
 if coalesce(p_body->>'levelKey','') not in ('beginner','intermediate','advanced') or jsonb_typeof(p_body->'order') is distinct from 'number' then
  raise exception 'Invalid tutorial level or order.' using errcode='22023';
 end if;
 ord:=(p_body->>'order')::numeric;
 if ord<>trunc(ord) or ord not between 1 and 1000 then raise exception 'Invalid tutorial order.' using errcode='22023'; end if;
 perform public.tutorial_require_text(p_body->'category',80);
 perform public.tutorial_require_text(p_body->'aliases',2000);
 if jsonb_typeof(p_body->'related') is distinct from 'array' then raise exception 'Invalid related topics.' using errcode='22023'; end if;
 if jsonb_array_length(p_body->'related')>30 then raise exception 'Too many related topics.' using errcode='22023'; end if;
 for item in select value from jsonb_array_elements(p_body->'related') loop
  if jsonb_typeof(item)<>'string' or (item#>>'{}') !~ '^[a-z0-9-]{1,80}$' then raise exception 'Invalid related topic ID.' using errcode='22023'; end if;
 end loop;
 foreach lang in array array['mn','en'] loop
  v:=case when lang='mn' then p_body else p_body#>'{translations,en}' end;
  if jsonb_typeof(v) is distinct from 'object' then raise exception 'Both languages are required.' using errcode='22023'; end if;
  perform public.tutorial_require_text(v->'title',200);
  perform public.tutorial_require_text(v->'summary',4000);
  perform public.tutorial_require_text(v->'prerequisites',2000);
  if jsonb_typeof(v->'sections') is distinct from 'array' then raise exception 'Invalid tutorial sections.' using errcode='22023'; end if;
  if jsonb_array_length(v->'sections') not between 1 and 30 then raise exception 'Expected 1-30 sections.' using errcode='22023'; end if;
  for s in select value from jsonb_array_elements(v->'sections') loop
   if jsonb_typeof(s) is distinct from 'object' then raise exception 'Invalid section.' using errcode='22023'; end if;
   perform public.tutorial_require_text(s->'title',200);
   if jsonb_typeof(s->'blocks') is distinct from 'array' then raise exception 'Invalid section content.' using errcode='22023'; end if;
   if jsonb_array_length(s->'blocks') not between 1 and 40 then raise exception 'Expected 1-40 content blocks.' using errcode='22023'; end if;
   for b in select value from jsonb_array_elements(s->'blocks') loop
    if jsonb_typeof(b) is distinct from 'object' then raise exception 'Invalid content block.' using errcode='22023'; end if;
    typ:=b->>'type';
    if typ in ('p','note','code') then perform public.tutorial_require_text(b->'text',40000);
    elsif typ='math' then perform public.tutorial_require_text(b->'tex',8000);
    elsif typ in ('list','ordered') then
     if jsonb_typeof(b->'items') is distinct from 'array' then raise exception 'Invalid list.' using errcode='22023'; end if;
     if jsonb_array_length(b->'items') not between 1 and 100 then raise exception 'Invalid list length.' using errcode='22023'; end if;
     for item in select value from jsonb_array_elements(b->'items') loop perform public.tutorial_require_text(item,8000); end loop;
    elsif typ='table' then
     if jsonb_typeof(b->'headers') is distinct from 'array' or jsonb_typeof(b->'rows') is distinct from 'array' then raise exception 'Invalid table.' using errcode='22023'; end if;
     cols:=jsonb_array_length(b->'headers');
     if cols not between 1 and 8 or jsonb_array_length(b->'rows') not between 1 and 100 then raise exception 'Invalid table dimensions.' using errcode='22023'; end if;
     for cell in select value from jsonb_array_elements(b->'headers') loop perform public.tutorial_require_text(cell,200); end loop;
     for row_value in select value from jsonb_array_elements(b->'rows') loop
      if jsonb_typeof(row_value) is distinct from 'array' then raise exception 'Invalid table row.' using errcode='22023'; end if;
      if jsonb_array_length(row_value)<>cols then raise exception 'Table column counts differ.' using errcode='22023'; end if;
      for cell in select value from jsonb_array_elements(row_value) loop perform public.tutorial_require_text(cell,8000); end loop;
     end loop;
    elsif typ='links' then
     if jsonb_typeof(b->'items') is distinct from 'array' then raise exception 'Invalid links.' using errcode='22023'; end if;
     if jsonb_array_length(b->'items') not between 1 and 30 then raise exception 'Invalid links length.' using errcode='22023'; end if;
     for item in select value from jsonb_array_elements(b->'items') loop
      perform public.tutorial_require_text(item->'label',300);perform public.tutorial_require_text(item->'url',1000);
      if item->>'url' !~ '^https://[^/@[:space:]]+([/?#][^[:space:]]*)?$' then raise exception 'HTTPS links are required.' using errcode='22023'; end if;
     end loop;
    else raise exception 'Unsupported tutorial block type.' using errcode='22023';
    end if;
   end loop;
  end loop;
 end loop;
end;
$fn$;
revoke all on function public.validate_tutorial_body(text,jsonb) from public,anon,authenticated;

create or replace function public.get_tutorials() returns jsonb
language sql stable security definer set search_path='' as $fn$
 select coalesce(jsonb_agg(jsonb_build_object('body',t.body,'revision',t.revision)
 order by case t.body->>'levelKey' when 'beginner' then 1 when 'intermediate' then 2 else 3 end,(t.body->>'order')::integer,t.id),'[]'::jsonb)
 from public.tutorial_catalog t;
$fn$;
revoke all on function public.get_tutorials() from public;
grant execute on function public.get_tutorials() to anon,authenticated;

create or replace function public.admin_save_tutorial(p_id text,p_body jsonb,p_revision integer) returns jsonb
language plpgsql security definer set search_path='' as $fn$
declare old public.tutorial_catalog%rowtype; saved public.tutorial_catalog%rowtype;
begin
 if auth.uid() is null or not public.is_admin() then raise exception 'Admin эрх шаардлагатай.' using errcode='42501'; end if;
 perform public.validate_tutorial_body(p_id,p_body);
 select * into old from public.tutorial_catalog where id=p_id for update;
 if not found then raise exception 'Tutorial not found.' using errcode='22023'; end if;
 if p_revision is distinct from old.revision then raise exception 'REVISION_CONFLICT: reload this tutorial.' using errcode='40001'; end if;
 update public.tutorial_catalog set body=p_body,revision=old.revision+1,updated_at=now(),updated_by=auth.uid() where id=p_id returning * into saved;
 insert into public.tutorial_changes(tutorial_id,actor_id,revision,previous_body,new_body) values(p_id,auth.uid(),saved.revision,old.body,saved.body);
 return jsonb_build_object('body',saved.body,'revision',saved.revision);
end;
$fn$;
revoke all on function public.admin_save_tutorial(text,jsonb,integer) from public,anon;
grant execute on function public.admin_save_tutorial(text,jsonb,integer) to authenticated;

-- Seed only missing lessons; rerunning preserves administrator edits.
insert into public.tutorial_catalog(id,body)
select x->>'id',x from jsonb_array_elements($tutorial_seed$[{"id":"complexity","title":"Time & space complexity","category":"Суурь","level":"Анхан шат","aliases":"big o O(n) хугацаа санах ой complexity asymptotic","summary":"Input томроход алгоритмын ажил хэрхэн нэмэгдэхийг тооцож, бодлогод багтах шийдэл сонгох.","prerequisites":"Loop, array, function.","related":["prefix-sums","binary-search","monotonic-stack"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"Time complexity нь код хэдэн секунд ажиллахыг шууд хэлдэггүй. Харин input-ийн хэмжээ өсөхөд хийх үйлдлийн тоо хэрхэн нэмэгдэхийг илэрхийлнэ. Big-O нь өсөлтийн дээд хязгаарыг, Θ нь өсөлтийн яг эрэмбийг тэмдэглэнэ. Жишээлбэл, $n$ элементтэй array-г нэг удаа бүтэн тойрох loop-ын complexity нь $\\Theta(n)$. Үүнийг $O(n^{2})$ гэж дээд хязгаарлаж болох ч алгоритмыг үнэлэхэд хэт сул мэдээлэл болно."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Код бичихээс өмнө $n$, query-ийн тоо $q$, graph-ийн $V$ ба $E$, DP-ийн state-уудын тоог хар. $n=200000$ үед бүх хосыг үзэх $n^{2}$ арга ихэвчлэн тохирохгүй. Харин sort хийдэг $n$ log $n$ шийдэл боломжтой байж болно. Нэг секундэд яг хэдэн үйлдэл багтах тогтмол дүрэм байхгүй: хэл, memory access, өгөгдлийн бүтэц, judge-ийн төхөөрөмж бүгд нөлөөлнө."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"Дараалсан loop-уудын ажлыг нэмнэ; nested loop-ын хувьд дотор loop хэдэн удаа ажиллахыг нийтээр нь тоолно. Дотор loop-ын урт $i$ байвал $n^{2}$ гэсэн үгийг цээжлэхийн оронд $1+2+…+n$ нийлбэр гарга. Binary search-д үлдсэн боломжийн тоо алхам бүрд хоёр дахин багасдаг."},{"type":"math","tex":"\\sum_{i=1}^{n} i=\\frac{n(n+1)}2=\\Theta(n^2),\\qquad \\log_2 n\\text{ halvings}"},{"type":"p","text":"Space complexity-д array, DP table, adjacency list, recursion stack зэрэг нэмэлт санах ойг тооцно. Input өөрөө эзэлж буй зай болон алгоритмын нэмэлт зайг ялгаж хэл. Recursion гүн $n$ бол local variable цөөн байсан ч stack $O(n)$ болно."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$n=4$ үед эхний $i$-д $j=0…i$ гэсэн nested loop-ын үйлдэл $1+2+3+4=10$.","$n=8$ үед $36$, $n=16$ үед $136$ болно. $n$ хоёр дахин өсөхөд ажил ойролцоогоор дөрөв дахин өснө.","Харин $n$-ийг алхам бүрд /$2$ хийвэл $16\\to 8\\to 4\\to 2\\to 1$: дөрвөн алхам.","$n=200000$ үед бүх хос ойролцоогоор $20$ тэрбум. Sort-ийн харьцуулалтын эрэмбэ хэдэн сая орчим боловч энэ нь шууд секундийн амлалт биш."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"$\\Theta(n^{2})$-ийг батлахдаа дээд ба доод хязгаар хоёрыг харуул. Nested loop нийт $n$($n+1$)/$2$ ажилладаг тул $n\\ge 1$ үед $n^{2}/2$-оос багагүй, $n^{2}$-оос ихгүй. Иймээс хоёр тогтмолын хооронд $n^{2}$-той ижил эрэмбээр өснө. Amortized analysis-д нэг үйлдлийн worst case-ийг бүх үйлдэлд үржүүлж болохгүй: stack-д элемент бүр нэг удаа push, нэг удаа pop хийгдэх нь нийт $O(n)$-ийн жишээ."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nlong long count_pairs(int n) {\n    long long count = 0;\n    for (int i = 0; i < n; ++i)\n        for (int j = 0; j <= i; ++j) ++count;\n    return count;\n}\nint halvings(int n) {\n    int steps = 0;\n    while (n > 1) { n /= 2; ++steps; }\n    return steps;\n}"},{"type":"p","text":"Эдгээр function нь үйлдлийн тооны өсөлтийг ажиглахад зориулагдсан. count_pairs-ийн хариуг $n(n+1)/2$ томъёотой харьцуулж болно. Кодод үржүүлэхдээ эхний үйлдлээс нь long long ашиглаж overflow-оос сэргийлнэ. Ганц input дээр хийсэн benchmark нь complexity-ийн баталгаа болохгүй."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["count_pairs","$\\Theta(n^{2})$ хугацаа, $O(1)$ нэмэлт зай"],["halvings","$\\Theta(\\log  n)$ хугацаа, $O(1)$ нэмэлт зай"],["$n\\times m$ DP table","$O(\\mathrm{nm})$ state хадгалах зай"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["Big-O-г яг гүйцэтгэх хугацаа гэж ойлгох.","Query бүрд $O(n)$ хийдэг кодын нийт $O(\\mathrm{nq})$-ийг мартах.","int overflow-оос болоод үйлдлийн тоог буруу тооцох. $n*(n+1)$-ийг long long-д үржүүл.","Recursive DFS-ийн stack болон hash table-ийн overhead-ийг зайны тооцоонд оруулахгүй орхих."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Дараалсан хоёр $n$ урт loop яагаад $O(n^{2})$ биш вэ?","$i=1$,$2$,$4$,$8$… гэж өсөх loop хэдэн удаа ажиллах вэ?","$n=200000$, $q=200000$ үед prefix sum, naive range sum хоёрын нийт ажлыг харьцуул."]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"beginner","order":1,"translations":{"en":{"title":"Time & space complexity","summary":"Estimate how running time and memory grow with input size, then choose an algorithm that fits the constraints.","prerequisites":"Loops, arrays and functions.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"Time complexity describes the growth in the number of operations, rather than an exact number of seconds. Big-O gives an asymptotic upper bound; Θ describes a tight growth rate. A loop visiting every one of $n$ elements takes $\\Theta(n)$ time. Calling it $O(n^{2})$ is technically valid but less informative."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Before coding, identify the array length $n$, query count $q$, and graph sizes $V$ and $E$. For $n=200000$, inspecting every pair is usually too expensive. Sorting may be practical. The number of operations per second depends on the language, memory access and judge hardware."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"Add the costs of consecutive loops. For nested loops, count how often the inner body actually runs. If its length grows with $i$, sum those lengths. In binary search, each step halves the remaining search space."},{"type":"math","tex":"\\sum_{i=1}^{n} i=\\frac{n(n+1)}2=\\Theta(n^2),\\qquad \\log_2 n\\text{ halvings}"},{"type":"p","text":"Count auxiliary arrays, DP tables, adjacency lists and the recursion stack in space complexity. Distinguish input storage from extra working space. A recursion depth of $n$ can require $O(n)$ stack space even when each call has few local variables."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["For $n=4$, the nested loop performs $1+2+3+4=10$ operations.","For $n=8$ it performs $36$ operations; for $n=16$ it performs $136$. Doubling $n$ approximately quadruples the work.","Repeated halving follows $16\\to 8\\to 4\\to 2\\to 1$, requiring four steps.","At $n=200000$ the pair count is about twenty billion. An operation count is still not a promise about wall-clock time."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"The pair count is $n$($n+1$)/$2$. For $n\\ge 1$ it lies between $n^{2}/2$ and $n^{2}$, proving $\\Theta(n^{2})$. Amortized analysis counts a whole sequence of operations: if each element is pushed and popped at most once, all stack operations together take $O(n)$."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nlong long count_pairs(int n) {\n    long long count = 0;\n    for (int i = 0; i < n; ++i)\n        for (int j = 0; j <= i; ++j) ++count;\n    return count;\n}\nint halvings(int n) {\n    int steps = 0;\n    while (n > 1) { n /= 2; ++steps; }\n    return steps;\n}"},{"type":"p","text":"count_pairs returns the measured operation count. Compare it with the closed formula using long long arithmetic. A benchmark at one input size cannot prove an asymptotic bound."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["count_pairs","$\\Theta(n^{2})$ time; $O(1)$ extra space"],["halvings","$\\Theta(\\log  n)$ time; $O(1)$ extra space"],["An $n$ by $m$ DP table","$O(\\mathrm{nm})$ stored states"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Confusing Big-O with an exact running time.","Ignoring $q$ repetitions of an $O(n)$ operation: the total is $O(\\mathrm{nq})$.","Multiplying in int before converting to long long.","Forgetting recursion depth and hash-table overhead."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Explain why two consecutive loops of length $n$ take $O(n)$, rather than $O(n^{2})$.","Count iterations when $i$ takes values $1$,$2$,$4$,$8$ and so on.","Compare naive range sums with prefix sums for $n=q=200000$."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"prefix-sums","title":"Prefix sum & difference array","category":"Array ба search","level":"Анхан шат","aliases":"prefix sum угтвар нийлбэр difference array ялгаврын массив range sum","summary":"Олон range query-г урьдчилан тооцсон нийлбэрээр хурдан хариулах; олон range update-ийг difference array-д хуримтлуулах.","prerequisites":"Array, loop, нийлбэр.","related":["fenwick-tree","segment-tree","two-pointers"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"Prefix sum нь array-ийн эхнээс тодорхой байрлал хүртэлх нийлбэрийг урьдчилан хадгалдаг. Ингэснээр query бүрд тухайн range-ийг дахин тойрохгүй. Difference array нь олон range update-ийн эхлэл, төгсгөлийн өөрчлөлтийг тэмдэглээд, эцэст нь prefix sum авч бодит утгуудыг сэргээдэг. Эхний арга нь query-д, хоёр дахь нь бүх update-ийн дараа хариу хэрэгтэй offline бодлогод тохирно."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Array өөрчлөгдөхгүй, range sum олон удаа асуухад prefix sum хэрэглэ. Нэмэх update-уудыг бүгдийг хийсний дараа л эцсийн array хэрэгтэй бол difference array хэрэглэ. Update ба query ээлжилбэл энгийн prefix sum-ийг байнга дахин байгуулах хэрэг гарна; тэр үед Fenwick tree эсвэл segment tree-г сонго."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"$0$-based array дээр $\\mathrm{pref}[k]$ нь эхний $k$ элементийн нийлбэр байг. Тэгвэл $\\mathrm{pref}[0]=0$, $\\mathrm{pref}[i+1]=\\mathrm{pref}[i]+a[i]$. Энэ хичээлд бүх range $[l,r)$, өөрөөр хэлбэл $l$ багтана, $r$ багтахгүй. Хоосон range-ийн нийлбэр $0$."},{"type":"math","tex":"\\operatorname{sum}(l,r)=P[r]-P[l],\\qquad d[l]\\mathrel{+}=x,\\quad d[r]\\mathrel{-}=x"},{"type":"p","text":"Difference array-д $l$-ээс эхлэн $x$ нэмэгдэж, $r$-ээс эхлэн тэр нөлөө дуусна. $n+1$ урттай array хэрэглэвэл $r=n$ үед төгсгөлийн тэмдэглэгээг ч аюулгүй хадгална. Нийлбэр $n$×max|$a[i]$| хүрч болдог тул long long хэрэгтэй эсэхээ шалга."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$a=[2,-1,3,4]$ байвал $P=[0,2,1,4,8]$.","$[1,4)$ range нь $-1+3+4=6$. $P[4]-P[1]=8-2=6$.","Zero array дээр $[1,4)$-д $5$ нэмбэл $d[1]+=5$, $d[4]$−=$5$.","$d$-ийн running sum-ийг авбал $[0,5,5,5]$ гарна. Дараагийн update-ийг $d$ дээр нэмж тэмдэглээд нэг удаа сэргээж болно."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"$P[r]$ нь $[0,r)$-ийг, $P[l]$ нь $[0,l)$-ийг тоолсон. Ижил эхний хэсгийг хасахад $[l,r)$ л үлдэнэ. Difference array-ийн нэг update prefix sum авахад $i<l$ үед $0$, $l\\le i<r$ үед $x$, $i\\ge r$ үед $x-x=0$ нэмэртэй. Бүх update нийлбэрт шугаман байдлаар үйлчилдэг тул тэдгээрийг хамтад нь тэмдэглэх нь зөв."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nvector<long long> prefix(const vector<long long>& a) {\n    vector<long long> p(a.size() + 1, 0);\n    for (int i = 0; i < (int)a.size(); ++i) p[i+1] = p[i] + a[i];\n    return p;\n}\nvector<long long> apply_updates(int n,\n        const vector<tuple<int,int,long long>>& updates) {\n    vector<long long> d(n+1, 0), a(n);\n    for (auto [l,r,x] : updates) {\n        assert(0 <= l && l <= r && r <= n);\n        d[l] += x; d[r] -= x;\n    }\n    long long current = 0;\n    for (int i = 0; i < n; ++i) { current += d[i]; a[i] = current; }\n    return a;\n}"},{"type":"p","text":"Prefix array-г нэг удаа байгуулсны дараа range sum-ийг $P[r]-P[l]$ гэж олно. Update бүрийг $(l,r,x)$ хэлбэрээр өгнө. apply_updates нь анх бүх утга нь $0$ байсан array-г сэргээнэ. Анхны array өгөгдсөн бол сэргээсэн нэмэгдлийг элемент тус бүрд нь нэмж тооцно."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Prefix байгуулах","$O(n)$ хугацаа, $O(n)$ зай"],["Нэг range sum","$O(1)$"],["$q$ offline range update + сэргээх","$O(n+q)$ хугацаа, $O(n)$ зай"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["$[l,r]$ ба $[l,r)$-ийг холих; inclusive $r$-ийг кодод $r+1$ болго.","Prefix sum нь ерөнхий range minimum-ийг хасалтаар гаргаж чадахгүй.","Negative элемент prefix sum-д асуудалгүй. Харин sum-ийг monotonic гэж үзэж binary search хийхэд асуудал болно.","Difference array-аас final array сэргээхээс өмнө энгийн query асуух."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["$[0,n)$, $[2,2)$, ганц элемент-ийн range-ийг турш.","2D grid-ийн rectangle sum-д дөрвөн prefix утгын inclusion-exclusion томъёо гарга.","Overlap хийсэн хоёр update-ийн хариуг гараар тооцоод кодтой тулга."]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"beginner","order":2,"translations":{"en":{"title":"Prefix sum & difference array","summary":"Answer static range sums quickly and combine offline range additions with a difference array.","prerequisites":"Arrays, loops and addition.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"A prefix sum stores the total before a position. It avoids rescanning a range for every query. A difference array records where an update begins and ends; a final prefix scan reconstructs the actual array. Prefix sums primarily answer queries, whereas difference arrays batch updates."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use prefix sums when the array is fixed and there are many sum queries. Use a difference array when all additions happen before you need the final values. Interleaved updates and queries usually need a Fenwick tree or segment tree."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"Use a $0$-based array and let $P[k]$ be the sum of its first $k$ elements. Set $P[0]=0$ and $P[i+1]=P[i]+a[i]$. Every range in this implementation is $[l,r)$: $l$ is included and $r$ is excluded."},{"type":"math","tex":"\\operatorname{sum}(l,r)=P[r]-P[l],\\qquad d[l]\\mathrel{+}=x,\\quad d[r]\\mathrel{-}=x"},{"type":"p","text":"For a range addition $x$, record the beginning at $d[l]$ and the end at $d[r]$. Allocate $n+1$ entries so that $r=n$ is valid. The sum may reach $n$ times the largest absolute element, so choose a sufficiently wide integer type."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["For $a=[2,-1,3,4]$, the prefix array is $P=[0,2,1,4,8]$.","The sum of $[1,4)$ is $P[4]$-$P[1]=8$-$2=6$.","Adding $5$ to $[1,4)$ in an initially zero array records $d[1]+=5$ and $d[4]-=5$.","A running sum of $d$ produces $[0,5,5,5]$. Multiple updates can be recorded before this scan."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"$P[r]$ counts $[0,r)$, and $P[l]$ counts $[0,l)$. Subtracting cancels the common prefix. A difference update contributes zero before $l$, contributes $x$ on $[l,r)$, and cancels after $r$. Linearity makes this work for any number of additions."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nvector<long long> prefix(const vector<long long>& a) {\n    vector<long long> p(a.size() + 1, 0);\n    for (int i = 0; i < (int)a.size(); ++i) p[i+1] = p[i] + a[i];\n    return p;\n}\nvector<long long> apply_updates(int n,\n        const vector<tuple<int,int,long long>>& updates) {\n    vector<long long> d(n+1, 0), a(n);\n    for (auto [l,r,x] : updates) {\n        assert(0 <= l && l <= r && r <= n);\n        d[l] += x; d[r] -= x;\n    }\n    long long current = 0;\n    for (int i = 0; i < n; ++i) { current += d[i]; a[i] = current; }\n    return a;\n}"},{"type":"p","text":"Build $\\mathrm{prefix}(a)$ once, then subtract its entries for each query. apply_updates starts with a zero array; for a nonzero initial array, add the reconstructed increments to the original elements."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Prefix construction","$O(n)$ time and space"],["One range-sum query","$O(1)$ time"],["$q$ offline additions and reconstruction","$O(n+q)$ time; $O(n)$ space"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Mixing inclusive $[l,r]$ with half-open $[l,r)$.","Trying to obtain arbitrary range minima by subtracting prefixes.","Assuming sums remain monotonic when negative values exist.","Querying the unreconstructed difference array as if it held actual values."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Test the entire array, an empty range and a single-element range.","Derive the four-term inclusion-exclusion formula for a rectangle in a 2D grid.","Check two overlapping updates by hand."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"hash-compression","title":"Hash map & coordinate compression","category":"Data structures","level":"Анхан шат","aliases":"hash map unordered_map map frequency coordinate compression шахалт давтамж","summary":"Том утгуудын давтамжийг хадгалах, утгуудыг дарааллыг нь алдагдуулахгүй жижиг индекс болгон шахах.","prerequisites":"Array, sort, binary search.","related":["binary-search","fenwick-tree","segment-tree"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"Coordinate compression нь том эсвэл сийрэг утгуудыг эрэмбэлсэн жижиг индексүүдээр төлөөлдөг. Ижил утгууд ижил индекс авч, бага утга бага индекс авна. Харин хоёр утгын зөрүү хадгалагдахгүй. Hash table нь утгаар хайх, давтамж тоолох зэрэг equality-д тулгуурласан үйлдэлд тохирдог бөгөөд утгуудын эрэмбийг хадгалдаггүй."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Frequency, value→state lookup-д map тохирно. Fenwick/segment tree-г том координат дээр ашиглахдаа compression хийнэ. Query-ийн бүх утга урьдчилан мэдэгдэж байвал шаардлагатай query coordinate-уудаа ч цуглуул. Compression нь утгын эрэмбэ ба тэнцүү чанарыг хадгалдаг боловч бодит зай, ялгавар, үржвэрийг хадгалахгүй."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"Sorted unique утгуудыг vals гэе. $x$-ийн rank нь lower_bound(vals,$x$)-ийн index. Нэг value ижил rank авч, бага value бага rank авна. Анхны утгыг хэрэгтэй үед $\\mathrm{vals}[\\mathrm{rank}]$-аас сэргээнэ. Unordered_map-ийн average $O(1)$ нь worst-case баталгаа биш; CP-д adversarial collision-ийг бас бодолц."},{"type":"math","tex":"x<y\\iff\\operatorname{rank}(x)<\\operatorname{rank}(y),\\qquad x=y\\iff\\operatorname{rank}(x)=\\operatorname{rank}(y)"},{"type":"p","text":"Compression хийсний дараа $[100,1000]$ нь $[0,1]$ болно; зай нь $900$ биш $1$ болсон. Geometry эсвэл interval length тооцохдоо анхны coordinate-ийн ялгаврыг хэрэглэ. Map-ийн $\\mathrm{operator}[]$ нь байхгүй key-г default value-тай нэмдэг; зөвхөн байгаа эсэхийг асуухдаа find/count хэрэглэ."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$a=[100,-5,100,1000000000]$. Sorted unique vals=$[-5,100,1000000000]$.","$-5\\to 0$, $100\\to 1$, $1000000000\\to 2$.","Шахсан array $[1,0,1,2]$. Frequency array $[1,2,1]$.","Анхны $100$ ба $1000000000$-ын хоорондын зайг rank-аас биш $\\mathrm{vals}[2]-\\mathrm{vals}[1]$-ээс олно."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"Sorted unique жагсаалтад value бүр яг нэг байрлалтай. lower_bound нь тэр байрлалыг олно. Sorting нь бүх pair-ийн бага/их харьцааг хадгалсан тул rank-ууд дээрх харьцуулалт анхны value-тай адил. Иймээс зөвхөн order ба equality-д тулгуурласан алгоритмд rank орлуулахад хариу өөрчлөгдөхгүй."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\npair<vector<int>,vector<long long>> compress(const vector<long long>& a) {\n    vector<long long> vals = a;\n    sort(vals.begin(), vals.end());\n    vals.erase(unique(vals.begin(), vals.end()), vals.end());\n    vector<int> ranks;\n    for (long long x : a)\n        ranks.push_back(lower_bound(vals.begin(),vals.end(),x)-vals.begin());\n    return {ranks, vals};\n}"},{"type":"p","text":"Буцах pair-ийн first нь rank array, second нь rank-аас анхны утга руу шилжих mapping юм. Зөвхөн давтамж хэрэгтэй бол map эсвэл unordered_map ашиглаж болно. Шинэ coordinate дараа нь ирэхэд өмнөх compression автоматаар шинэчлэгдэхгүй тул шаардлагатай утгуудаа эхлээд бүрэн цуглуулна."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Compression","$O(n \\log  n)$ хугацаа, $O(n)$ зай"],["std::map lookup/update","$O(\\log  k)$"],["unordered_map lookup/update","Average $O(1)$, worst case $O(k)$"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["Compressed index-үүдийн ялгаврыг бодит зай гэж үзэх.","Duplicate утгуудыг unique хийхгүй байх.","Unordered_map iteration sorted байна гэж таамаглах.","$\\mathrm{operator}[]$ ашигласан lookup шинэ entry үүсгэж болохыг мартах."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Inverse mapping-ээр бүх $a[i]$-г сэргээ.","Том coordinate-тай inversion count-д ямар data structure нэмж хэрэглэх вэ?","Online шинэ value ирдэг үед offline compression-ийн ямар асуудал гарахыг тайлбарла."]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"beginner","order":3,"translations":{"en":{"title":"Hash map & coordinate compression","summary":"Map large values to compact ordered indices and distinguish ordered compression from hash lookup.","prerequisites":"Sorting, binary search and associative containers.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"Coordinate compression replaces each distinct value with its position in a sorted unique list. Equality and order are preserved, but numeric distances are not. Hash tables instead support equality-based lookup without preserving sorted order."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Compress coordinates before a Fenwick tree, segment tree or value-indexed DP when original values are too large for an array. Use a hash map for frequencies when order queries are unnecessary."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"Copy the values, sort them and erase duplicates. For each original $x$, use lower_bound in the unique list to obtain its compressed rank. Preserve the list to translate a rank back to its original value."},{"type":"math","tex":"x<y\\iff\\operatorname{rank}(x)<\\operatorname{rank}(y),\\qquad x=y\\iff\\operatorname{rank}(x)=\\operatorname{rank}(y)"},{"type":"p","text":"If values arrive later, either collect all relevant values offline or use a structure that supports online keys. A hash table has expected efficient operations, but its worst-case behaviour is not the same as a balanced tree."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["Start with values $[100,-5,100,8]$.","The sorted unique list is $[-5,8,100]$.","The compressed array is $[2,0,2,1]$.","Ranks $0$ and $1$ differ by one, but their original values differ by $13$."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"Sorting places $x$ before $y$ exactly when $x<y$. Removing duplicates gives one rank to each distinct value. Thus comparisons and equality are preserved, which is sufficient for order-based queries, but differences and geometric lengths need original coordinates."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\npair<vector<int>,vector<long long>> compress(const vector<long long>& a) {\n    vector<long long> vals = a;\n    sort(vals.begin(), vals.end());\n    vals.erase(unique(vals.begin(), vals.end()), vals.end());\n    vector<int> ranks;\n    for (long long x : a)\n        ranks.push_back(lower_bound(vals.begin(),vals.end(),x)-vals.begin());\n    return {ranks, vals};\n}"},{"type":"p","text":"The function returns both the rank array and the sorted unique values. The ranks have the same length and order as the input; the values provide inverse mapping. lower_bound for a value absent from that copy gives an insertion position, not a registered coordinate."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Sort and unique","$O(n \\log  n)$ time"],["Map all $n$ values by binary search","$O(n \\log  n)$ time"],["Lists and ranks","$O(n)$ space"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Assuming rank differences preserve coordinate distances.","Forgetting to erase duplicate values.","Compressing only initial values when updates introduce new keys.","Assuming unordered_map provides sorted iteration or a guaranteed constant worst-case bound."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Compress repeated negative and very large values.","Retain inverse mapping and recover the original array.","Explain how to compute interval lengths from original coordinates."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"binary-search","title":"Binary search","category":"Array ба search","level":"Анхан шат","aliases":"хоёртын хайлт binary search lower bound upper bound answer monotonic","summary":"Monotonic нөхцөлийн false/true заагийг олж, эрэмбэлсэн array эсвэл хариун дээр хайлт хийх.","prerequisites":"Sorted array, comparison, complexity.","related":["complexity","prefix-sums","lis"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"Binary search нь зөвхөн array-аас утга хайхад хэрэглэгддэггүй. Боломжит хариунуудын хувьд $\\mathrm{check}(x)$ нөхцөл эхлээд false, тодорхой заагаас хойш true болдог байвал анхны true байрлалыг олж болно. Хамгийн чухал шаардлага нь нөхцөл monotonic байх явдал юм. Тиймээс $x$ боломжтой үед түүнээс их утгууд яагаад боломжтой хэвээр үлдэхийг эхлээд батална."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Sorted array дээр lower_bound буюу анхны ≥$x$ байрлал, upper_bound буюу анхны >$x$ байрлал олоход хэрэглэнэ. Хамгийн бага боломжит capacity, хамгийн бага хугацаа зэрэг answer search бодлогод check function зохионо. Check нь $O(n)$ бол хайлт $O(n \\log  R)$. Нөхцөл true/false ээлжлээд байвал энэ template тохирохгүй."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"Хариу $[0,n]$ байг; $n$ нь array-д тохирох элемент байхгүй гэсэн sentinel. $l<r$ үед $m$-ийг шалга. $a[m]\\ge x$ бол анхны тохирох байрлал $m$-ээс хойш байх албагүй тул $r=m$. Үгүй бол $m$ болон түүнээс өмнөх бүх байрлал тохирохгүй учир $l=m+1$."},{"type":"math","tex":"\\text{answer}\\in[l,r],\\qquad m=l+\\left\\lfloor\\frac{r-l}{2}\\right\\rfloor"},{"type":"p","text":"Энэ хувилбар $n$ sentinel дээр check хийхгүй. Loop дуусахад $l=r$ болсон цорын ганц candidate үлдэнэ. Answer search дээр check-ийн дотор integer overflow, ceiling division, total sum-ийн төрлийг мөн шалга. Midpoint зөв байсан ч check буруу байвал хариу буруу гарна."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$a=[1,3,3,7,9]$, $x=4$. Эхэнд $l=0$,$r=5$.","$m=2$ дээр $3<4$: $l=3$. Одоо хариу $[3,5]$-д.","$m=4$ дээр $9\\ge 4$: $r=4$. $m=3$ дээр $7\\ge 4$: $r=3$.","$l=r=3$, хариу $a[3]=7$-ийн байрлал. $x=10$ үед $5$ буцна; $a[5]$-д хандаж болохгүй."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"Loop эхэнд анхны тохирох байрлал $[l,r]$-д байна. Sorted учир $a[m]<x$ байвал бүх $i\\le m$ дээр $a[i]<x$; хариу $m+1$-ээс эхэлнэ. $a[m]\\ge x$ байвал $m$ өөрөө боломжит байрлал тул хариу $m$-ээс их байж таарахгүй. Алхам бүр invariant хадгалагдаж, range багасна. Тэгэхээр төгсгөлд үлдсэн $l$ зөв хариу."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nint first_at_least(const vector<long long>& a, long long x) {\n    int l = 0, r = (int)a.size();\n    while (l < r) {\n        int m = l + (r-l)/2;\n        if (a[m] >= x) r = m;\n        else l = m+1;\n    }\n    return l;\n}"},{"type":"p","text":"Array нь өсөх буюу тэнцүү утга зөвшөөрсөн эрэмбэтэй байх ёстой. Буцах индекс $n$ бол тохирох элемент байхгүй. Standard library-ийн lower_bound мөн ийм үр дүн өгдөг. Яг $x$ утга байгаа эсэхийг шалгахдаа эхлээд индекс $n$-ээс бага эсэхийг, дараа нь тухайн утга $x$-тэй тэнцүү эсэхийг шалгана."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Sorted array query","$O(\\log  n)$ хугацаа, $O(1)$ нэмэлт зай"],["Sort шаардлагатай бол","$O(n \\log  n)$ урьдчилсан ажил"],["Answer search","$O(\\mathrm{Tcheck} \\times  \\log  R)$ хугацаа"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["Unsorted array дээр шууд хэрэглэх.","$r=m-1$ гэж өөр template-ийн дүрмийг хольж хэрэглэх; $m$ нь хариу байж болно.","Midpoint өөрчлөгдөхгүй loop үүсгэх.","Answer search-ийн high нь үнэхээр боломжтой эсэхийг шалгахгүй байх."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Хоосон array, бүх элемент ижил, $x$ хамгийн бага/их утгаас гадуур тохиолдлыг шалга.","Upper_bound хийхэд ганц comparison-ийг яаж өөрчлөх вэ?","Хугацаа $T$-д $k$ machine хэдэн бүтээгдэхүүн гаргах check function зохиож monotonic чанарыг батал."]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"beginner","order":4,"translations":{"en":{"title":"Binary search","summary":"Find the boundary of a monotonic predicate in a sorted array or in the space of possible answers.","prerequisites":"Sorted arrays, comparisons and complexity.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"Binary search is a method for locating a boundary. A predicate $\\mathrm{check}(x)$ must change from false to true at most once. The monotonic property is essential: establish why a feasible answer remains feasible when $x$ increases."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use lower_bound for the first element at least $x$, or upper_bound for the first element greater than $x$. For minimum-capacity or minimum-time problems, search over answers with a feasibility test. An $O(n)$ test gives $O(n \\log  R)$ total time over a search interval of width $R$."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"Maintain a candidate interval $[l,r]$ for an answer in $[0,n]$, where $n$ is a sentinel meaning that no array element qualifies. If $a[m]\\ge x$, keep $m$ by setting $r=m$. Otherwise discard $m$ and all earlier positions by setting $l=m+1$."},{"type":"math","tex":"\\text{answer}\\in[l,r],\\qquad m=l+\\left\\lfloor\\frac{r-l}{2}\\right\\rfloor"},{"type":"p","text":"The implementation never reads $a[n]$. At termination $l=r$ is the only candidate. Check the feasibility function for overflow and correct ceiling division; a correct midpoint cannot repair an incorrect predicate."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["Take $a=[1,3,3,7,9]$ and $x=4$. Initially $l=0$ and $r=5$.","At $m=2$, $a[m]=3$ is too small, so $l=3$.","At $m=4$, set $r=4$; then $m=3$ qualifies, so $r=3$.","The returned index is $3$. For $x=10$, the return value is $5$ and must not be dereferenced."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"The first qualifying position stays in $[l,r]$. Sorted order means that when $a[m]<x$ every earlier element also fails. When $a[m]\\ge x$, a qualifying position exists at or before $m$. Each step preserves this invariant and shrinks the interval."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nint first_at_least(const vector<long long>& a, long long x) {\n    int l = 0, r = (int)a.size();\n    while (l < r) {\n        int m = l + (r-l)/2;\n        if (a[m] >= x) r = m;\n        else l = m+1;\n    }\n    return l;\n}"},{"type":"p","text":"Require nondecreasing input. An index equal to $a$.$\\mathrm{size}()$ means no match. To test exact equality, first check that the index is in bounds. The standard lower_bound implements the same operation."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["One sorted-array query","$O(\\log  n)$ time; $O(1)$ extra space"],["Initial sorting if needed","$O(n \\log  n)$ time"],["Answer search","$O(\\mathrm{T\\_check} \\log  R)$ time"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Searching an unsorted array.","Mixing the $r=m$ rule with another template that uses $r=m$-$1$.","Choosing updates that do not shrink the interval.","Using an upper search bound that is not actually feasible."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Test an empty array, repeated values and targets outside the array range.","Change the comparison to implement upper_bound.","Design and prove a monotonic production-time check for $k$ machines."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"two-pointers","title":"Two pointers & sliding window","category":"Array ба search","level":"Анхан шат","aliases":"хоёр зааг sliding window two pointers subarray window","summary":"Range-ийн хоёр заагийг зөвхөн урагшлуулж, олон overlapping subarray-г нийт $O(n)$-д боловсруулах.","prerequisites":"Array, prefix sum, monotonic нөхцөл.","related":["prefix-sums","hash-compression","monotonic-stack"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"Two pointers нь $l$, $r$ гэсэн хоёр заагийг ашиглан array-ийн хэсгүүдийг боловсруулдаг. Sliding window хувилбар нь одоогийн range-ийн нийлбэр, давтамж зэрэг мэдээллийг давхар хадгална. Код дотор nested loop байсан ч зааг тус бүр нийт $n$ удаа л урагшилбал нийт хугацаа $O(n)$ байна. Энэ аргыг хэрэглэхийн өмнө range томрох, жижгэрэхэд нөхцөл хэрхэн өөрчлөгдөхийг тогтоох хэрэгтэй."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Nonnegative array дээр $\\mathrm{sum}\\le K$ байх subarray-ийн тоо, distinct элемент≤$K$ байх цонх, string-д тодорхой нөхцөл хангах хамгийн урт хэсэгт хэрэглэж болно. Sum-ийн хувьд negative тоо байвал $r$ нэмэхэд sum буурч болох учир доорх арга ерөнхийдөө буруу. Тийм үед prefix $\\mathrm{sum}$ + өөр өгөгдлийн бүтэц хэрэгтэй."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"Баруун зааг $r$-ийг нэмэхдээ $a[r]$-ийг sum-д оруул. Sum>$K$ болсон үед $l$-ийг урагшлуулж илүүдсэн хэсгийг хас. Үлдсэн window valid болсон бол $r$ дээр төгсөх $[l,r]$, [$l+1$,$r$], …, $[r,r]$ гэсэн бүх хоосон биш range valid байна."},{"type":"math","tex":"\\text{answer}\\mathrel{+}=r-l+1\\quad\\text{when all }a_i\\ge0\\text{ and }K\\ge0"},{"type":"p","text":"Nonnegative учир эхнээс нь элемент хасахад sum өсөхгүй. Өмнө хассан эхлэлүүдийг дараагийн $r$ дээр дахин харах шаардлагагүй. Zero элементтэй үед ч энэ чанар хэвээр. $K<0$ байвал nonnegative array дээр valid хоосон биш subarray огт байхгүй."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$a=[2,1,3]$, $K=3$. $r=0$ үед $\\mathrm{sum}=2$, $l=0$; нэг range тоолно.","$r=1$ үед $\\mathrm{sum}=3$; $[2,1]$, $[1]$ гэсэн хоёр range нэмнэ. Нийт $3$.","$r=2$ үед $\\mathrm{sum}=6$. $a[0]=2$-ыг хасаад $4$, $a[1]=1$-ийг хасаад $3$ болно.","$l=2$ тул $[3]$ л зөв. Нийт $4$. Negative input $[4,-3]$ дээр анхны $4$-ийг хасвал дараа нь $[4,-3]$-ийг алдах учир нөхцөлөө шалгах ёстой."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"$r$ бүрд loop дуусахад window $\\mathrm{sum}\\le K$ бөгөөд хассан эхлэлүүд $\\mathrm{sum}>K$ байсан. Nonnegative шинэ элемент нэмэхэд өмнө invalid байсан эхлэл valid болохгүй. Үлдсэн window-ийн suffix бүр sum нь window-оос ихгүй тул зөв. Иймээс $r-l+1$ нь яг $r$ дээр төгсөх valid range-ийн тоо. Эдгээр бүлгүүд төгсгөлийн индексээрээ ялгаатай тул давхар тоолохгүй."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nlong long count_subarrays(const vector<long long>& a, long long k) {\n    if (k < 0) return 0;\n    long long sum = 0, answer = 0;\n    int l = 0;\n    for (int r = 0; r < (int)a.size(); ++r) {\n        assert(a[r] >= 0);\n        sum += a[r];\n        while (sum > k) sum -= a[l++];\n        answer += r-l+1;\n    }\n    return answer;\n}"},{"type":"p","text":"count_subarrays нь нийлбэр нь $K$-ээс хэтрэхгүй хоосон биш subarray-ийн тоог буцаана. Нийлбэр болон хариунд long long ашиглана: хариу $n(n+1)/2$ хүрч болно. Nonnegative array дээр нийлбэр нь яг $K$ байх хэсгүүдийн тоог $\\mathrm{count}(K)-\\mathrm{count}(K-1)$ гэж олно. $K<0$ үед хариу $0$."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Хоёр pointer-ийн шилжилт","Нийт $O(n)$"],["Sum window","$O(1)$ нэмэлт зай"],["Frequency window","Distinct утгуудын тоотой тэнцэх зай"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["Negative array дээр sum-based sliding window хэрэглэж нөхцөлийг батлахгүй орхих.","Window-ийг шинэчлэх үед frequency $0$ болсон утгыг distinct count-оос хасахгүй байх.","answer-ийн $O(n^{2})$ хэмжээ int-д багтана гэж бодох.","Empty window үед $r-l+1=0$ гарч болохыг буруу алдаа гэж үзэх."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["$a=[0,0,0]$, $K=0$ үед яагаад $6$ гарахыг тайлбарла.","Brute force-аар жижиг array-ийн бүх range-ийг тоолоод function-тай харьцуул.","Хамгийн ихдээ хоёр distinct утгатай longest window-ийн state-ийг тодорхойл."]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"beginner","order":5,"translations":{"en":{"title":"Two pointers & sliding window","summary":"Move two boundaries forward to process ranges in linear time when the window condition is monotonic.","prerequisites":"Arrays, sums and half-open ranges.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"Two pointers track positions $l$ and $r$. A sliding window also maintains a summary of the current range, such as its sum or element frequencies. Nested loops can still take $O(n)$ time if each pointer advances at most $n$ times."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"For a nonnegative array, extending a window never reduces its sum. This allows counting the subarrays whose sum is at most $K$. Negative elements break this reasoning: adding another element could make an invalid window valid again."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"Include each new right element in the sum. While the sum exceeds $K$, remove $a[l]$ and advance $l$. Once the window is valid, every starting position from $l$ through $r$ gives a valid subarray ending at $r$. Add $r$-$l+1$ to the total count. The left boundary never moves backward."},{"type":"math","tex":"\\text{answer}\\mathrel{+}=r-l+1\\quad\\text{when all }a_i\\ge0\\text{ and }K\\ge0"},{"type":"p","text":"The code uses an inclusive right loop index and adds $r$-$l+1$ to the answer. Input values must be nonnegative. If $K$ is negative, no nonempty subarray qualifies and the function returns zero. Other window problems need their own invariant; the same loop is not a universal template."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["Use $a=[2,1,3,1]$ and $K=4$.","After reading $2$ and $1$, the window sum is $3$ and its length is $2$.","Adding $3$ makes the sum $6$. Remove $2$ and move $l$ forward: the sum becomes $4$.","Adding the final $1$ requires another removal. The valid-start counts for the four right endpoints are $1$,$2$,$2$,$2$, giving $7$ subarrays in total."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"For a fixed right endpoint, any left endpoint discarded because its sum was too large remains unsuitable as later nonnegative elements are appended. After shrinking, exactly the starts from $l$ through $r$ are valid for this right endpoint. Each nonempty subarray has a unique right endpoint, so summing these counts counts every valid subarray once."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nlong long count_subarrays(const vector<long long>& a, long long k) {\n    if (k < 0) return 0;\n    long long sum = 0, answer = 0;\n    int l = 0;\n    for (int r = 0; r < (int)a.size(); ++r) {\n        assert(a[r] >= 0);\n        sum += a[r];\n        while (sum > k) sum -= a[l++];\n        answer += r-l+1;\n    }\n    return answer;\n}"},{"type":"p","text":"Use long long for both the running sum and the answer: the count can reach $n$($n+1$)/$2$. Empty input returns a count of zero. For arbitrary signed values, consider prefix sums and a suitable ordered data structure instead of this invariant."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Pointer movements","$O(n)$ total time"],["Running sum and boundaries","$O(1)$ extra space"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Using the sum invariant on signed arrays.","Forgetting to remove the outgoing element from the summary.","Mixing inclusive and half-open lengths.","Resetting $l$ for every right endpoint and losing linear complexity."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Trace an all-zero array with $K=0$.","Construct a counterexample containing negative values.","Adapt the window to at most $k$ distinct values using a frequency map."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"bfs","title":"BFS — өргөнөөр хайх","category":"Graphs","level":"Анхан шат","aliases":"bfs breadth first search grid graph unweighted shortest path өргөнөөр богино зам queue","summary":"Жингүй graph эсвэл grid дээр хамгийн цөөн ирмэгтэй замыг queue-аар олох.","prerequisites":"Graph, adjacency list, queue.","related":["monotonic-stack","dfs","dijkstra"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"BFS нь эхлэх $s$ оройгоос graph-ийг үе давхаргаар нь үздэг. Эхний үеийн зай $0$, дараагийнх $1$ гэх мэт байна. Энд зайг туулсан edge-ийн тоогоор хэмжинэ. Тиймээс энгийн BFS-ийн shortest path нь бүх edge ижил өртөгтэй үед зөв байдаг. Queue нь оройнуудыг олдсон дарааллаар нь боловсруулах үүрэгтэй."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Жингүй graph, дөрвөн чиглэлтэй grid, нэг алхам ижил үнэтэй puzzle-ийн хамгийн бага алхамд хэрэглэ. Өртөг $0/1$ бол $0$-$1$ BFS, дурын nonnegative weight бол Dijkstra хэрэгтэй. Олон эхлэлтэй үед бүх source-ийг зай $0$-той queue-д оруулаад multi-source BFS хийж болно."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"$\\mathrm{dist}[v]=-1$ бол хараахан олдоогүй. $s$-ийг $\\mathrm{dist}=0$ болгож queue-д хийнэ. Queue-оос $v$ авахад олдоогүй neighbor $u$-г $\\mathrm{dist}[u]=\\mathrm{dist}[v]+1$ болгож queue-д нэм. Visited тэмдэглэгээг pop хийхэд биш, queue-д нэмэх үед хий; ингэснээр нэг орой олон удаа нэмэгдэхгүй."},{"type":"math","tex":"d[u]=d[v]+1\\quad\\text{on the first discovery of }u"},{"type":"p","text":"Зам сэргээхэд $\\mathrm{parent}[u]=v$ гэж хадгал. Target-оос parent дагаж source хүрээд reverse хийнэ. Grid дээр (row,col)-ийг state болгох эсвэл row*$m$+col гэсэн index ашиглаж болно. Хана, grid-ийн хязгаар, diagonal allowed эсэхийг neighbor үүсгэх үед шалга."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$0\\to 1$, $0\\to 2$, $1\\to 3$, $2\\to 3$ гэсэн graph. Queue эхэнд $[0]$, $\\mathrm{dist}[0]=0$.","$0$-г гаргаад $1$,$2$-ыг зай $1$-тэй нэмнэ. Queue=$[1,2]$.","$1$-ээс $3$-ыг анх олоод зай $2$, $\\mathrm{parent}[3]=1$ болгоно.","$2$-оос $3$ аль хэдийн олдсон учир дахин нэмэхгүй. $0\\to 1\\to 3$ хамгийн богино замуудын нэг; $0\\to 2\\to 3$ ч мөн урт $2$."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"FIFO queue-ийн улмаас зай $k$-тэй бүх орой зай $k+1$-тэй оройгоос өмнө боловсруулагдана. $u$-г анх зай $k+1$-тэй олсон үед илүү богино зам байсан бол тэр замын өмнөх орой зай≤$k-1$-тэй байх ёстой бөгөөд өмнө нь боловсруулагдсан байх байлаа. Тэгвэл $u$ өмнө олдох байсан гэсэн зөрчил гарна. Иймээс анхны discovery зай optimal."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\npair<vector<int>,vector<int>> bfs(const vector<vector<int>>& g, int s) {\n    int n = g.size();\n    assert(0 <= s && s < n);\n    vector<int> dist(n,-1), parent(n,-1);\n    queue<int> q; q.push(s); dist[s]=0;\n    while (!q.empty()) {\n        int v=q.front(); q.pop();\n        for (int u:g[v]) if (dist[u]==-1) {\n            dist[u]=dist[v]+1; parent[u]=v; q.push(u);\n        }\n    }\n    return {dist,parent};\n}"},{"type":"p","text":"Neighbor бүрийн индекс $[0,n)$ дотор байх ёстой. Undirected graph-ийн edge-ийг adjacency list-д хоёр чиглэлд оруулна. Функц distance болон parent array-г хамтад нь буцаана. Хүрэх боломжгүй оройн зай $-1$ хэвээр үлдэх тул parent-аар нь зам сэргээхгүй."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["BFS","$O(V+E)$ хугацаа"],["$\\mathrm{dist}$, parent, queue","$O(V)$ зай"],["Adjacency list өөрөө","$O(V+E)$ зай"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["Жин өөр өөр graph дээр BFS ашиглах.","Visited-ийг queue-д нэмэхэд тэмдэглэхгүй байх.","Graph disconnected байхад нэг source-оос бүх орой хүрнэ гэж бодох.","Grid-ийн coordinate-ийг row/col сольж neighbor буруу үүсгэх."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Хүрэхгүй орой нэмээд $\\mathrm{dist}$ нь $-1$ хэвээр эсэхийг шалга.","Олон галын эхлэлтэй grid дээр cell бүрийн гал хүрэх хамгийн эрт хугацааг ол.","Parent-аас сэргээсэн замын edge-ийн тоо $\\mathrm{dist}[\\mathrm{target}]$-тай тэнцүүг батал."]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"beginner","order":6,"translations":{"en":{"title":"BFS — breadth-first search","summary":"Find shortest paths by edge count in an unweighted graph using a queue.","prerequisites":"Graphs, adjacency lists and queues.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"BFS visits vertices in layers around a start vertex $s$. The first layer has distance zero, the next has distance one, and so on. This measures the number of edges, so ordinary BFS requires unit edge costs."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use BFS for unweighted shortest paths, grid movement with equal-cost steps, and multi-source distances. For edges of cost $0$ or $1$ use $0$-$1$ BFS; for general nonnegative weights use Dijkstra."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"Initialize all distances to $-1$ and set $\\mathrm{dist}[s]=0$. Put $s$ in a queue. When processing $v$, discover every unvisited neighbor $u$, assign $\\mathrm{dist}[u]=\\mathrm{dist}[v]+1$, and enqueue it immediately."},{"type":"math","tex":"d[u]=d[v]+1\\quad\\text{on the first discovery of }u"},{"type":"p","text":"Mark a vertex when it is enqueued, rather than waiting until it is removed, to avoid duplicates. Store $\\mathrm{parent}[u]=v$ at discovery if a path is needed. A grid cell can be treated as a graph vertex."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["Take edges $0$-$1$, $0$-$2$, $1$-$3$ and $2$-$3$. Start at $0$.","The initial queue contains only $0$ at distance $0$.","Processing $0$ discovers $1$ and $2$ at distance $1$.","Processing $1$ discovers $3$ at distance $2$. Processing $2$ does not enqueue $3$ again."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"The queue processes vertices in nondecreasing distance order. When $u$ is first discovered from $v$, every shorter layer has already been processed. A shorter path to $u$ would therefore have discovered it earlier. Each vertex is enqueued once and each adjacency entry is inspected once."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\npair<vector<int>,vector<int>> bfs(const vector<vector<int>>& g, int s) {\n    int n = g.size();\n    assert(0 <= s && s < n);\n    vector<int> dist(n,-1), parent(n,-1);\n    queue<int> q; q.push(s); dist[s]=0;\n    while (!q.empty()) {\n        int v=q.front(); q.pop();\n        for (int u:g[v]) if (dist[u]==-1) {\n            dist[u]=dist[v]+1; parent[u]=v; q.push(u);\n        }\n    }\n    return {dist,parent};\n}"},{"type":"p","text":"The graph must use indices in $[0,V)$, and $s$ must be valid. A distance of $-1$ means unreachable. For an undirected edge, store both adjacency directions."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Traversal","$O(V+E)$ time"],["Queue and distance array","$O(V)$ extra space"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Applying ordinary BFS to arbitrary edge weights.","Marking vertices only when dequeued.","Omitting one direction of an undirected edge.","Treating an unreachable distance of $-1$ as a valid path length."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Trace a disconnected graph.","Store parents and reconstruct one shortest path.","Initialize several starting vertices with distance zero for multi-source BFS."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"dfs","title":"DFS — гүнээр хайх","category":"Graphs","level":"Анхан шат","aliases":"dfs depth first search гүнээр холбоост connected component traversal subtree recursion","summary":"Graph-ийн холбоост хэсгүүдийг олох, tree-г боловсруулах, recursion ба iterative traversal-ийг ойлгох.","prerequisites":"Graph, stack, visited.","related":["bfs","topological-sort","lca"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"DFS нь нэг чиглэлээр аль болох гүн явж, цааш явах боломжгүй үед буцдаг traversal арга юм. Connected component олох, tree-ийн parent байгуулах, орох ба гарах дараалал гаргах зэрэгт хэрэглэнэ. Энэ хичээлийн код recursion ашиглахгүй, explicit stack-аар undirected graph-ийн component-уудыг тэмдэглэнэ."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Undirected graph-ийн connected component, tree-ийн subtree мэдээлэл, directed graph-ийн cycle check, topological ordering зэрэгт хэрэглэ. Энгийн DFS-ийн олсон зам нь хамгийн богино байх албагүй. $n$≈$200000$ chain tree дээр recursive DFS stack overflow үүсгэж болох тул iterative хувилбар эсвэл зөвшөөрөгдсөн stack нөхцөл сонго."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"Undirected graph дээр component label-ийг анх $-1$ болго. Олдоогүй орой $s$ бүрээс DFS эхлүүлж, хүрсэн бүх оройд ижил label өг. Stack-д нэмэхдээ visited тэмдэглэвэл нэг орой нэг л удаа нэмэгдэнэ. Tree-ийн postorder calculation-д enter/exit event эсвэл preorder-ийг reverse хийсэн өөр загвар хэрэгтэй."},{"type":"math","tex":"\\text{sameComponent}(u,v)\\iff\\operatorname{component}[u]=\\operatorname{component}[v]"},{"type":"p","text":"Parent edge-ийг алгасах нь зөвхөн tree эсвэл зохих undirected cycle algorithm-ийн нэг хэсэг. Directed cycle шалгахад unvisited/active/finished гэсэн гурван төлөв хэрэгтэй; visited ганц boolean хүрэлцэхгүй. Доорх код зөвхөн undirected connected component label гаргана."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["Graph-д $0$—$1$—$2$, мөн $3$—$4$, тусгаар $5$ байг.","$0$-оос DFS эхлээд $0$,$1$,$2$-т component $0$ өгнө.","$3$ хараахан тэмдэглээгүй тул component $1$ эхэлж $3$,$4$-ийг авна.","$5$-д component $2$ өгнө. Нийт $3$ component; $1$ ба $4$ хооронд зам байхгүй."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"$s$-ээс DFS-ээр олдсон орой бүр $s$-ээс edge-үүд дагасан замтай. Нөгөө талаас $s$-ээс хүрэх орой $u$ олдоогүй үлдвэл $s\\to u$ зам дээр анх олдоогүй оройг ав. Түүний өмнөх орой олдсон учраас adjacency list-ийг үзэхэд $u$ рүү DFS шилжих ёстой. Энэ зөрчлөөс component-ийн бүх оройг яг олдог нь гарна."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nvector<int> components(const vector<vector<int>>& g) {\n    int n=g.size(), count=0;\n    vector<int> comp(n,-1);\n    for (int s=0;s<n;++s) if (comp[s]==-1) {\n        vector<int> st={s}; comp[s]=count;\n        while (!st.empty()) {\n            int v=st.back(); st.pop_back();\n            for (int u:g[v]) if (comp[u]==-1) {\n                comp[u]=count; st.push_back(u);\n            }\n        }\n        ++count;\n    }\n    return comp;\n}"},{"type":"p","text":"Explicit stack ашигласан хувилбар нь recursion stack overflow-оос сэргийлнэ. Neighbor-уудыг push хийх дарааллаас traversal өөрчлөгдөж болох ч connected component-ийн хариу ижил байна. Энэ код undirected graph-д зориулагдсан бөгөөд directed graph-ийн SCC-г олохгүй."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Бүх component traversal","$O(V+E)$ хугацаа"],["Label ба explicit stack","$O(V)$ нэмэлт зай"],["Recursive хувилбар","Worst-case $O(V)$ call stack"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["Visitedгүй cycle дээр recursion хийж infinite loop үүсгэх.","Нэг source-оос л эхлээд бусад component-ийг орхих.","DFS замыг shortest path гэж үзэх.","Directed graph-ийн SCC-г энгийн reachability label-тай андуурах."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Оройгүй graph болон ганц тусгаар оройг турш.","Tree-ийн subtree size-ийг children боловсруулсны дараа яаж нэмэх вэ?","Active орой руу чиглэсэн edge нь directed cycle үүсгэж байгааг тайлбарла."]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"beginner","order":7,"translations":{"en":{"title":"DFS — depth-first search","summary":"Explore components and traversal structure with depth-first search while keeping recursion depth under control.","prerequisites":"Graphs, stacks and visited arrays.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"DFS follows a path as far as possible before returning. It discovers connectivity, entry and exit events, and the structure of rooted trees. The sample uses an explicit stack to label connected components in an undirected graph."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use DFS for component discovery, tree traversal and many graph proofs. Recursive DFS is concise but a long chain can exhaust the process stack. Directed cycle detection requires more information than a single visited flag."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"Scan all vertices. Start a new component at every unvisited vertex, mark it immediately, and push it. Pop a vertex and push its unvisited neighbors, assigning the same component label."},{"type":"math","tex":"\\text{sameComponent}(u,v)\\iff\\operatorname{component}[u]=\\operatorname{component}[v]"},{"type":"p","text":"A simple explicit vertex stack is sufficient for connectivity. To reproduce recursive postorder or exit times, store frames with an iterator or enter/exit events. For directed reachability, do not call the resulting groups undirected connected components."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["Take edges $0$-$1$ and $1$-$2$, with vertex $3$ isolated.","Starting at $0$ reaches $1$ and $2$; label all three with component $0$.","The outer scan skips already visited vertices $1$ and $2$.","Starting at $3$ creates component $1$."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"Every vertex reached from a start lies in its connected component. Conversely, if a vertex in that component remained unvisited, the first unvisited vertex on a path from the start would have been found from a visited neighbor, a contradiction. Marking on push prevents repeated discovery."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nvector<int> components(const vector<vector<int>>& g) {\n    int n=g.size(), count=0;\n    vector<int> comp(n,-1);\n    for (int s=0;s<n;++s) if (comp[s]==-1) {\n        vector<int> st={s}; comp[s]=count;\n        while (!st.empty()) {\n            int v=st.back(); st.pop_back();\n            for (int u:g[v]) if (comp[u]==-1) {\n                comp[u]=count; st.push_back(u);\n            }\n        }\n        ++count;\n    }\n    return comp;\n}"},{"type":"p","text":"Provide both directions for undirected edges. Component labels identify membership, not a meaningful numeric ordering. An explicit stack prevents recursion overflow, but still uses memory proportional to the graph size."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Component traversal","$O(V+E)$ time"],["Labels and explicit stack","$O(V)$ extra space"],["Recursive alternative","$O(V)$ worst-case call-stack depth"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Running only from one start when the graph is disconnected.","Assuming ordinary visited flags detect all directed cycles.","Using recursion on a very long chain without checking stack limits.","Using a vertex-only stack when postorder is required."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Test an empty graph and isolated vertices.","Record explicit enter/exit events for a tree.","Explain the difference between connected components and strongly connected components."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"greedy","title":"Sorting & greedy","category":"Array ба search","level":"Дунд шат","aliases":"greedy шуналтай эрэмбэлэлт sorting interval exchange argument","summary":"Алхам бүрд нэг сонголт хийгээд эргэж өөрчлөхгүй шийдлийг exchange argument-аар батлах.","prerequisites":"Sort, comparator, optimal solution.","related":["complexity","dynamic-programming","binary-search"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"Greedy арга нь алхам бүрд тухайн үед хамгийн зөв мэт харагдах сонголтыг хийж, өмнөх шийдвэрээ буцаадаггүй. Гэхдээ зөв харагдах нь хангалтгүй: тэр сонголтыг хийсэн ч optimal хариу олох боломж хадгалагдана гэдгийг батлах ёстой. Энэ хичээлд давхцахгүй хамгийн олон interval сонгох бодлогоор exchange argument-ийг тайлбарлана."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Бодлогын structure нь хамгийн эрт дуусах, хамгийн бага үнэ, хамгийн их үлдэгдэл зэрэг сонголтыг optimal хариунд хүчээр оруулж болох үед хэрэглэнэ. Сонгосны дараа үлдсэн бодлого ижил хэлбэртэй байх нь тус болдог. Local сонголтоос global optimal руу шилжих баталгаа байхгүй бол counterexample хай. Weighted interval scheduling-д доорх greedy ерөнхийдөө тохирохгүй; DP хэрэгтэй."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"Interval-уудыг end өсөхөөр sort хий. Сонгосон сүүлийн interval-ийн end-ийг last-д хадгал. Дараагийн interval-ийн start≥last бол сонгоод last=end болго. Энэ хичээлд [start,end) interval, start<end гэж үзсэн тул нэг нь дуусах мөчид нөгөө эхэлж болно."},{"type":"math","tex":"\\text{choose }[s,e)\\text{ iff }s\\ge\\text{lastEnd}"},{"type":"p","text":"Sort comparator strict weak ordering байх ёстой: $a$.end<$b$.end, тэнцвэл $a$.start<$b$.start гэж тодорхойл. ≤ хэрэглэвэл өөрийгөө өөрөөсөө өмнө гэж үзэх зөрчил үүсгэнэ. Greedy-д нэг дүрэм тохирсон нь бусад зорилтод мөн тохирно гэсэн үг биш."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["Interval-ууд $[0,5)$, $[1,3)$, $[3,4)$, $[4,7)$. End-ээр sort хийвэл $[1,3)$, $[3,4)$, $[0,5)$, $[4,7)$.","Эхлээд $[1,3)$-ыг сонгоно. last=$3$.","$[3,4)$-ийг сонгоно. $[0,5)$ нь overlap тул алгасна.","$[4,7)$-ийг сонгоод нийт $3$. Эрт эхэлдэг $[0,5)$-ыг сонгосон бол энэ жишээнд зөвхөн нэг interval авч болно."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"g нь хамгийн эрт дуусах interval, optimal шийдлийн эхний interval o байг. g.end≤o.end тул o-г g-ээр сольсон ч дараагийн interval-уудтай overlap шинээр үүсэхгүй. Interval-ийн тоо хэвээр. Иймээс g-г агуулсан optimal шийдэл байдаг. g-ийн дараах үлдсэн interval-ууд дээр мөн адил солилт хийж, сонголт бүр optimal шийдэлтэй нийцэхийг induction-аар батална."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nint max_intervals(vector<pair<long long,long long>> intervals) {\n    sort(intervals.begin(), intervals.end(), [](auto a, auto b) {\n        if (a.second != b.second) return a.second < b.second;\n        return a.first < b.first;\n    });\n    long long last = LLONG_MIN;\n    int answer = 0;\n    for (auto [s,e] : intervals) {\n        assert(s < e);\n        if (s >= last) { ++answer; last = e; }\n    }\n    return answer;\n}"},{"type":"p","text":"Pair-ийн first нь эхлэх, second нь дуусах байрлал юм. Interval бүр эерэг урттай, жингүй байна. Зорилго нь сонгосон interval-ийн тоог хамгийн их болгох. $[s,e)$ тэмдэглэгээгээр дуусах байрлал багтахгүй тул өмнөх interval дууссан цэгээс дараагийнх эхэлж болно."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Sort","$O(n \\log  n)$"],["Greedy scan","$O(n)$"],["Function-ийн interval copy","$O(n)$ зай"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["Хэдэн жишээнд таарсан учраас greedy зөв гэж дүгнэх.","Shortest interval сонгох зэрэг баталгаагүй дүрмийг цээжлэх.","Weighted variant-д энэ greedy-г шууд хэрэглэх.","Comparator-д ≤ ашиглах эсвэл overflow үүсэх subtraction-оор харьцуулах."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Earliest-start ба shortest-length дүрэм тус бүрд counterexample зохио.","$n\\le 15$ үед бүх subset-ийг шалгаж greedy-ийн хариутай тулга.","Яагаад эхний interval-ийг солиход дараагийн сонголтууд боломжтой хэвээр вэ гэдгийг зураггүйгээр тайлбарла."]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"intermediate","order":8,"translations":{"en":{"title":"Sorting & greedy","summary":"Make locally chosen decisions only when an exchange argument proves that they preserve an optimum.","prerequisites":"Sorting, intervals and proof by exchange.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"A greedy algorithm commits to a choice without exploring every alternative. A convincing intuition is insufficient: prove that some optimal solution can make the same first choice. The example selects the largest number of nonoverlapping intervals."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"For unweighted interval scheduling, choose the interval with the earliest finishing time. A short duration or early start is not enough. Weighted scheduling is a different problem and generally requires DP."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"Sort intervals by their right endpoints. Track the finish of the last selected interval. Accept an interval when its left endpoint is at least that finish. Interpret intervals as $[l,r)$, so touching endpoints are allowed."},{"type":"math","tex":"\\text{choose }[s,e)\\text{ iff }s\\ge\\text{lastEnd}"},{"type":"p","text":"Equal finishing times may be processed in any order under the stated contract. The greedy choice maximizes the space left for later intervals. It does not optimize arbitrary weights."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["Take $[1,4)$, $[2,3)$, $[3,5)$ and $[5,7)$.","Sorting by finish puts $[2,3)$ first. Select it.","Select $[3,5)$, because its beginning equals the previous finish.","Then select $[5,7)$. The answer is $3$ intervals."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"Let g be the earliest-finishing interval and let o be the first interval of an optimal solution. Replace o with g. Since g finishes no later, all later intervals remain feasible and the number selected is unchanged. Repeat the argument on the remaining suffix."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nint max_intervals(vector<pair<long long,long long>> intervals) {\n    sort(intervals.begin(), intervals.end(), [](auto a, auto b) {\n        if (a.second != b.second) return a.second < b.second;\n        return a.first < b.first;\n    });\n    long long last = LLONG_MIN;\n    int answer = 0;\n    for (auto [s,e] : intervals) {\n        assert(s < e);\n        if (s >= last) { ++answer; last = e; }\n    }\n    return answer;\n}"},{"type":"p","text":"The function returns a count, rather than the chosen interval list. Store an interval when accepting it if reconstruction is needed. The input must contain valid positive-length intervals."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Sort intervals","$O(n \\log  n)$ time"],["Selection scan","$O(n)$ time"],["Storage","$O(n)$ for the interval input; scan uses $O(1)$ extra space"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Choosing the earliest start instead of the earliest finish.","Applying the unweighted proof to weighted intervals.","Using a strict comparison when touching intervals are allowed.","Claiming correctness from examples alone."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Find a counterexample to selecting the shortest interval.","Modify the scan to return the chosen intervals.","Explain why assigning values to intervals leads to weighted-interval DP."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"monotonic-stack","title":"Stack, queue & monotonic stack","category":"Data structures","level":"Дунд шат","aliases":"stack queue deque monotonic stack next greater next smaller стек дараалал","summary":"LIFO/FIFO ялгааг ойлгож, monotonic stack-аар nearest greater элемент-ийг нийт $O(n)$-д олох.","prerequisites":"Array, loop, amortized complexity.","related":["two-pointers","bfs","complexity"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"Monotonic stack нь индексүүдийг утгын тодорхой эрэмбээр хадгалдаг. Энэ хичээлд элемент бүрийн баруун талд байгаа хамгийн ойрын, түүнээс strictly greater элементийн индексийг олно. Stack-д хариу нь хараахан олдоогүй индексүүд байна. Шинэ утга stack-ийн орой дахь утгаас их бол тэр индексийн хариуг тогтоож pop хийнэ. Тэнцүү утгыг хасахгүй тул stack-ийн утгууд доороос дээш өсөхгүй эрэмбэтэй үлдэнэ"}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Next greater/smaller элемент, histogram-ийн хамгийн том rectangle, зарим contribution бодлогод monotonic stack тохирно. Sliding window minimum/maximum-д хоёр талаасаа гаргах хэрэгтэй тул monotonic deque ашиглана. Priority queue нь хамгийн бага/их элемент-ийг гаргах heap бөгөөд энгийн queue-ийн FIFO дүрэмтэй адил биш."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"Зүүнээс баруун руу scan хийхэд stack-д next strictly greater нь олдоогүй индексүүдийг хадгал. Шинэ $a[i]$ нь top-ын утгаас их бол тухайн top-ын хариу $i$. Түүнийг pop хийгээд дахин шалгана. Эцэст нь $i$-г push хийнэ. Stack-ийн утгууд доороос дээш nonincreasing хэвээр үлдэнэ."},{"type":"math","tex":"\\operatorname{nextGreater}(j)=\\min\\{i>j\\mid a_i>a_j\\}"},{"type":"p","text":"Index хадгалах нь хариу бичих болон зай тооцоход хэрэгтэй. Strictly greater учир equal утгыг pop хийхгүй. Greater-or-equal хүсвэл comparison-ийг өөрчилнө. Ижил утгуудын дүрэм contribution тоолох бодлогод давхар тоололт үүсгэж болох тул хоёр талын strict/non-strict заагийг зориуд сонго."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$a=[2,1,3,3]$. $i=0$: stack=$[0]$.","$i=1$ дээр $1$ нь $2$-оос их биш: stack=$[0,1]$.","$i=2$ дээр $3>1$ тул $\\mathrm{answer}[1]=2$; мөн $3>2$ тул $\\mathrm{answer}[0]=2$. Stack=$[2]$.","$i=3$ дээр $3>3$ биш: stack=$[2,3]$. Эдгээрт дараагийн strictly greater байхгүй тул $-1$. Хариу $[2,2,-1,-1]$."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"$j$ stack-д үлдсэн нь $j$-ээс хойш одоог хүртэл greater элемент байгаагүй гэсэн үг. $i$ анх $a[i]>a[j]$ болж pop хийх үед $i$ нь хамгийн ойрын greater. Үүний өмнө ийм элемент байсан бол $j$ аль хэдийн pop болсон байх ёстой. Index бүр нэг удаа push, нэг удаа pop хийгдэх учир nested while-ийн нийт үйлдэл $O(n)$."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nvector<int> next_greater(const vector<long long>& a) {\n    vector<int> answer(a.size(), -1), st;\n    for (int i = 0; i < (int)a.size(); ++i) {\n        while (!st.empty() && a[st.back()] < a[i]) {\n            answer[st.back()] = i;\n            st.pop_back();\n        }\n        st.push_back(i);\n    }\n    return answer;\n}"},{"type":"p","text":"Буцах array нь утга бус, индекс хадгална. $-1$ нь дараагийн strictly greater элемент байхгүй гэсэн үг. vector-ийн back, push_back, pop_back үйлдлүүдээр LIFO stack хэрэгжүүлсэн. Тэнцүү утгууд хариу болохгүй учраас харьцуулалт strictly greater хэвээр байна."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Next greater scan","$O(n)$ amortized хугацаа"],["Stack ба answer","$O(n)$ зай"],["Queue/deque төгсгөлийн push/pop","Ердийн хэрэглээнд $O(1)$"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["While loop бүр $O(n)$ тул нийт $O(n^{2})$ гэж буруу дүгнэх.","Index-ийн оронд value хадгалаад duplicate-уудыг ялгаж чадахгүй болох.","Strict > нөхцөлд ≥ comparison ашиглах.","Empty stack дээр back/top дуудах."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Next smaller элемент олохоор comparison-ийг өөрчил.","Бүх утга ижил array-ийн хариуг урьдчилан хэл.","Fixed $k$ window maximum-д deque-ийн урдаас ямар index-ийг хасах ёстойг тайлбарла."]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"intermediate","order":9,"translations":{"en":{"title":"Stack, queue & monotonic stack","summary":"Find the next strictly greater element by maintaining a stack of unanswered indices.","prerequisites":"Stacks, arrays and amortized analysis.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"A monotonic stack keeps candidate indices in a sorted value order. This implementation finds the first strictly greater element to the right of each position. The stack contains indices whose answer has not yet been found; their values are nonincreasing from bottom to top."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use it for nearest greater or smaller elements, histogram boundaries and contribution counting. Choose strict or non-strict comparison intentionally, especially when duplicate values occur."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"Scan left to right. While $a[i]$ is greater than the value at the top index $j$, set $\\mathrm{answer}[j]=i$ and pop $j$. After resolving all smaller values, push $i$. Equal values remain on the stack because the target is strictly greater."},{"type":"math","tex":"\\operatorname{nextGreater}(j)=\\min\\{i>j\\mid a_i>a_j\\}"},{"type":"p","text":"Store indices so answers and distances can be recovered. Remaining indices have no greater element to their right and retain $-1$. For a greater-or-equal variant, the pop comparison changes."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["Take $a=[2,1,3,3]$. Initially the stack is empty.","Push indices $0$ and $1$: the stack values are $[2,1]$.","At index $2$, value $3$ resolves both earlier indices, setting their answers to $2$.","At index $3$, the equal value does not resolve index $2$. The final answer is $[2,2,-1,-1]$."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"An index $j$ stays in the stack until the first later value greater than $a[j]$ is encountered. Earlier scanned values did not qualify, so the current index is exactly the nearest qualifying one. Each index is pushed once and popped at most once, proving linear total work."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nvector<int> next_greater(const vector<long long>& a) {\n    vector<int> answer(a.size(), -1), st;\n    for (int i = 0; i < (int)a.size(); ++i) {\n        while (!st.empty() && a[st.back()] < a[i]) {\n            answer[st.back()] = i;\n            st.pop_back();\n        }\n        st.push_back(i);\n    }\n    return answer;\n}"},{"type":"p","text":"The implementation returns indices, not values. A return value of $-1$ means no qualifying element. It uses vector as a LIFO stack. Equality is deliberately excluded by the strict comparison."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Complete scan","$O(n)$ time"],["Stack and result","$O(n)$ space"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Using the wrong comparison for duplicate values.","Returning a greater value instead of its nearest index.","Leaving answered indices in the stack.","Multiplying inner-loop worst cases instead of counting total pushes and pops."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Trace strictly increasing and decreasing arrays.","Modify the comparison to find the next greater-or-equal element.","Use two monotonic-stack scans to derive histogram boundaries."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"dsu","title":"Disjoint Set Union — DSU","category":"Data structures","level":"Дунд шат","aliases":"dsu union find холбоост компонент disjoint set path compression","summary":"Оройнуудын бүлгийг merge хийж, хоёр орой нэг component-д байгаа эсэхийг хурдан шалгах.","prerequisites":"Tree parent, connected component.","related":["dfs","greedy","fenwick-tree"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"DSU нь хоорондоо огтлолцохгүй бүлгүүдийг parent tree-үүдээр төлөөлдөг. Бүлэг бүр нэг root-той. $\\mathrm{find}(v)$ нь $v$-ийн бүлгийн төлөөлөгчийг, $\\mathrm{unite}(a,b)$ нь хоёр бүлгийг нэгтгэх үйлдлийг өгнө. Төлөөлөгчийн индекс нь бүлгийн хамгийн бага элемент гэсэн утгагүй; энэ нь зөвхөн дотоод зохион байгуулалтын сонголт юм."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Edge нэмэгдэхэд connectivity query асуух, Kruskal MST, component size хадгалахад тохирно. Энгийн DSU нь edge устгах, component доторх замыг сэргээх, distance олох үйлдлийг шууд дэмжихгүй. Deletion хэрэгтэй бол offline processing, rollback DSU эсвэл өөр бүтэц шаардаж болно."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"Path compression нь find хийсэн орой бүрийг root рүү ойртуулна. Union by size нь жижиг tree-ийн root-ийг том tree-ийн root дор холбоно. Энэ хоёр optimization хамт хэрэглэхэд олон үйлдлийн amortized өртөг inverse Ackermann $\\alpha(n)$, практикт маш бага боловч $O(1)$ гэсэн формал баталгаа биш."},{"type":"math","tex":"\\operatorname{same}(a,b)\\iff\\operatorname{find}(a)=\\operatorname{find}(b)"},{"type":"p","text":"Size мэдээлэл root дээр л зөв. unite эхлээд хоёр root-ийг олж, ижил бол false буцаана. Merge амжилттай бол том root-ийн size дээр жижиг root-ийн size-ийг нэм. Шинэ root-д аль нэмэлт мэдээлэл шилжихийг тус бүрд тодорхойл."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$5$ тусдаа орой: sizes бүгд $1$.","$\\mathrm{unite}(0,1)$ хийвэл {$0$,$1$} хэмжээ $2$ болно.","$\\mathrm{unite}(2,3)$, дараа $\\mathrm{unite}(1,3)$ хийвэл {$0$,$1$,$2$,$3$} хэмжээ $4$.","$\\mathrm{find}(0)==\\mathrm{find}(2)$ true. $\\mathrm{unite}(0,2)$ дахин хийхэд бүлэг өөрчлөгдөхгүй, false буцна. $4$ тусдаа хэвээр."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"Эхэнд орой бүр тусдаа component. Unite нь зөвхөн өөр root-уудыг холбодог учир хоёр component яг нэг болно, бусад component өөрчлөгдөхгүй. Path compression зөвхөн тухайн оройн аль хэдийн хүрдэг root рүү parent өөрчилдөг тул бүлгийн гишүүнчлэл хадгалагдана. Size-ийг root-уудын нийлбэрээр шинэчлэх нь давхар тоолохгүй."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct DSU {\n    vector<int> p,sz;\n    DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}\n    int find(int v){\n        while(v!=p[v]){p[v]=p[p[v]];v=p[v];}\n        return v;\n    }\n    bool unite(int a,int b){\n        a=find(a);b=find(b);\n        if(a==b)return false;\n        if(sz[a]<sz[b])swap(a,b);\n        p[b]=a;sz[a]+=sz[b];return true;\n    }\n    int size(int v){return sz[find(v)];}\n};"},{"type":"p","text":"DSU-г $n$ элементтэй байгуулж, find-ээр төлөөлөгчийг, unite-аар нэгтгэлийг, size-аар бүлгийн хэмжээг олно. Индексүүд $[0,n)$ дотор байна. Энэ find нь iterative path halving ашигладаг. Rollback нэмэх бол parent-ийн өөрчлөлт бүрийг бүртгэж сэргээх, эсвэл compression ашиглахгүй өөр хувилбар сонгох шаардлагатай."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Initialization","$O(n)$"],["$m$ unite/find","$O((n+m) \\alpha(n))$ гэж дээд хязгаарлаж болно"],["Parent ба size","$O(n)$ зай"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["$\\mathrm{sz}[v]$-г root биш үед унших.","Root id-г тогтвортой component ID гэж хадгалах; merge дараа өөрчлөгдөж болно.","Same component дээр unite хийхэд size дахин нэмэх.","Graph path эсвэл edge deletion DSU өөрөө өгнө гэж бодох."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Component-ийн тоог амжилттай unite бүрд нэгээр бууруул.","Edge нэмэхэд cycle үүсэж байгаа эсэхийг unite-ийн return-оос илрүүл.","$n\\le 20$ random edge-үүдийн connectivity-г BFS болон DSU-гаар тулга."]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"intermediate","order":10,"translations":{"en":{"title":"Disjoint Set Union — DSU","summary":"Maintain disjoint components under merges with path compression and union by size.","prerequisites":"Trees, arrays and connectivity.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"DSU represents each component as a parent tree. $\\mathrm{find}(v)$ returns its representative root; $\\mathrm{unite}(a,b)$ joins two components. A representative is an implementation detail and need not be the smallest vertex."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use DSU for incremental connectivity and Kruskal’s minimum spanning tree algorithm. Ordinary DSU does not support arbitrary edge deletion. Offline deletion or rollback techniques require a different design."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"During find, shorten parent paths. When merging roots, attach the smaller component below the larger one. Keep component sizes only at roots. The sample uses iterative path halving."},{"type":"math","tex":"\\operatorname{same}(a,b)\\iff\\operatorname{find}(a)=\\operatorname{find}(b)"},{"type":"p","text":"Combining compression and size balancing gives amortized inverse-Ackermann cost $\\alpha(n)$ per operation, rather than a formal constant-time guarantee. Rollback DSU usually avoids path compression so that changes can be undone predictably."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["Begin with components {$0$}, {$1$}, {$2$}, {$3$}.","$\\mathrm{unite}(0,1)$ joins two singleton components.","$\\mathrm{unite}(2,3)$, then $\\mathrm{unite}(1,2)$, connects all four vertices.","$\\mathrm{find}(0)==\\mathrm{find}(3)$ is now true and $\\mathrm{size}(0)$ returns $4$."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"Initially each parent tree represents exactly one singleton. Joining two roots merges precisely their vertex sets. Compression changes only the route to an existing root, so membership stays unchanged. Size balancing limits height; compression improves the amortized bound further."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct DSU {\n    vector<int> p,sz;\n    DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}\n    int find(int v){\n        while(v!=p[v]){p[v]=p[p[v]];v=p[v];}\n        return v;\n    }\n    bool unite(int a,int b){\n        a=find(a);b=find(b);\n        if(a==b)return false;\n        if(sz[a]<sz[b])swap(a,b);\n        p[b]=a;sz[a]+=sz[b];return true;\n    }\n    int size(int v){return sz[find(v)];}\n};"},{"type":"p","text":"Construct DSU $d$($n$). Compare representatives for connectivity and call $\\mathrm{size}(v)$ for component size. Indices must be in $[0,n)$. Do not assume the representative remains fixed after a merge."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Initialization","$O(n)$ time"],["$m$ find/unite operations","$O((n+m) \\alpha(n))$ upper bound"],["Parent and size arrays","$O(n)$ space"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Reading size from a nonroot without finding its root.","Treating the representative as the minimum element.","Expecting ordinary DSU to handle deletions.","Adding rollback to a compressing find without logging every change."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Merge the same pair twice and check the size.","Count connected components after every successful union.","Use DSU to explain why Kruskal rejects cycle-forming edges."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"fenwick-tree","title":"Fenwick tree — Binary Indexed Tree","category":"Data structures","level":"Дунд шат","aliases":"fenwick tree bit binary indexed tree point update range sum","summary":"Point add ба prefix/range sum-ийг $O(\\log  n)$-д хийдэг компакт data structure.","prerequisites":"Prefix sum, binary representation, $1$-based indexing.","related":["prefix-sums","hash-compression","segment-tree"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"Prefix sum нь static array-ийн query-г хурдан хариулдаг ч point update хийхэд олон prefix өөрчлөгдөнө. Fenwick tree нь нийлбэрүүдийг тусгай урттай block-уудад хадгалж, query болон update бүрд $O(\\log  n)$ block л үздэг. Энэ хичээлд point add update болон prefix, range sum query-г авч үзнэ."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Dynamic array range sum, inversion count, compressed coordinate-ийн frequency хадгалахад тохирно. Point assign хийхэд шинэ−хуучин $\\mathrm{delta}$-г тооцох ёстой. Ерөнхий range minimum, arbitrary merge operation-д segment tree илүү тохиромжтой. Two Fenwick tree-аар range add + range sum зэрэг extension хийж болдог ч доорх код түүнийг хэрэгжүүлээгүй."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"Дотоод index $i$ нь $1$-based. $\\mathrm{lowbit}(i)$=$i$&−$i$ нь сүүлийн $1$ bit-ийн байрлалын утга. $\\mathrm{bit}[i]$ нь $i$ дээр төгсөх $\\mathrm{lowbit}(i)$ урттай block-ийг хадгална. Prefix query-д $i$−=$\\mathrm{lowbit}(i)$, update-д $i$+=$\\mathrm{lowbit}(i)$ гэж явна. Гаднаас дуудах үйлдлүүд нь $0$-based бөгөөд $\\mathrm{prefix}(r)$ нь $[0,r)$-ийн sum."},{"type":"math","tex":"\\operatorname{lowbit}(i)=i\\mathbin{\\&}(-i),\\qquad \\operatorname{sum}(l,r)=\\operatorname{prefix}(r)-\\operatorname{prefix}(l)"},{"type":"p","text":"Query index-ийн хамгийн бага $1$ bit-ийг алхам бүрд арилгана; update нь дараагийн том хамрах block руу шилжинэ. $\\mathrm{bit}[0]$-г ашиглахгүй. Internal $i=0$ дээр update эхэлбэл $\\mathrm{lowbit}(0)$=$0$ тул loop ахихгүй."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$8$ элемент-ийн internal $\\mathrm{bit}[6]$ нь $\\mathrm{lowbit}(6)$=$2$ тул public index $[4,6)$-ийг хадгална.","$\\mathrm{prefix}(7)$-д $\\mathrm{bit}[7]+\\mathrm{bit}[6]+\\mathrm{bit}[4]$ авна: уртууд $1+2+4=7$.","Public index $2$ дээр +$5$ хийхэд internal $i=3$,$4$,$8$ block-ууд өөрчлөгдөнө.","$a=[2,1,3,4]$ үед $\\mathrm{sum}(1,4)=8$; index $2$ дээр +$5$ хийсний дараа $13$."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"Prefix query-ийн block-ууд нь хоорондоо давхцахгүй, нийлээд яг $[0,r)$-ийг бүрхэнэ. $i$-ээс $\\mathrm{lowbit}(i)$-ийг хасахад үлдсэн prefix-ийн төгсгөл рүү шилждэг. Update-ийн visited block бүр тухайн элемент-ийг агуулдаг бөгөөд бусад block түүнийг агуулахгүй. Иймээс update дараа block sum invariant хадгалагдаж, query зөв хэвээр."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct Fenwick {\n    int n; vector<long long> bit;\n    Fenwick(int n):n(n),bit(n+1,0){}\n    void add(int index,long long delta){\n        assert(0<=index && index<n);\n        for(int i=index+1;i<=n;i+=i&-i)bit[i]+=delta;\n    }\n    long long prefix(int r)const{\n        assert(0<=r && r<=n);\n        long long s=0;for(int i=r;i>0;i-=i&-i)s+=bit[i];return s;\n    }\n    long long sum(int l,int r)const{\n        assert(0<=l && l<=r && r<=n);return prefix(r)-prefix(l);\n    }\n};"},{"type":"p","text":"Fenwick tree-г $n$ элементтэй байгуулж, анхны утга бүрээр point add хийнэ. Range sum нь $[l,r)$ дээр ажиллана. Assign update хийхдээ хуучин утга $a[i]$-г хадгалж, tree-д $x-a[i]$ нэмээд, хадгалсан утгаа $x$ болгож солино. Ингэснээр add үйлдлээр assignment хэрэгжүүлнэ."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Add ба prefix/range sum","$O(\\log  n)$"],["$n$ add-аар build","$O(n \\log  n)$"],["bit array","$O(n)$ зай"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["Public $0$-based index-ийг internal $1$-based loop-той холих.","Assign value-г $\\mathrm{delta}$ гэж нэмж хуучин утгыг давхар тоолох.","Prefix($r$) нь inclusive $r$ хүртэл гэж эндүүрэх.","Negative frequency байхад Fenwick дээр kth order statistic search monotonic байна гэж үзэх."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Prefix($0$), $\\mathrm{sum}(l,l)$, бүтэн range-ийн sum-ийг турш.","Random add/query-г vector дээрх naive sum-тай тулга.","Compression + Fenwick-ээр inversion count хийхэд query нь strictly smaller эсвэл larger алийг тоолох ёстой вэ?"]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"intermediate","order":11,"translations":{"en":{"title":"Fenwick tree — Binary Indexed Tree","summary":"Combine point additions with prefix and range sums in logarithmic time.","prerequisites":"Prefix sums, binary indices and arrays.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"A static prefix array makes queries fast but a point update changes many entries. A Fenwick tree stores sums for carefully chosen blocks. Both a point addition and a prefix query touch only $O(\\log  n)$ blocks."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use this sum-based version when operations alternate between adding to one element and querying a range sum. Range minimum and arbitrary assignment require different logic; an assignment can be converted to a $\\mathrm{delta}$ if the old value is stored."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"Internally use $1$-based indices. $\\mathrm{lowbit}(i)$=$i$&(-$i$) is the value of the lowest set bit. $\\mathrm{bit}[i]$ stores the block of length $\\mathrm{lowbit}(i)$ ending at $i$. A prefix query subtracts $\\mathrm{lowbit}$; an update adds it."},{"type":"math","tex":"\\operatorname{lowbit}(i)=i\\mathbin{\\&}(-i),\\qquad \\operatorname{sum}(l,r)=\\operatorname{prefix}(r)-\\operatorname{prefix}(l)"},{"type":"p","text":"The public API is $0$-based and $\\mathrm{prefix}(r)$ returns the sum on $[0,r)$. range sum is the difference of two prefixes. Negative values are supported for sums, but order-statistic search needs additional assumptions."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["For $a=[2,1,3,4]$, build the tree by adding each value.","$\\mathrm{prefix}(3)$ returns $6$, the sum of the first three elements.","add($1$,$5$) changes the logical array to $[2,6,3,4]$.","$\\mathrm{sum}(1,4)$ now returns $13$."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"The blocks visited by a prefix query are disjoint and exactly partition the requested prefix. A point update visits precisely the stored blocks containing that point. Keeping those block sums correct therefore keeps every prefix and range query correct."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct Fenwick {\n    int n; vector<long long> bit;\n    Fenwick(int n):n(n),bit(n+1,0){}\n    void add(int index,long long delta){\n        assert(0<=index && index<n);\n        for(int i=index+1;i<=n;i+=i&-i)bit[i]+=delta;\n    }\n    long long prefix(int r)const{\n        assert(0<=r && r<=n);\n        long long s=0;for(int i=r;i>0;i-=i&-i)s+=bit[i];return s;\n    }\n    long long sum(int l,int r)const{\n        assert(0<=l && l<=r && r<=n);return prefix(r)-prefix(l);\n    }\n};"},{"type":"p","text":"Construct Fenwick f($n$). Build with f.add($i$,$a[i]$). To assign a new value $x$, add $x$-$a[i]$ and update the separately stored original value. Check index bounds before calling the API."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Point add and prefix/range query","$O(\\log  n)$ time"],["Build with $n$ additions","$O(n \\log  n)$ time"],["Tree array","$O(n)$ space"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Using internal $1$-based indices as public array positions.","Attempting an internal update at index zero, which never advances.","Assigning a value by adding the full value instead of the $\\mathrm{delta}$.","Mixing inclusive and half-open queries."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Compare random operations against a naive array.","Implement point assignment by retaining old values.","Derive two-Fenwick range-add/range-sum formulas."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"segment-tree","title":"Segment tree","category":"Data structures","level":"Дунд шат","aliases":"segment tree range sum min max point update мод interval query","summary":"Range-ийн aggregate-ийг хадгалж point assign ба range query-г $O(\\log  n)$-д хийх.","prerequisites":"Array, binary tree, prefix sum.","related":["fenwick-tree","sparse-table","prefix-sums"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"Segment tree нь array-г хэсгүүдэд хувааж, хэсэг бүрийн нийлбэр зэрэг нэгтгэсэн мэдээллийг хадгалдаг. Leaf нь нэг элемент, дотоод node нь хоёр child-ийн хариуг merge хийсэн утга байна. Sum, min, max, gcd зэрэг associative үйлдэл тохирно. Аль ч node-ийн утга зөв байхын тулд child-уудын утга болон merge дүрэм зөв байх ёстой."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Point update-тэй $\\mathrm{sum}$/min/max query, custom aggregate-д хэрэглэ. Static sum-д prefix sum энгийн; static min-д sparse table байж болно. Range update-ийг $O(\\log  n)$-д хийхийн тулд $\\mathrm{lazy}$ propagation гэсэн тусдаа invariant хэрэгтэй. Энэ хичээлийн код зөвхөн point assign + range sum."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"Leaf-үүдийг power-of-two size-тай суурийн хоёр дахь хагаст байрлуулна. Query $[l,r)$-ийг leaf index рүү шилжүүлж, зүүн зааг right child бол тэр node-ийг авч $l$++, баруун зааг odd бол --$r$ node-ийг авна. Дараа нь хоёр заагийг parent руу /$2$ хийнэ."},{"type":"math","tex":"t[v]=t[2v]+t[2v+1],\\qquad \\operatorname{identity}_{\\mathrm{sum}}=0"},{"type":"p","text":"Merge-ийн associative чанар хэсгүүдийг янз бүрийн бүлэглэлээр нийлүүлэх боломж өгдөг. Хоосон query-ийн identity нь sum-д $0$, min-д +∞. Noncommutative merge, жишээ нь string concatenation-д зүүн ба баруун accumulator-ийн order-ийг хадгалах ёстой; sum дээр тэр ялгаа харагддаггүй."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$a=[2,1,3,4]$. Хүүхдийн sums: $[0,2)=3$, $[2,4)=7$; root=$10$.","$[1,4)$ query нь $a[1]=1$ ба $[2,4)$-ийн $7$-г авч $8$ болно.","Index $2$-ыг $8$ болгоход leaf $3\\to 8$, $[2,4)$ sum $7\\to 12$, root $10\\to 15$.","$[1,4)$ query одоо $13$. Бусад замын node өөрчлөгдөхгүй."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"Build нь leaves-ээс дээш merge хийдэг тул node бүрийн segment sum зөв. Point assign хийхэд зөвхөн тэр leaf-ийг агуулдаг ancestor-уудын sum өөрчлөгдөнө; тэднийг дарааллаар дахин тооцох нь invariant-ийг сэргээнэ. Query нь $[l,r)$-ийг давхцахгүй бүрэн node-уудад хувааж авдаг тул тэдний sum яг хүссэн range-ийн sum."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct SegTree {\n    int n,size=1;vector<long long> t;\n    SegTree(const vector<long long>& a):n(a.size()){\n        while(size<n)size*=2;t.assign(2*size,0);\n        for(int i=0;i<n;i++)t[size+i]=a[i];\n        for(int i=size-1;i>0;i--)t[i]=t[2*i]+t[2*i+1];\n    }\n    void assign(int i,long long x){\n        assert(0<=i&&i<n);i+=size;t[i]=x;\n        for(i/=2;i>0;i/=2)t[i]=t[2*i]+t[2*i+1];\n    }\n    long long sum(int l,int r)const{\n        assert(0<=l&&l<=r&&r<=n);long long answer=0;\n        for(l+=size,r+=size;l<r;l/=2,r/=2){\n            if(l&1)answer+=t[l++];if(r&1)answer+=t[--r];\n        }\n        return answer;\n    }\n};"},{"type":"p","text":"Энэ хэрэгжүүлэлт point assignment болон $[l,r)$ range sum дэмжинэ. $n=0$ үед хоосон query-ийн нийлбэр $0$ боловч assignment хийх боломжгүй. Sum нь long long-д багтах ёстой. Min хувилбар болгохдоо merge төдийгүй identity болон padding-ийн утгыг $+\\infty$ болгож өөрчилнө."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Build","$O(n)$ хугацаа"],["Point assign / range sum","$O(\\log  n)$"],["Tree storage","$O(n)$ зай"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["Min query-ийн identity-д $0$ тавих; positive бүх range-д буруу $0$ гарна.","Range-ийн inclusive/exclusive заагийг холих.","Associative биш operation-ийг node merge болгох.","Range update хийхдээ бүх leaf update хийгээд $O(\\log  n)$ гэж мэдээлэх."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Random point assign/query-г naive array-тай тулга.","Node дээр sum ба maximum хоёрыг зэрэг хадгалдаг merge зохио.","Lazy range-add хийхэд sum-д $\\mathrm{delta}$×segmentLength яагаад нэмэхийг тайлбарла."]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"intermediate","order":12,"translations":{"en":{"title":"Segment tree","summary":"Maintain an associative aggregate under point updates and interval queries.","prerequisites":"Arrays, binary trees and associative operations.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"A segment tree summarizes subranges. A leaf stores one element and an internal node combines its two children. Sum, minimum, maximum and gcd are associative operations and therefore suitable aggregates."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use it when values change and a Fenwick tree does not naturally support the required aggregate. Choose an identity element and a merge operation first. Associativity is necessary; commutativity is not."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"The iterative sum tree pads the leaf layer to a power of two. Convert $[l,r)$ to leaf indices. If $l$ is a right child, include that node and advance $l$. If $r$ is odd, decrement it and include that node. Then move both boundaries to their parents."},{"type":"math","tex":"t[v]=t[2v]+t[2v+1],\\qquad \\operatorname{identity}_{\\mathrm{sum}}=0"},{"type":"p","text":"A point assignment changes a leaf and recomputes its ancestors. For a noncommutative operation, use separate left and right accumulators in the correct order. For minimum, padding and the identity must both be positive infinity."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["Build a tree for $[2,1,3,4]$.","The root sum is $10$; $\\mathrm{sum}(1,3)$ returns $1+3=4$.","assign($2$,$8$) changes the array to $[2,1,8,4]$.","The affected ancestors are recomputed; $\\mathrm{sum}(1,3)$ is now $9$."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"Every node stores the correct result for its segment by induction from the leaves. Updating ancestors preserves that invariant. A query partitions the requested range into disjoint stored segments, so merging their results gives exactly the requested sum."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct SegTree {\n    int n,size=1;vector<long long> t;\n    SegTree(const vector<long long>& a):n(a.size()){\n        while(size<n)size*=2;t.assign(2*size,0);\n        for(int i=0;i<n;i++)t[size+i]=a[i];\n        for(int i=size-1;i>0;i--)t[i]=t[2*i]+t[2*i+1];\n    }\n    void assign(int i,long long x){\n        assert(0<=i&&i<n);i+=size;t[i]=x;\n        for(i/=2;i>0;i/=2)t[i]=t[2*i]+t[2*i+1];\n    }\n    long long sum(int l,int r)const{\n        assert(0<=l&&l<=r&&r<=n);long long answer=0;\n        for(l+=size,r+=size;l<r;l/=2,r/=2){\n            if(l&1)answer+=t[l++];if(r&1)answer+=t[--r];\n        }\n        return answer;\n    }\n};"},{"type":"p","text":"Use SegTree st($a$), st.assign($i$,$x$) and st.$\\mathrm{sum}(l,r)$. An empty array allows $\\mathrm{sum}(0,0)$, but no assignment. Aggregate totals must fit the chosen integer type."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Construction","$O(n)$ time"],["Point assignment or range query","$O(\\log  n)$ time"],["Tree storage","$O(n)$ space"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Choosing a merge that is not associative.","Using zero as the identity for minimum.","Dropping the order of a noncommutative aggregate.","Forgetting to recompute all ancestors after assignment."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Implement range minimum with the correct identity.","Test empty and single-element queries.","Store pairs of sum and maximum in each node."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"sparse-table","title":"Sparse table — static RMQ","category":"Data structures","level":"Дунд шат","aliases":"sparse table rmq static range minimum query min gcd","summary":"Өөрчлөгдөхгүй array-ийн range minimum query-г $O(1)$-д хариулах.","prerequisites":"Array, powers of two, min.","related":["segment-tree","binary-search","lca"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"Sparse table нь $1$, $2$, $4$, $8$ зэрэг power-of-two урттай range бүрийн мэдээллийг урьдчилан хадгалдаг. Range minimum query-д хүссэн хэсгийг хоёр block-оор бүрхэнэ. Block-ууд давхцаж болох ч нэг утгыг давтан min-д оруулахад хариу өөрчлөгддөггүй. Энэ шинжийг idempotence гэдэг бөгөөд $O(1)$ query-ийн гол үндэслэл юм."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Static array дээр олон RMQ, gcd, maximum query хийхэд ашигтай. Update байвал table-ийн олон утга хүчингүй болох тул segment tree сонго. Query-д хоёр overlap segment ашигладаг $O(1)$ арга нь idempotent operation шаарддаг. Sum-д overlap давхар нэмэгдэх тул энэ хувилбар тохирохгүй; prefix sum энгийн бөгөөд хурдан."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"$\\mathrm{st}[k][i]$ нь [$i$,$i+2^k$)-ийн minimum. Урт $r-l$-ийн floor(log2)-ийг $k$ гэе. Query-д [$l$,$l+2^k$) ба [$r-2^k$,$r$) segment авна. Эдгээр нь range-ээс гарахгүй бөгөөд нийлээд бүх range-ийг бүрхэнэ."},{"type":"math","tex":"\\operatorname{RMQ}(l,r)=\\min(st[k][l],st[k][r-2^k]),\\quad k=\\lfloor\\log_2(r-l)\\rfloor"},{"type":"p","text":"Хоёр segment overlap хийж болно. min($x$,$x$)=$x$ тул давхардсан элементийн нэмэр өөрчлөгдөхгүй. Log table-ийг integer recurrence-аар байгуулбал floating-point log2 rounding-оос зайлсхийнэ. Query заавал хоосон биш: log2($0$) тодорхойгүй."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$a=[5,2,7,1,6]$. Урт $2$ segment-ийн min $[2,2,1,1]$.","Урт $4$ segment-ийн min $[1,1]$.","$[1,5)$ query урт $4$ тул $[1,5)$ segment өөрөө minimum $1$.","$[0,3)$ query урт $3$, $k=1$: $[0,2)$ min=$2$ ба $[1,3)$ min=$2$. Index $1$ давхардсан ч хариу $2$ зөв."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"Build recurrence-ийн хоёр child нь parent segment-ийг overlapгүй бүрхдэг тул induction-аар st бүр зөв. Query-ийн $2^k\\le \\mathrm{len}<2^{k+1}$ учир хоёр block-ийн уртын нийлбэр len-ээс багагүй, эхнийх нь $l$-ээс, хоёр дахь нь $r$ дээр дуусдаг тул завсар үлдэхгүй. Min idempotent тул overlap хариунд нөлөөлөхгүй."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct SparseTable {\n    vector<vector<long long>> st;vector<int> lg;int n;\n    SparseTable(const vector<long long>& a):n(a.size()){\n        assert(n>0);lg.assign(n+1,0);\n        for(int i=2;i<=n;i++)lg[i]=lg[i/2]+1;\n        st.assign(lg[n]+1,vector<long long>(n));st[0]=a;\n        for(int k=1;k<(int)st.size();k++)\n            for(int i=0;i+(1<<k)<=n;i++)\n                st[k][i]=min(st[k-1][i],st[k-1][i+(1<<(k-1))]);\n    }\n    long long query(int l,int r)const{\n        assert(0<=l&&l<r&&r<=n);int k=lg[r-l];\n        return min(st[k][l],st[k][r-(1<<k)]);\n    }\n};"},{"type":"p","text":"Хоосон array болон хоосон range query-г энэ хэрэгжүүлэлт дэмжихгүй. Query нь $[l,r)$ хэсгийн minimum-ийг өгнө. Memory limit бага бол table-ийн хэмжээг byte-аар тооцно. Long long хадгалбал ойролцоогоор $8n(\\lfloor\\log_2 n\\rfloor+1)$ byte шаардлагатай."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Build","$O(n \\log  n)$"],["Nonempty min query","$O(1)$"],["Table","$O(n \\log  n)$ зай"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["Min-ийн overlap аргыг sum-д хуулж хэрэглэх.","Point update дараа table-ийг шинэчлэхгүй query хийх.","$r-l=0$ үед log table унших.","Урт $2^k$ segment төгсгөлийн index $n$-ээс хэтрэх build хийх."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Бүх $[l,r)$-ийг naive minimum-тай тулга.","Max ба gcd-д яагаад хоёр overlap block хэрэглэж болдгийг тайлбарла.","Sum-ийг overlapгүй power-of-two хэсгүүдэд хуваавал query complexity ямар болох вэ?"]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"intermediate","order":13,"translations":{"en":{"title":"Sparse table — static RMQ","summary":"Precompute power-of-two ranges to answer static idempotent queries in constant time.","prerequisites":"Arrays, powers of two and range minimum.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"A sparse table stores aggregates for all ranges of lengths $1$,$2$,$4$,$8$ and so on. For a minimum query, two possibly overlapping blocks cover the requested range. Overlap is harmless because min($x$,$x$)=$x$."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use it for a fixed array with many minimum, maximum or gcd queries. The $O(1)$ overlapping-block query requires idempotence. It cannot be used unchanged for sums, and point updates invalidate precomputed entries."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"Let $\\mathrm{st}[k][i]$ store the minimum on [$i$,$i+2^k$). For a query $[l,r)$, choose $k$=floor(log2($r$-$l$)). Combine the blocks starting at $l$ and ending at $r$."},{"type":"math","tex":"\\operatorname{RMQ}(l,r)=\\min(st[k][l],st[k][r-2^k]),\\quad k=\\lfloor\\log_2(r-l)\\rfloor"},{"type":"p","text":"Since $2^k\\le r$-$l<2^{k+1}$, the blocks stay inside the query and jointly cover it. Overlap may count a value twice, which does not affect a minimum."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["Use $a=[5,2,7,1,4]$ and query $[1,5)$.","The length is $4$, so $k=2$.","Both selected blocks are the same length-four interval.","Their combined minimum is $1$. For length $3$, the two length-two blocks overlap."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"Construction is correct because each block is the minimum of its two halves. The two query blocks cover every requested element and no outside element. Idempotence ensures duplicated elements cannot alter the aggregate."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct SparseTable {\n    vector<vector<long long>> st;vector<int> lg;int n;\n    SparseTable(const vector<long long>& a):n(a.size()){\n        assert(n>0);lg.assign(n+1,0);\n        for(int i=2;i<=n;i++)lg[i]=lg[i/2]+1;\n        st.assign(lg[n]+1,vector<long long>(n));st[0]=a;\n        for(int k=1;k<(int)st.size();k++)\n            for(int i=0;i+(1<<k)<=n;i++)\n                st[k][i]=min(st[k-1][i],st[k-1][i+(1<<(k-1))]);\n    }\n    long long query(int l,int r)const{\n        assert(0<=l&&l<r&&r<=n);int k=lg[r-l];\n        return min(st[k][l],st[k][r-(1<<k)]);\n    }\n};"},{"type":"p","text":"Require a nonempty array and a nonempty query. SparseTable rmq($a$) answers rmq.$\\mathrm{query}(l,r)$. Estimate memory explicitly: long long entries need roughly $8$ times $n$ times the number of levels bytes."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Preprocessing","$O(n \\log  n)$ time"],["Nonempty minimum query","$O(1)$ time"],["Table storage","$O(n \\log  n)$ space"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Using overlapping blocks for sum.","Querying an empty interval and taking log2($0$).","Updating the input without rebuilding the table.","Underestimating the table memory."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Trace a length-three query and its overlap.","Replace min with gcd and explain idempotence.","Compare sparse-table and segment-tree tradeoffs."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"topological-sort","title":"Topological sort & DAG DP","category":"Graphs","level":"Дунд шат","aliases":"topological sort dag indegree kahn dependency cycle чиглэсэн cycle","summary":"Dependency-уудыг зөрчихгүй дараалал олох; DAG дээр DP state-уудыг зөв дарааллаар боловсруулах.","prerequisites":"Directed graph, BFS queue, DP-ийн санаа.","related":["dfs","dynamic-programming","dijkstra"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"Topological order гэдэг нь directed edge $u\\to v$ бүрийн хувьд $u$ нь $v$-ээс өмнө байрласан оройнуудын дараалал юм. Ийм дараалал prerequisite болон task dependency-г илэрхийлэхэд хэрэгтэй. Directed cycle байвал дараалал байгуулах боломжгүй. Cycle-гүй directed graph-ийг DAG гэж нэрлэнэ."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Dependency scheduling, DAG path counting, longest path, negative edge-тай DAG shortest path-д хэрэглэ. Topological sort нь ерөнхий graph-ийн shortest path алгоритм биш. Undirected graph-д хоёр чиглэл нэмээд topological sort хийвэл утга өөр болж cycle гэж үзэх тул edge-ийн чиглэлийг өгүүлбэрээс зөв байгуул."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"Kahn-ийн аргад $\\mathrm{indegree}[v]$ нь хараахан боловсруулаагүй оройноос $v$ рүү орж ирэх edge-ийн тоо. Indegree $0$ оройнуудыг queue-д нэм. $v$-г авахад order-д бичээд outgoing edge бүрийн indegree-г нэгээр бууруул. $0$ болсон neighbor одоо dependency-гүй болж queue-д орно."},{"type":"math","tex":"\\forall(u\\to v),\\quad\\operatorname{pos}(u)<\\operatorname{pos}(v)"},{"type":"p","text":"DAG DP-д source state-ийг initialize хийсний дараа topo order-оор relax хийнэ. Path counting-д $\\mathrm{ways}[u]+=\\mathrm{ways}[v]$, longest path-д $\\mathrm{dp}[u]$=max($\\mathrm{dp}[u]$,$\\mathrm{dp}[v]+w$). Хүрэхгүй state-ийг source-оос хүрсэнтэй андуурахгүй sentinel хэрэглэ. Sorting-д vertex label-ийн тоон эрэмбэ ямар ч шаардлагагүй."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$0\\to 2$, $1\\to 2$, $2\\to 3$ graph-ийн indegree=$[0,0,2,1]$.","Queue-д $0$,$1$. $0$-г авахад $\\mathrm{indegree}[2]=1$.","$1$-г авахад $\\mathrm{indegree}[2]=0$ болж $2$ нэмэгдэнэ.","$2$-оос $3$-ыг чөлөөлнө. Order=$[0,1,2,3]$; $[1,0,2,3]$ мөн зөв. $3\\to 1$ edge нэмбэл бүх орой боловсруулагдахгүй."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"Indegree $0$ $v$-д үлдсэн оройноос ирэх edge байхгүй тул $v$-г дараагийн байрлалд тавих нь dependency зөрчихгүй. DAG-ийн хоосон биш үлдсэн хэсэгт indegree $0$ орой заавал бий: байхгүй гэвэл predecessor дагаж finite оройнууд дунд cycle үүснэ. Иймээс DAG-д бүх орой гарна; үлдсэн орой байгаа нь cycle байгааг илтгэнэ."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\noptional<vector<int>> topological(const vector<vector<int>>& g){\n    int n=g.size();vector<int>deg(n),order;queue<int>q;\n    for(auto&edges:g)for(int u:edges)++deg[u];\n    for(int v=0;v<n;v++)if(!deg[v])q.push(v);\n    while(!q.empty()){\n        int v=q.front();q.pop();order.push_back(v);\n        for(int u:g[v])if(--deg[u]==0)q.push(u);\n    }\n    if((int)order.size()!=n)return nullopt;\n    return order;\n}"},{"type":"p","text":"Хоосон optional нь cycle илэрсэн гэсэн үг. Харин хоосон vector агуулсан optional нь хоосон graph-ийн зөв дараалал юм. Parallel edge бүрийг indegree-д тусад нь тоолж, боловсруулахдаа тус бүр нэгээр бууруулна. Хамгийн бага label-тай дараалал хэрэгтэй бол queue-ийн оронд min-heap ашиглана."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Kahn traversal","$O(V+E)$ хугацаа"],["Indegree, queue, order","$O(V)$ нэмэлт зай"],["DAG-ийн edge transition DP","$O(V+E)$, transition $O(1)$ үед"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["Order-ийн урт $n$ эсэхийг шалгахгүй cycle-тэй graph дээр DP хийх.","Indegree биш outgoing edge count ашиглах.","DAG longest path-ийг ерөнхий cycle-тэй graph-д ашиглах.","Topo order цорын ганц гэж бодох."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Гарсан order-ийн pos array үүсгээд edge бүрийг шалга.","DAG дээр source-оос target хүрэх path count-ийн recurrence бич.","Cycle-д оролцоогүй оройнууд ч үлдэж болох уу? Жишээ гарга."]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"intermediate","order":14,"translations":{"en":{"title":"Topological sort & DAG DP","summary":"Order directed dependencies and detect cycles with Kahn’s algorithm.","prerequisites":"Directed graphs, queues and indegrees.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"A topological order places $u$ before $v$ for every directed edge $u\\to v$. It exists exactly for a DAG, a directed acyclic graph. A directed cycle would require each of its vertices to come before the next, which is impossible."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use it for prerequisites, task dependencies and DP on a DAG. An order is usually not unique. For the lexicographically smallest order, replace the queue with a min-heap."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"Count $\\mathrm{indegree}[v]$ and enqueue every vertex whose indegree is zero. Remove $v$, append it to the order, and decrement the indegree of every outgoing neighbor. Enqueue a neighbor when its count becomes zero."},{"type":"math","tex":"\\forall(u\\to v),\\quad\\operatorname{pos}(u)<\\operatorname{pos}(v)"},{"type":"p","text":"If fewer than $V$ vertices are removed, the remaining graph contains a cycle. Parallel edges must each be counted and decremented. An empty graph has a valid empty order."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["Take edges $0\\to 2$ and $1\\to 2$.","Vertices $0$ and $1$ initially have indegree zero.","Remove them in either order; vertex $2$ becomes available after both.","Adding edge $2\\to 0$ creates a cycle, so a full order cannot be produced."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"A zero-indegree vertex has no remaining prerequisite and can safely come next. Removing it preserves the same problem on the remaining vertices. If a nonempty remaining graph has no zero-indegree vertex, repeatedly following incoming edges eventually repeats a vertex and yields a cycle."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\noptional<vector<int>> topological(const vector<vector<int>>& g){\n    int n=g.size();vector<int>deg(n),order;queue<int>q;\n    for(auto&edges:g)for(int u:edges)++deg[u];\n    for(int v=0;v<n;v++)if(!deg[v])q.push(v);\n    while(!q.empty()){\n        int v=q.front();q.pop();order.push_back(v);\n        for(int u:g[v])if(--deg[u]==0)q.push(u);\n    }\n    if((int)order.size()!=n)return nullopt;\n    return order;\n}"},{"type":"p","text":"The function returns an optional order. An empty optional means a cycle, whereas an optional containing an empty vector is a valid empty DAG. Edge-transition DP can follow the resulting order."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Kahn traversal","$O(V+E)$ time"],["Indegrees, queue and order","$O(V)$ extra space"],["Constant-cost DAG DP transitions","$O(V+E)$ time"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Treating undirected edges as DAG dependencies.","Confusing an empty valid order with failure.","Ignoring parallel edges in indegrees.","Assuming every vertex label must appear in numeric order."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Construct two different valid orders for one DAG.","Use a min-heap to obtain the smallest label order.","Compute the longest path in a DAG using the order."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"dynamic-programming","title":"Dynamic programming — DP","category":"DP","level":"Дунд шат","aliases":"dp dynamic programming memoization tabulation төлөв transition recurrence","summary":"Ижил subproblem-ийг дахин бодохгүйгээр state, transition, base case, боловсруулах дарааллыг тодорхойлох.","prerequisites":"Recursion, array, complexity.","related":["knapsack","lis","topological-sort"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"DP нь бодлогыг жижиг subproblem-уудад хувааж, тэдгээрийн хариуг хадгалан дахин ашигладаг арга юм. State нь цаашдын сонголтод нөлөөлөх бүх мэдээллийг агуулсан байх ёстой. Мэдээлэл дутвал ялгаатай нөхцөлүүдийг буруу нэгтгэнэ. Харин хэрэггүй мэдээлэл нэмбэл state-ийн тоо хэт өснө. Иймээс state-ийн утгыг тодорхой өгүүлбэрээр бичихээс эхэлнэ."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Optimization, counting, feasibility бодлогод давтагдсан subproblem ба зөв dependency structure байвал хэрэглэ. Memoization нь шаардлагатай state-ийг recursion-аар бодож хадгална. Tabulation нь dependency order-оор table бөглөнө. DP зохиохдоо state-ийн өгүүлбэр, recurrence, base, order, final answer, complexity зургааг тусад нь бич."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"Жишээ нь $1$ эсвэл $2$ алхмаар $n$ шат өгсөх замын тоо. $\\mathrm{ways}[i]$ нь яг $i$ шатанд хүрэх sequence-ийн тоо. Сүүлчийн алхам $1$ эсвэл $2$ байснаар бүх sequence хоёр бүлэгт хуваагдана. $\\mathrm{ways}[0]=1$ нь ямар ч алхам хийгээгүй нэг empty sequence."},{"type":"math","tex":"ways[i]=ways[i-1]+ways[i-2],\\qquad ways[0]=1,\\quad ways[1]=1"},{"type":"p","text":"$\\mathrm{ways}[i]$ бодоход зөвхөн өмнөх хоёр state хэрэгтэй учир memory-г $O(1)$ болгож болно. Энэ нь recurrence-ээс гарсан optimization; өмнөх бүх state хэрэгтэй өөр DP дээр ийм rolling memory шууд хэрэглэж болохгүй. Доорх тоололтыг $10^{9}+7$ modulo-р хийдэг; энэ нь exact integer-ийн оронд үлдэгдэл өгнө."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$n=0$: empty sequence нэг тул $\\mathrm{ways}[0]=1$.","$n=1$: $[1]$, $\\mathrm{ways}[1]=1$. $n=2$: $[1,1]$,$[2]$, $\\mathrm{ways}[2]=2$.","$n=3$: $[1,1,1]$,$[1,2]$,$[2,1]$, $\\mathrm{ways}[3]=3$.","$n=4$ үед $\\mathrm{ways}[3]+\\mathrm{ways}[2]=3+2=5$. $[1,2]$ ба $[2,1]$ ялгаатай дараалал учир хоёул тоологдоно."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"Ямар ч $n$ шат хүрсэн sequence-ийн сүүлчийн алхам $1$ эсвэл $2$. Сүүлчийн алхмыг хасахад $n-1$ эсвэл $n-2$ хүрсэн sequence гарна. Эсрэгээрээ эдгээр sequence бүрийн араас тохирох алхмыг залгаж болно. Хоёр бүлэг давхцахгүй, бүх боломжийг хамардаг учир нийлбэр recurrence зөв. Base cases-ээс эхэлж induction-аар бүх state зөв болно."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nlong long stair_ways(int n){\n    assert(n>=0);const long long MOD=1'000'000'007;\n    if(n==0)return 1;\n    long long previous=1,current=1;\n    for(int i=2;i<=n;i++){\n        long long next=(previous+current)%MOD;\n        previous=current;current=next;\n    }\n    return current;\n}"},{"type":"p","text":"stair_ways нь алхмуудын дарааллыг ялгаж тоолоод $10^9+7$-оор modulo авна. Optimal шийдлийг сэргээх DP-д сонгосон transition эсвэл predecessor-ийг хадгална. Unreachable state-д min бодлогоор $+\\mathrm{INF}$, max бодлогоор $-\\mathrm{INF}$ оноож болох ч тэдгээр дээр арифметик хийхийн өмнө хүрэх боломжтой эсэхийг шалгана."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["$n$ state, $2$ transition","$O(n)$ хугацаа"],["Rolling хоёр state","$O(1)$ нэмэлт зай"],["Ерөнхий DP","State-ийн тоо × нэг state-ээс хийх transition-ий тоо"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["State яг юу гэсэн утгатайг бичихгүйгээр table үүсгэх.","Counting DP-д order чухал эсэхийг ялгахгүй байх.","Unreachable state-ийг $0$ болгоод valid $0$-той андуурах.","Memoized recursion-ийн stack гүн болон exponential state space-ийг үл тоох."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["$1$,$3$ алхам allowed бол recurrence ба base-ийг гарга.","Бүх жижиг sequence-ийг enumerate хийгээд DP-тай тулга.","Min-cost climbing-д state ба transition-ийг counting-оос яаж өөрчлөх вэ?"]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"intermediate","order":15,"translations":{"en":{"title":"Dynamic programming — DP","summary":"Define sufficient states, derive transitions and reuse subproblem answers instead of recomputing them.","prerequisites":"Arrays, recurrence relations and dependency order.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"DP stores solutions to overlapping subproblems. A state must retain every detail that affects future decisions. Too little information merges incompatible situations; too much creates an unnecessarily large state space."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use DP when the answer can be expressed through smaller states with a manageable number of transitions. First decide whether a state counts possibilities, minimizes cost or maximizes value. Then specify its exact meaning."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"For steps of size one or two, $\\mathrm{ways}[i]$ counts ordered step sequences reaching exactly stair $i$. The last step is either one or two, giving two disjoint predecessor cases. $\\mathrm{ways}[0]=1$ represents the empty sequence."},{"type":"math","tex":"ways[i]=ways[i-1]+ways[i-2],\\qquad ways[0]=1,\\quad ways[1]=1"},{"type":"p","text":"Process dependencies before dependents. Since only the previous two states are needed here, retain two rolling values. The implementation counts modulo $1000000007$ rather than returning an unbounded integer."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["For $n=0$, there is one empty sequence.","For $n=1$, the only sequence is $[1]$.","For $n=2$, the sequences are $[1,1]$ and $[2]$.","For $n=3$, the sequences are $[1,1,1]$, $[1,2]$ and $[2,1]$, so the count is $3$."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"Every sequence ending at $i$ has exactly one final step of size one or two. Removing that step maps it to exactly one predecessor sequence. The two cases are disjoint and exhaustive. Induction from the base states proves the recurrence."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nlong long stair_ways(int n){\n    assert(n>=0);const long long MOD=1'000'000'007;\n    if(n==0)return 1;\n    long long previous=1,current=1;\n    for(int i=2;i<=n;i++){\n        long long next=(previous+current)%MOD;\n        previous=current;current=next;\n    }\n    return current;\n}"},{"type":"p","text":"$\\mathrm{stair\\_ways}(n)$ counts ordered sequences modulo the fixed prime. For optimization DP, store a chosen predecessor if reconstruction is required. Never add to an unreachable $\\mathrm{INF}$ sentinel without checking reachability."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["$n$ states with two transitions each","$O(n)$ time"],["Rolling state storage","$O(1)$ extra space"],["General DP","Number of states times transitions per state"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Leaving the state meaning ambiguous.","Using an incorrect base case such as $\\mathrm{ways}[0]=0$.","Processing states before their dependencies.","Double-counting cases that are not disjoint."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Add a permitted step of size three and derive the recurrence.","Compare ordered sequences with unordered combinations.","Write a small brute-force enumerator to verify the first counts."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"knapsack","title":"0/1 knapsack","category":"DP","level":"Дунд шат","aliases":"knapsack үүргэвч багтаамж 0/1 dp capacity descending","summary":"Item бүрийг хамгийн ихдээ нэг удаа авч capacity дотор нийт value-г хамгийн их болгох.","prerequisites":"DP state, loop order, array.","related":["dynamic-programming","greedy","bitmask-dp"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"$0/1$ knapsack-д item бүр weight, value гэсэн хоёр утгатай. Item бүрийг нэг удаа авах эсвэл авахгүй үлдээж болно. Нийт weight нь $W$-ээс хэтрэхгүй үед нийт value-г хамгийн их болгохыг зорьдог. Value/weight харьцаагаар сонгох greedy арга нь fractional хувилбарт тохирдог бөгөөд $0/1$ бодлогыг ерөнхий тохиолдолд зөв шийдэхгүй."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"$n\\times W$ багтах үед capacity-based DP хэрэглэ. $W$ маш том, нийт value бага бол value-based minimum-weight DP сонгож болно. $n\\le 40$ үед meet-in-the-middle байж болно. $O(\\mathrm{nW})$ нь weight-ийн тоон утга $W$-ээс хамаардаг pseudo-polynomial complexity; $W$-ийн bit length-ээс polynomial биш."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"$\\mathrm{dp}[c]$ нь одоог хүртэл үзсэн item-уудаас нийт weight≤$c$ нөхцөлд авах хамгийн их value. Эхэнд itemгүй тул бүх $\\mathrm{dp}=0$. Item $(w,v)$ дээр авахгүй $\\mathrm{dp}[c]$, авбал previous $\\mathrm{dp}[c-w]+v$ хоёрын max. Нэг array дээр хийхдээ capacity-г ихээс бага руу явуул; доод state хараахан энэ item-ээр update болоогүй байна."},{"type":"math","tex":"dp[c]\\leftarrow\\max(dp[c],dp[c-w]+v),\\qquad c=W,W-1,\\ldots,w"},{"type":"p","text":"Хэрэв capacity-г багаас их явуулбал $\\mathrm{dp}[c-w]$ аль хэдийн тухайн item-ийг агуулж, нэг item-ийг олон дахин авах боломж өгнө. Энэ нь unbounded knapsack-ийн өөр recurrence. Exact weight=$c$ байх DP бол $\\mathrm{dp}[0]=0$, бусад нь −$\\mathrm{INF}$; энэ хичээлийн ≤capacity анхны утга оноох үйлдэл-тай адил биш."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["Items $(2,3)$,$(3,4)$,$(4,5)$, $W=5$. Эхэнд $\\mathrm{dp}=[0,0,0,0,0,0]$.","Эхний item-ийн дараа capacity $2…5$ дээр value $3$.","Хоёр дахь item дээр $c=5$: $\\mathrm{dp}[2]+4=3+4=7$; $c=3$ дээр $4$.","Гурав дахь item $4$ weight авч value $5$ өгнө, capacity $5$ дээрх $7$-г сайжруулахгүй. Хариу item $1+2$, нийт weight $5$, value $7$."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"Item $i$-г боловсруулахын өмнө $\\mathrm{dp}$ нь эхний $i-1$ item-ийн optimal утгууд. Item $i$-тэй optimal шийдэл нь түүнийг аваагүй эсвэл авсан гэсэн хоёр case. Авсан бол үлдсэн capacity $c-w$ дээр өмнөх item-уудын optimal сонголт шаардлагатай; эсрэгээрээ түүний дээр item $i$ нэмэх нь зөв. Descending order нь previous-layer утгыг хадгалдаг учир recurrence яг хоёр-layer DP-тай ижил."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nlong long knapsack(int W,const vector<pair<int,long long>>& items){\n    assert(W>=0);vector<long long>dp(W+1,0);\n    for(auto [w,v]:items){\n        assert(w>0);\n        for(int c=W;c>=w;c--)dp[c]=max(dp[c],dp[c-w]+v);\n    }\n    return dp[W];\n}"},{"type":"p","text":"Weight нь эерэг бүхэл тоо, нийт value нь long long-д багтана гэж үзсэн. Item авахгүй үлдээж болох тул negative value байсан ч анхны утгыг $0$ тавих нь зөв. Энэ код zero-weight item дэмжихгүй. Сонгосон item-уудыг сэргээхэд DP history эсвэл тусгай reconstruction хэрэгтэй."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["$n$ item × capacity","$O(\\mathrm{nW})$ хугацаа"],["Нэг DP layer","$O(W)$ зай"],["Exact-weight variant","Unreachable sentinel тусад нь шаардана"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["$0/1$ хувилбарт capacity-г ascending явуулах.","$W=10^{9}$ үед $O(\\mathrm{nW})$ DP багтана гэж бодох.","At-most ба exact capacity state-ийг холих.","Item сэргээхдээ overwritten нэг layer-ийн parent-ийг баталгаагүй дагах."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Нэг item $(2,3)$, $W=4$ үед $3$ гарах ёстой; $6$ гарвал loop order буруу.","$n\\le 15$ бүх subset-ийг enumerate хийж хариугаа тулга.","Value-based DP-ийн state ба recurrence-ийг бич."]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"intermediate","order":16,"translations":{"en":{"title":"0/1 knapsack","summary":"Choose each item at most once to maximize value under a capacity limit.","prerequisites":"DP states, arrays and descending loops.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"In $0/1$ knapsack, each item has a weight and a value. Either take it once or omit it. Maximize total value while total weight is at most $W$. The value-to-weight greedy rule solves a fractional variant, not general $0/1$ knapsack."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use capacity-indexed DP when $W$ is small enough for $O(\\mathrm{nW})$ work. If weights are huge but the total value is small, consider value-indexed DP instead. The loop direction distinguishes $0/1$ from unbounded knapsack."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"Let $\\mathrm{dp}[c]$ be the maximum value obtainable with weight at most $c$ using processed items. For item $(w,v)$, compare keeping $\\mathrm{dp}[c]$ with taking the item using the previous-layer $\\mathrm{dp}[c-w]+v$. Iterate $c$ downward to preserve the previous-layer value."},{"type":"math","tex":"dp[c]\\leftarrow\\max(dp[c],dp[c-w]+v),\\qquad c=W,W-1,\\ldots,w"},{"type":"p","text":"All capacities initially have value zero because taking no items is allowed. For an exact-weight variant, initialize unreachable weights to a negative-infinity sentinel instead. The sample requires strictly positive weights."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["Take items $(2,3)$, $(3,4)$, with capacity $W=5$.","After the first item, capacities at least $2$ can achieve value $3$.","Process the second item in descending capacity order.","At capacity $5$, combine the earlier value at capacity $2$ with value $4$, obtaining $7$."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"For each item, every valid optimum either omits it or includes it once. These are exactly the two transitions. Descending capacity ensures the inclusion transition reads a state that has not yet used the current item, preventing repeated selection."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nlong long knapsack(int W,const vector<pair<int,long long>>& items){\n    assert(W>=0);vector<long long>dp(W+1,0);\n    for(auto [w,v]:items){\n        assert(w>0);\n        for(int c=W;c>=w;c--)dp[c]=max(dp[c],dp[c-w]+v);\n    }\n    return dp[W];\n}"},{"type":"p","text":"The code assumes positive integer weights and totals fitting long long. Negative-value items can be skipped. Restoring the chosen items requires additional history or a carefully designed reconstruction method."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["$n$ items and capacities through $W$","$O(\\mathrm{nW})$ time"],["One DP layer","$O(W)$ space"],["Exact-weight variant","Requires unreachable-state initialization"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Iterating capacities upward and reusing an item.","Applying a fractional greedy argument.","Confusing at-most capacity with exact weight.","Ignoring zero-weight items or integer overflow."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Construct a counterexample to value-to-weight greedy.","Compare small answers with subset enumeration.","Derive a value-indexed minimum-weight DP."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"lis","title":"Longest Increasing Subsequence — LIS","category":"DP","level":"Дунд шат","aliases":"lis longest increasing subsequence strictly increasing дараалал өсөх tails","summary":"Анхны дарааллыг хадгалсан strictly increasing subsequence-ийн хамгийн их уртыг $O(n \\log  n)$-д олох.","prerequisites":"DP, binary search, subsequence vs subarray.","related":["binary-search","dynamic-programming","fenwick-tree"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"Subsequence нь зарим элементийг алгасаж болох боловч индексүүдийн анхны дарааллыг хадгалдаг. Subarray нь array-ийн тасралтгүй хэсэг юм. Strict LIS-д сонгосон дараагийн утга нь өмнөхөөсөө заавал их байна. Энгийн DP нь $a[j]<a[i]$ байх өмнөх бүх $j<i$ байрлалыг шалгаж $O(n^{2})$ хугацаа зарцуулдаг. Илүү хурдан хувилбар нь боломжит сүүлийн утгуудыг $\\mathrm{tails}$ array-д хадгална."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Strictly increasing subsequence-ийн length, зарим ordering/chain бодлогод хэрэглэ. Tails арга нь length хурдан олдог ч LIS-ийн тоог шууд өгдөггүй. 2D координатын chain-д sort-ын tie-breaking маш чухал; ижил эхний coordinate-той утгуудыг буруу дарааллаар оруулбал valid биш chain нэмэгдэнэ."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"$\\mathrm{tails}[k]$ нь боловсруулсан prefix дотор урт $k+1$ strictly increasing subsequence-ийн хамгийн бага боломжит сүүлчийн утга. Шинэ $x$-д анхны $\\mathrm{tails}[k]\\ge x$ байрлалыг lower_bound-аар ол. Олдвол $x$-ээр солино; олдохгүй бол уртыг нэгээр өсгөнө."},{"type":"math","tex":"tails[k]=\\min\\{\\text{last value of an increasing subsequence of length }k+1\\}"},{"type":"p","text":"Бага сүүлтэй subsequence цааш илүү олон элемент-ээр сунгагдах боломжтой. $\\mathrm{tails}$ нь sorted боловч энэ array бүхэлдээ анхны input-ийн нэг valid LIS байх албагүй: өөр өөр уртын optimal $\\mathrm{tails}$-ийг хольж хадгалдаг. Бодит subsequence сэргээхэд indices ба predecessor тусад нь хэрэгтэй."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$a=[3,1,2,2,5,4]$. $3$ орвол $\\mathrm{tails}=[3]$, $1$ орвол $[1]$.","$2$ нь бүх $\\mathrm{tails}$-ээс их тул $[1,2]$. Дараагийн $2$ lower_bound дээр index $1$-ийг солино, урт нэмэхгүй.","$5$ орвол $[1,2,5]$. $4$ нь $5$-г сольж $[1,2,4]$.","Length=$3$. Жишээ LIS нь $[1,2,4]$ эсвэл $[1,2,5]$. Equal $2$-ууд strictly increasing биш тул хоёуланг авахгүй."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"Length $k+1$ subsequence-ийн tail бага байх тусам шинэ том $x$-ээр сунгах боломж муудахгүй. Lower_bound-аас өмнөх бүх $\\mathrm{tails}<x$ тул $x$-ийг өмнөх length-ийн subsequence-д залгаж болно. Lower_bound байрлалын tail-ийг $x$-ээр солих нь тэр уртад илүү бага эсвэл ижил tail өгнө, бусад уртыг эвдэхгүй. Инvariant induction-аар хадгалагдаж, $\\mathrm{tails}$.$\\mathrm{size}()$ хамгийн их боломжит length болно."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nint lis_length(const vector<long long>& a){\n    vector<long long>tails;\n    for(long long x:a){\n        auto it=lower_bound(tails.begin(),tails.end(),x);\n        if(it==tails.end())tails.push_back(x);\n        else *it=x;\n    }\n    return tails.size();\n}"},{"type":"p","text":"Strict LIS-д lower_bound, тэнцүү утга зөвшөөрсөн nondecreasing subsequence-д upper_bound хэрэглэнэ. Энэ код зөвхөн уртыг буцаана. LIS-ийн тоо эсвэл weighted хувилбар хэрэгтэй бол coordinate compression болон Fenwick tree, segment tree ашигласан DP-г авч үзнэ."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Element бүрийн binary search","$O(n \\log  n)$ нийт хугацаа"],["$\\mathrm{tails}$","$O(n)$ зай"],["Энгийн $j<i$ DP","$O(n^{2})$ хугацаа, $O(n)$ зай"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["Subarray ба subsequence-ийг андуурах.","Strict хувилбарт upper_bound хэрэглэж equal элемент-үүдээр length өсгөх.","Tails array өөрөө valid LIS гэж хэвлэх.","LIS count-ийг энэ length algorithm өгнө гэж бодох."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Бүх утга ижил input дээр strict ба nondecreasing хариуг харьцуул.","$O(n^{2})$ DP-тай random array-уудын length-ийг тулга.","LIS сэргээхэд ямар index ба parent мэдээлэл хадгалах вэ?"]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"intermediate","order":17,"translations":{"en":{"title":"Longest Increasing Subsequence — LIS","summary":"Find a longest strictly increasing subsequence in $O(n \\log  n)$ time using minimal $\\mathrm{tails}$.","prerequisites":"Subsequences, DP and binary search.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"A subsequence preserves index order but may skip elements; a subarray is contiguous. Strictly increasing means every later selected value is greater. The basic DP examines earlier smaller values in $O(n^{2})$ time."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use the $\\mathrm{tails}$ method when only the LIS length is required. Reconstructing a subsequence needs indices and predecessors. Counting all LIS or optimizing a weighted variant often needs a Fenwick or segment tree."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"$\\mathrm{tails}[k]$ is the smallest possible final value of an increasing subsequence of length $k+1$ in the processed prefix. For each $x$, find the first $\\mathrm{tails}$ value at least $x$ using lower_bound. Replace it, or append $x$ if none exists."},{"type":"math","tex":"tails[k]=\\min\\{\\text{last value of an increasing subsequence of length }k+1\\}"},{"type":"p","text":"A smaller ending value never reduces future extension opportunities. The $\\mathrm{tails}$ array stores best ending values for different lengths; its entries need not form an actual subsequence of the original input."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["Process $[3,1,2,2,4]$.","The first two values make $\\mathrm{tails}=[3]$, then $\\mathrm{tails}=[1]$.","The next $2$ extends it to $[1,2]$; the equal $2$ replaces the same entry.","The final $4$ extends it to length $3$."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"The minimal-tail invariant holds initially. Binary search identifies the length that $x$ can extend; replacing its tail keeps that length achievable and improves or preserves its minimum ending value. Appending happens exactly when a longer increasing subsequence becomes achievable."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nint lis_length(const vector<long long>& a){\n    vector<long long>tails;\n    for(long long x:a){\n        auto it=lower_bound(tails.begin(),tails.end(),x);\n        if(it==tails.end())tails.push_back(x);\n        else *it=x;\n    }\n    return tails.size();\n}"},{"type":"p","text":"Use lower_bound for strict LIS. Use upper_bound for a nondecreasing subsequence allowing equality. Empty input has length zero. This code returns a length, not the chosen indices."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["One binary search per element","$O(n \\log  n)$ time"],["Tail values","$O(n)$ space"],["Basic earlier-index DP","$O(n^{2})$ time; $O(n)$ space"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Confusing subsequence with subarray.","Using upper_bound for a strict LIS.","Returning $\\mathrm{tails}$ as if it were always an actual subsequence.","Assuming the length-only method also counts all solutions."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Test equal values and a decreasing array.","Add predecessor indices for reconstruction.","Verify random results against the $O(n^{2})$ DP."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"dijkstra","title":"Dijkstra — weighted shortest path","category":"Graphs","level":"Дунд шат","aliases":"dijkstra shortest path жинтэй graph хамгийн богино зам heap priority queue","summary":"Nonnegative edge weight-тай graph дээр нэг source-оос бүх shortest distance-ийг олох.","prerequisites":"BFS, graph, min-heap, long long.","related":["bfs","topological-sort","dynamic-programming"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"Dijkstra нь одоогоор олсон хамгийн бага зайтай оройг түрүүлж боловсруулдаг shortest path алгоритм юм. Тухайн оройгоос edge даган илүү богино зам олдвол хөршийн зайг шинэчилнэ; үүнийг relaxation гэдэг. Min-heap нь дараагийн оройг сонгоно. Бүх edge-ийн weight сөрөг биш байх нь алгоритм зөв ажиллах үндсэн нөхцөл юм."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Замын урт, хугацаа, төлбөр зэрэг nonnegative weight-тай sparse graph-д хэрэглэ. Negative edge байвал Dijkstra-ийн баталгаа нурна; Bellman–Ford эсвэл graph-ийн structure-д тохирох өөр арга хэрэгтэй. DAG дээр negative edge байж болох бөгөөд topological DP ашиглаж болно. $0/1$ weight-д $0$-$1$ BFS илүү энгийн $O(V+E)$ арга байж болно."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"$\\mathrm{dist}[s]=0$, бусад $\\mathrm{dist}=\\mathrm{INF}$. Heap-д $(0,s)$ нэм. $(d,v)$-г pop хийхэд $d\\ne \\mathrm{dist}[v]$ бол хуучирсан entry тул алгас. Edge $v\\to u$ weight $w$ дээр $d+w<\\mathrm{dist}[u]$ бол шинэ distance болон parent хадгалж heap-д шинэ entry хийнэ."},{"type":"math","tex":"\\text{if }d[v]+w(v,u)<d[u],\\quad d[u]\\leftarrow d[v]+w(v,u)"},{"type":"p","text":"Priority_queue-ийн default нь max-heap тул greater<pair<...>> хэрэглэж min-heap болго. Heap-д нэг оройн олон version байж болно; stale check шаардлагатай. $\\mathrm{INF}$-ийг буруу сонговол хүрэх замыг unreachable гэж үзэх тул бүх боломжит distance $\\mathrm{INF}$-ээс бага, addition overflowгүй байх нөхцөлийг тогтоо."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$0\\to 1$ weight $5$, $0\\to 2$ weight $1$, $2\\to 1$ weight $2$. Эхэнд $\\mathrm{dist}$=[$0$,$\\mathrm{INF}$,$\\mathrm{INF}$].","$0$-г pop хийгээд $\\mathrm{dist}[1]=5$, $\\mathrm{dist}[2]=1$. Heap-д $(1,2)$,$(5,1)$.","$2$-г pop хийхэд $1+2=3<5$, тэгэхээр $\\mathrm{dist}[1]=3$. Шинэ $(3,1)$ нэмнэ.","$(3,1)$-ийг зөв version гэж боловсруулна. Дараа $(5,1)$-ийг stale тул алгасна."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"Хамгийн бага tentative distance-тай $v$-г авах мөчид түүнд илүү богино зам байсан гэж төсөөлье. Тэр зам дээр хараахан эцэслээгүй анхны оройн өмнөх орой боловсруулагдсан тул relaxation хийгдсэн байх ёстой. Nonnegative edge-үүдтэй учраас тэр prefix-ийн distance $v$-ийн боломжит богино замаас ихгүй. Тэгвэл heap $v$-ээс өмнө тэр candidate-ийг авах байсан гэсэн зөрчил. Negative edge үед prefix нь бүтэн замаас их байж болох тул энэ баталгаа ажиллахгүй."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nconst long long INF=4'000'000'000'000'000'000LL;\nvector<long long> dijkstra(const vector<vector<pair<int,long long>>>& g,int s){\n    int n=g.size();assert(0<=s&&s<n);\n    vector<long long>d(n,INF);d[s]=0;\n    priority_queue<pair<long long,int>,vector<pair<long long,int>>,\n                   greater<pair<long long,int>>>q;q.push({0,s});\n    while(!q.empty()){\n        auto [dv,v]=q.top();q.pop();if(dv!=d[v])continue;\n        for(auto [u,w]:g[v]){\n            assert(w>=0 && w<INF);\n            if(dv<=INF-w && dv+w<d[u]){\n                d[u]=dv+w;q.push({d[u],u});\n            }\n        }\n    }\n    return d;\n}"},{"type":"p","text":"Бүх бодит shortest distance нь $\\mathrm{INF}$-ээс бага байх ёстой. $\\mathrm{INF}$ хэвээр үлдсэн оройд хүрэх боломжгүй. Зам сэргээх бол зай амжилттай шинэчлэх бүрд $\\mathrm{parent}[u]=v$ хадгална. Weight нь $0$ байж болно, parallel edge мөн дэмжинэ. Heap entry-ийн тоо $O(E)$ хүрч болохыг санах ойн тооцоонд оруулна."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Lazy heap хувилбар","$O((V+E) \\log (E+2))$ дээд хязгаар"],["Simple graph дээр","Ихэвчлэн $O((V+E) \\log  V)$ гэж бичдэг"],["Graph + heap + distance","$O(V+E)$ зай"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["Negative edge байхад шууд ашиглах.","Heap-ийг max-heap хэвээр орхих.","Stale entry-ээс дахин adjacency list боловсруулах.","int distance, $\\mathrm{INF}+w$ overflow, unreachable-ийг $0$ гэж үзэх."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Жижиг random nonnegative graph-ийн distance-ийг Floyd–Warshall-тай тулга.","Zero-weight cycle-тэй үед strict < relax яагаад чухал вэ?","Parent хадгалж зам сэргээх; замын weight sum $\\mathrm{dist}[\\mathrm{target}]$-тай тэнцүүг шалга."]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"intermediate","order":18,"translations":{"en":{"title":"Dijkstra — weighted shortest path","summary":"Find shortest paths with nonnegative edge weights using a min-heap and relaxation.","prerequisites":"Graphs, BFS, priority queues and wide integers.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"Dijkstra processes the vertex with the smallest tentative distance. Relaxation tries to improve a neighbor using an edge from that vertex. All edge weights must be nonnegative; this requirement is central to the proof."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use it for weighted shortest paths when weights are at least zero. Ordinary BFS is preferable for unit weights. Negative edges need a different algorithm even when the graph has no negative cycle."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"Initialize $\\mathrm{dist}[s]=0$ and the others to $\\mathrm{INF}$. Push $(0,s)$. When popping $(d,v)$, skip it if $d\\ne \\mathrm{dist}[v]$: it is an obsolete heap entry. For edge $v\\to u$ of weight $w$, update when $d+w<\\mathrm{dist}[u]$ and push the improved pair."},{"type":"math","tex":"\\text{if }d[v]+w(v,u)<d[u],\\quad d[u]\\leftarrow d[v]+w(v,u)"},{"type":"p","text":"The $\\mathrm{lazy}$ heap stores multiple entries per vertex. Record a parent on successful relaxation for path reconstruction. Choose $\\mathrm{INF}$ above every valid distance and avoid overflow while adding a weight."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["Use edges $0\\to 1$ of weight $5$, $0\\to 2$ of weight $1$, and $2\\to 1$ of weight $2$.","From $0$, tentative distances become $5$ and $1$.","Process vertex $2$ first and improve vertex $1$ to distance $3$.","Process the new entry for $1$; later discard its obsolete distance-$5$ entry."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"When a valid minimum-distance vertex $v$ is popped, any path improving it would first cross from a processed vertex to an unprocessed vertex. Nonnegative remaining weights would have given that crossing vertex a smaller tentative distance, contradicting the choice of $v$."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nconst long long INF=4'000'000'000'000'000'000LL;\nvector<long long> dijkstra(const vector<vector<pair<int,long long>>>& g,int s){\n    int n=g.size();assert(0<=s&&s<n);\n    vector<long long>d(n,INF);d[s]=0;\n    priority_queue<pair<long long,int>,vector<pair<long long,int>>,\n                   greater<pair<long long,int>>>q;q.push({0,s});\n    while(!q.empty()){\n        auto [dv,v]=q.top();q.pop();if(dv!=d[v])continue;\n        for(auto [u,w]:g[v]){\n            assert(w>=0 && w<INF);\n            if(dv<=INF-w && dv+w<d[u]){\n                d[u]=dv+w;q.push({d[u],u});\n            }\n        }\n    }\n    return d;\n}"},{"type":"p","text":"Unreachable vertices retain $\\mathrm{INF}$. Zero weights and parallel edges are supported. The contract requires every finite shortest distance to be below $\\mathrm{INF}$. Heap storage can reach $O(E)$, not just $O(V)$."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Lazy-heap implementation","$O((V+E) \\log (E+2))$ time upper bound"],["Simple graphs","Commonly written $O((V+E) \\log  V)$"],["Graph, distances and heap","$O(V+E)$ space"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Using negative edge weights.","Processing obsolete heap entries.","Using int for large path sums.","Confusing $\\mathrm{INF}$ with a finite distance or overflowing an addition."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Check zero-weight and parallel edges.","Store parents to reconstruct a path.","Compare random small results with Floyd-Warshall."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"lca","title":"Tree, binary lifting & LCA","category":"Graphs","level":"Дунд шат","aliases":"tree lca lowest common ancestor binary lifting ancestor мод өвөг","summary":"Rooted tree дээр хоёр оройн хамгийн ойрын нийтлэг ancestor болон path-ийн уртыг хурдан олох.","prerequisites":"Tree, DFS/BFS, depth, powers of two.","related":["dfs","bfs","sparse-table"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"Tree нь connected, cycle-гүй undirected graph юм. Root сонгосноор орой бүрийн $\\mathrm{parent}$ болон root-оос хэмжсэн $\\mathrm{depth}$ тодорхой болно. Parent-ийг давтан дагаж хүрэх оройг ancestor гэнэ; энэ хичээлд $v$ өөрөө мөн $v$-ийн ancestor гэж үзнэ. $\\mathrm{LCA}(u,v)$ нь хоёр оройн common ancestor-уудаас хамгийн их $\\mathrm{depth}$-тэй буюу хамгийн доод орой юм."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"LCA нь tree-ийн хоёр оройн хоорондох зай, kth ancestor болон path query бодлогод хэрэгтэй. Binary lifting нь ancestor jump-уудыг урьдчилан тооцоод query-г $O(\\log  n)$ хугацаанд хариулна. Энэ арга static tree-д зориулагдсан: edge өөрчлөгдвөл preprocessing-ийг дахин хийх эсвэл dynamic tree дэмждэг data structure сонгох шаардлагатай."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"$\\mathrm{up}[k][v]$ нь $v$-ээс дээш $2^k$ edge явсан ancestor-ийг хадгална. Дараагийн түвшнийг $\\mathrm{up}[k][v]=\\mathrm{up}[k-1][\\mathrm{up}[k-1][v]]$ гэж байгуулна. Query-д эхлээд илүү гүн оройг нөгөөгийн $\\mathrm{depth}$-тэй тэнцүүлнэ. Оройнууд ижил болсон бол тэр нь LCA. Үгүй бол jump-уудыг ихээс бага руу шалгаж, очих ancestor-ууд нь өөр байвал хоёр оройг зэрэг өргөнө."},{"type":"math","tex":"\\operatorname{dist}(u,v)=depth[u]+depth[v]-2\\,depth[\\operatorname{LCA}(u,v)]"},{"type":"p","text":"Хоёр оройг нэг ancestor дээр зэрэг аваачих jump-ийг алгасана. Ингэснээр LCA-г давж гарахгүй. Бүх jump-ийг шалгасны дараа хоёр орой нэг $\\mathrm{parent}$-тэй болж, тэр $\\mathrm{parent}$ нь LCA байна. Доорх томъёо unweighted tree-ийн зам дахь edge-ийн тоог өгнө. Weighted tree-д $\\mathrm{depth}$-ийн оронд root-оос хэмжсэн зайг ашиглана."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["Tree edges $0$—$1$,$0$—$2$,$1$—$3$,$1$—$4$; root=$0$. Depth=$[0,1,1,2,2]$.","$\\mathrm{LCA}(3,4)$: depth ижил, $1$-step ancestors хоёул $1$ тул дээш үсрэхгүй. Parent $1$ хариу.","$\\mathrm{LCA}(3,2)$: $3$-ыг depth $1$ хүртэл өргөөд $1$ болгоно.","$1$ ба $2$-ийн parent хоёул $0$. LCA=$0$, distance($3$,$2$)=$2+1-0=3$."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"Depth-ийг тэнцүүлэх нь нийтлэг ancestor-уудыг алдахгүй: shallow оройн $\\mathrm{depth}$-ээс доош LCA байх боломжгүй. Ижил $\\mathrm{depth}$-тэй $u$,$v$ өөр байх үед $\\mathrm{up}[k][u]$≠$\\mathrm{up}[k][v]$ байвал тэр ancestor-ууд LCA-ээс доор байна; LCA болон түүнээс дээр ижил $\\mathrm{depth}$ дээр хоёул ижил орой байдаг. Тиймээс зөвхөн аюулгүй jump хийж, төгсгөлд хоёул LCA-ийн хүүхэд дээр үлдэнэ."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct LCA {\n    int n,LOG=1;vector<int>depth;vector<vector<int>>up;\n    LCA(const vector<vector<int>>&g,int root):n(g.size()),depth(n,-1){\n        assert(n>0&&0<=root&&root<n);\n        while((1LL<<LOG)<=n)++LOG;up.assign(LOG,vector<int>(n,root));\n        queue<int>q;depth[root]=0;q.push(root);\n        while(!q.empty()){\n            int v=q.front();q.pop();\n            for(int u:g[v])if(depth[u]==-1){\n                depth[u]=depth[v]+1;up[0][u]=v;q.push(u);\n            }\n        }\n        for(int d:depth)assert(d!=-1);\n        for(int k=1;k<LOG;k++)for(int v=0;v<n;v++)\n            up[k][v]=up[k-1][up[k-1][v]];\n    }\n    int query(int a,int b)const{\n        if(depth[a]<depth[b])swap(a,b);\n        int diff=depth[a]-depth[b];\n        for(int k=0;k<LOG;k++)if(diff>>k&1)a=up[k][a];\n        if(a==b)return a;\n        for(int k=LOG-1;k>=0;k--)if(up[k][a]!=up[k][b]){\n            a=up[k][a];b=up[k][b];\n        }\n        return up[0][a];\n    }\n    int distance(int a,int b)const{return depth[a]+depth[b]-2*depth[query(a,b)];}\n};"},{"type":"p","text":"Input нь connected tree байх бөгөөд edge бүр adjacency list-д хоёр чиглэлд орсон байна. Constructor нь recursion ашиглахгүй BFS-ээр $\\mathrm{depth}$ болон $\\mathrm{parent}$-ийг олно. Ердийн connected graph өгвөл traversal tree-ийн LCA гарч болох ч энэ нь анхны graph-ийн shortest distance-ийг илэрхийлэхгүй."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Preprocessing","$O(n \\log  n)$ хугацаа"],["LCA / distance query","$O(\\log  n)$"],["Ancestor table","$O(n \\log  n)$ зай"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["Graph tree мөн эсэхийг шалгалгүй ашиглах.","Root-ийн parent-ийг $-1$ тавьчихаад $\\mathrm{up}[k-1][-1]$ унших.","Depth difference-ийн бүх bit-ийг боловсруулахгүй байх.","Weighted path length-д unweighted depth томъёо ашиглах."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["$\\mathrm{query}(v,v)$, ancestor-descendant pair, root оролцсон query турш.","Chain ба star tree-ийн depth, LCA-г гараар бод.","Хоёр оройг parent-аар нэг нэгээр өргөдөг naive LCA-тай random tree дээр тулга."]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"intermediate","order":19,"translations":{"en":{"title":"Tree, binary lifting & LCA","summary":"Precompute binary ancestor jumps to answer lowest-common-ancestor and tree-distance queries.","prerequisites":"Rooted trees, BFS or DFS, depths and powers of two.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"A tree is a connected undirected graph without cycles. After choosing a root, each vertex has a parent and a depth. A vertex is considered its own ancestor. $\\mathrm{LCA}(u,v)$ is the common ancestor with greatest depth."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use LCA for distances, ancestor queries and path reasoning on a static tree. Changing the tree edges invalidates the preprocessing. A traversal tree of an arbitrary graph does not preserve the graph’s shortest distances."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"Store $\\mathrm{up}[k][v]$, the ancestor $2^k$ edges above $v$. Compose two half-length jumps to build the next level. First lift the deeper query vertex to equal depth. If vertices differ, inspect jumps from large to small and lift both whenever their ancestors differ."},{"type":"math","tex":"\\operatorname{dist}(u,v)=depth[u]+depth[v]-2\\,depth[\\operatorname{LCA}(u,v)]"},{"type":"p","text":"Set the root’s parent to itself. After the simultaneous jumps, the vertices have the same parent, which is their LCA. For weighted trees use distance from the root instead of depth in the distance formula."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["Root a tree at $0$ with edges $0$-$1$, $0$-$2$, $1$-$3$ and $1$-$4$.","Vertices $3$ and $4$ share ancestor $1$, so $\\mathrm{LCA}(3,4)$=$1$.","Vertices $3$ and $2$ share only ancestors reaching root $0$, so $\\mathrm{LCA}(3,2)$=$0$.","The unweighted distance from $3$ to $2$ is $2+1$-$2\\times 0=3$."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"Depth equalization preserves all common ancestors. When the two jump ancestors differ, both are still strictly below the LCA, so lifting cannot pass it. After all powers have been checked, the two vertices lie immediately below their common parent, identifying the lowest common ancestor."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct LCA {\n    int n,LOG=1;vector<int>depth;vector<vector<int>>up;\n    LCA(const vector<vector<int>>&g,int root):n(g.size()),depth(n,-1){\n        assert(n>0&&0<=root&&root<n);\n        while((1LL<<LOG)<=n)++LOG;up.assign(LOG,vector<int>(n,root));\n        queue<int>q;depth[root]=0;q.push(root);\n        while(!q.empty()){\n            int v=q.front();q.pop();\n            for(int u:g[v])if(depth[u]==-1){\n                depth[u]=depth[v]+1;up[0][u]=v;q.push(u);\n            }\n        }\n        for(int d:depth)assert(d!=-1);\n        for(int k=1;k<LOG;k++)for(int v=0;v<n;v++)\n            up[k][v]=up[k-1][up[k-1][v]];\n    }\n    int query(int a,int b)const{\n        if(depth[a]<depth[b])swap(a,b);\n        int diff=depth[a]-depth[b];\n        for(int k=0;k<LOG;k++)if(diff>>k&1)a=up[k][a];\n        if(a==b)return a;\n        for(int k=LOG-1;k>=0;k--)if(up[k][a]!=up[k][b]){\n            a=up[k][a];b=up[k][b];\n        }\n        return up[0][a];\n    }\n    int distance(int a,int b)const{return depth[a]+depth[b]-2*depth[query(a,b)];}\n};"},{"type":"p","text":"The constructor expects a connected tree with both adjacency directions. It computes parents and depths with iterative BFS, avoiding recursive stack overflow. Vertex indices must be valid."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Preprocessing","$O(n \\log  n)$ time"],["LCA or distance query","$O(\\log  n)$ time"],["Ancestor table","$O(n \\log  n)$ space"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Forgetting to equalize depths first.","Jumping when the two ancestors are equal and passing the LCA.","Applying the tree distance formula to a general graph.","Treating weighted distance as edge-count depth."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Test identical vertices and an ancestor-descendant pair.","Derive the kth-ancestor query from binary jumps.","Compare random tree queries with a naive parent walk."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"kmp","title":"Prefix function & KMP","category":"Strings","level":"Дунд шат","aliases":"kmp prefix function string pattern matching текст хайх border substring","summary":"Pattern-ийг text дотор $O(n+m)$-д хайх; тохирсон prefix-ийн мэдээллийг mismatch үед дахин ашиглах.","prerequisites":"String, index, prefix ба suffix.","related":["dynamic-programming","hash-compression","complexity"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"Pattern-ийн prefix function $\\mathrm{pi}[i]$ нь $p[0..i]$-ийн эхлэл болон төгсгөлд зэрэг таардаг хамгийн урт proper prefix-ийн урт юм. Proper prefix нь тухайн хэсгээс богино байх ёстой. Ийм давхцсан хэсгийг border гэдэг. KMP нь mismatch гарахад өмнө таарсан бүх character-ийг дахин шалгахын оронд боломжит border руу шилждэг."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Олон substring match, overlap occurrences, string period/border бодлогод хэрэглэ. Standard string::find нь хэрэглээний хувьд энгийн боловч энэ хичээл guaranteed linear algorithm-ийн invariant-ийг ойлгоход зориулагдсан. Unicode-ийн тухайд std::string нь byte sequence; Монгол үсгийг UTF-$8$ байтаар боловсруулах ба буцах index нь character биш byte index байна."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"$\\mathrm{pi}[i]$ бодоход $j=\\mathrm{pi}[i-1]$-ээс эхэл. $p[i]\\ne p[j]$ байвал $j=\\mathrm{pi}[j-1]$ гэж дараагийн хамгийн урт border руу буц. Тэнцвэл $j$++. Text scan-д $j$ нь одоогийн text prefix-ийн suffix-тэй таарч буй pattern prefix-ийн урт. $j=m$ бол match олдсон; дараагийн overlap-ийг алдахгүй $j=\\mathrm{pi}[m-1]$ болгож үргэлжлүүл."},{"type":"math","tex":"pi[i]=\\max\\{k<i+1\\mid p[0:k)=p[i-k+1:i+1)\\}"},{"type":"p","text":"Mismatch үед $j$−− гэж бүх length-ийг нэг нэгээр шалгахгүй. Зөв боломжит length-үүд нь border-уудын chain тул $\\mathrm{pi}$-ээр үсэрнэ. Pattern $m=0$ тусдаа case; энэ хичээлд хоосон pattern text-ийн $n+1$ boundary бүр дээр таарна гэж тодорхойлсон."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["Pattern ababa-ийн $\\mathrm{pi}=[0,0,1,2,3]$. Сүүлчийн $a$ дээр aba prefix ба suffix таарна.","Text abababa дээр эхний таван character pattern-тэй таарч index $0$ match болно.","Дараа $j=\\mathrm{pi}[4]=3$. Шинээр $b$,$a$ уншаад бүтэн match index $2$ дээр олдоно.","$j$-г $0$ болгосон бол overlap мэдээллийг алдана. KMP match-үүд $[0,2]$ гэж буцаана."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"Таарсан prefix урт $j$ дээр mismatch гарвал шинэ candidate нь тэр prefix-ийн suffix бөгөөд pattern-ийн prefix байх ёстой. Ийм хамгийн урт proper хэсэг $\\mathrm{pi}[j-1]$, дараагийнх нь түүний border гэх мэт. Chain-ээр буцах нь бүх боломжит candidate-ийг алгасахгүй. $j$ нь character match бүрд хамгийн ихдээ нэгээр өсөх ба буцахад буурдаг тул нийт өсөлт/бууралтын тоо linear."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nvector<int> prefix_function(const string& p){\n    vector<int>pi(p.size());\n    for(int i=1;i<(int)p.size();i++){\n        int j=pi[i-1];\n        while(j>0&&p[i]!=p[j])j=pi[j-1];\n        if(p[i]==p[j])++j;pi[i]=j;\n    }\n    return pi;\n}\nvector<int> kmp(const string& text,const string& pattern){\n    int n=text.size(),m=pattern.size();vector<int>answer;\n    if(m==0){answer.resize(n+1);iota(answer.begin(),answer.end(),0);return answer;}\n    auto pi=prefix_function(pattern);int j=0;\n    for(int i=0;i<n;i++){\n        while(j>0&&text[i]!=pattern[j])j=pi[j-1];\n        if(text[i]==pattern[j])++j;\n        if(j==m){answer.push_back(i-m+1);j=pi[j-1];}\n    }\n    return answer;\n}"},{"type":"p","text":"Буцах индексүүд нь $0$-оос эхэлсэн match-ийн эхлэлүүд юм. Empty pattern-ийг text-ийн бүх заагт таарна гэж үзэж $0$-ээс $n$ хүртэлх индексүүдийг буцаана. ASCII үед byte index нь character index-тэй ижил; Unicode text-д индексийн convention-оо тусад нь тогтооно. Энэ хувилбар тусгай separator шаарддаггүй."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Prefix function","$O(m)$ хугацаа, $O(m)$ зай"],["Text scan","$O(n)$ хугацаа"],["Match list","Occurrence-ийн тоотой тэнцэх зай"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["$\\mathrm{pi}[j]$ гэж буцаж өөрчлөгдөхгүй loop үүсгэх; $\\mathrm{pi}[j-1]$ хэрэгтэй.","Бүтэн match дараа $\\mathrm{pattern}[m]$-д хандах.","Overlap match-уудыг алгасах.","UTF-$8$ byte index-ийг харагдах character index гэж тайлбарлах."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Text aaaaa, pattern aaa дээр match-уудыг хэлээд кодтой тулга.","Random жижиг string-ийн naive substring comparison-тай тулга.","$n-\\mathrm{pi}[n-1]$ нь string-ийн period candidate болохыг тайлбарла; full repetition-д divisibility шалгах уу?"]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"intermediate","order":20,"translations":{"en":{"title":"Prefix function & KMP","summary":"Reuse prefix borders to find every occurrence of a pattern without rescanning matched characters.","prerequisites":"Strings, arrays and amortized analysis.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"The prefix function $\\mathrm{pi}[i]$ is the length of the longest proper prefix of $p[0..i]$ that is also a suffix. Such a prefix-suffix is a border. Proper means shorter than the whole prefix being considered."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use KMP for deterministic linear-time matching, including overlapping occurrences. Unlike a pattern-separator-text construction, this implementation scans the text directly and needs no special separator character."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"To compute $\\mathrm{pi}[i]$, start with $j=\\mathrm{pi}[i-1]$. While $p[i]$ differs from $p[j]$, fall back to $j=\\mathrm{pi}[j-1]$. During the text scan, $j$ is the length of the matching pattern prefix. When $j=m$, report a match and fall back to $\\mathrm{pi}[m-1]$."},{"type":"math","tex":"pi[i]=\\max\\{k<i+1\\mid p[0:k)=p[i-k+1:i+1)\\}"},{"type":"p","text":"The fallback preserves useful already-matched information. Resetting $j$ to zero after a match would miss overlapping occurrences. The supplied implementation defines an empty pattern to occur at every boundary, returning all indices from $0$ through $n$."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["For pattern abab, the prefix function is $[0,0,1,2]$.","Scan text ababab from left to right.","The first complete match starts at index $0$; fall back to border length $2$.","Continuing finds another match at index $2$, despite the overlap."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"After a mismatch, any shorter viable matching prefix must be a border of the already-matched prefix. Following the border chain tests all candidates without missing one. $j$ increases at most once per scanned character, so total decreases are also linear."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nvector<int> prefix_function(const string& p){\n    vector<int>pi(p.size());\n    for(int i=1;i<(int)p.size();i++){\n        int j=pi[i-1];\n        while(j>0&&p[i]!=p[j])j=pi[j-1];\n        if(p[i]==p[j])++j;pi[i]=j;\n    }\n    return pi;\n}\nvector<int> kmp(const string& text,const string& pattern){\n    int n=text.size(),m=pattern.size();vector<int>answer;\n    if(m==0){answer.resize(n+1);iota(answer.begin(),answer.end(),0);return answer;}\n    auto pi=prefix_function(pattern);int j=0;\n    for(int i=0;i<n;i++){\n        while(j>0&&text[i]!=pattern[j])j=pi[j-1];\n        if(text[i]==pattern[j])++j;\n        if(j==m){answer.push_back(i-m+1);j=pi[j-1];}\n    }\n    return answer;\n}"},{"type":"p","text":"Returned positions are $0$-based byte indices. For ASCII, byte and character indices agree; multibyte text needs an explicit indexing convention. Preserve the fallback after every full match."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Prefix function for length $m$","$O(m)$ time and space"],["Text scan of length $n$","$O(n)$ time"],["Reported matches","$O(\\mathrm{number} \\mathrm{of} \\mathrm{occurrences})$ space"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Resetting to zero after a full match.","Accessing $p[j]$ after $j$ has reached $m$.","Confusing border length with the border’s last index.","Assuming byte indices always equal Unicode character indices."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Find all occurrences of aaa in aaaaa.","List the borders of ababab.","Compare random small results with naive string matching."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"number-theory","title":"GCD, sieve & modular arithmetic","category":"Math","level":"Дунд шат","aliases":"gcd lcm euclid sieve prime эратосфен анхны тоо modulo fast power modular arithmetic","summary":"GCD, prime sieve, fast exponentiation-ийг ойлгож integer overflow ба modular division-ийн нөхцөлийг ялгах.","prerequisites":"Integer, remainder, loop, binary representation.","related":["combinatorics","binary-search","bitmask-dp"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"$\\mathrm{GCD}(a,b)$ нь $a$, $b$ хоёрыг хуваадаг хамгийн их эерэг бүхэл тоо юм; стандарт convention-оор $\\mathrm{gcd}(0,0)$=$0$. Euclid алгоритм $\\mathrm{gcd}(a,b)$=$\\mathrm{gcd}(b,a \\bmod  b)$ дүрмээр ажиллана. Sieve нь $0$-ээс $N$ хүртэлх prime тоонуудыг урьдчилан олно. Binary exponentiation нь exponent-ийн binary бичлэгийг ашиглан зэрэг дэвшүүлэх үйлдлийг хурдлуулна."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Олон primality query, factorization-ийн суурь prime list, combinatorics modulo, exponent том бодлогод хэрэглэ. Sieve нь $10$¹⁸ хүртэл array байгуулах арга биш; ганц асар том integer-д өөр primality algorithm хэрэгтэй. Modular division нь integer division биш: inverse зөвхөн $\\mathrm{gcd}(a,m)$=$1$ үед оршино."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"Sieve-д prime $p$-ийн multiples-ийг $p^{2}$-оос тэмдэглэж болно; түүнээс жижиг multiples нь өмнөх prime-уудаар тэмдэглэгдсэн. Fast power-д base-г square хийж exponent-ийг /$2$ хийнэ; тухайн bit $1$ бол result-д base-г үржүүлнэ. Modulo-ийн үлдэгдэлд addition/multiplication хийж болно."},{"type":"math","tex":"\\gcd(a,b)=\\gcd(b,a\\bmod b),\\qquad a^{2k}=(a^k)^2,\\qquad a^{2k+1}=a(a^k)^2"},{"type":"p","text":"C++ дээр negative % нь negative байж болно. Normalized remainder хэрэгтэй үед $x$%=$m$; if($x<0$)$x+=m$ хэрэглэ. base×base нь modulo авахын өмнө overflow үүсгэж болох тул доорх код __int128 intermediate ашиглана. Энэ нь GNU C++$17$ extension, GCC/Clang орчинд тохирно."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$\\mathrm{gcd}(48,18)$: $(48,18)\\to (18,12)\\to (12,6)\\to (6,0)$. Хариу $6$.","$N=10$ sieve-д $2$-ын $4$,$6$,$8$,$10$, дараа $3$-ын $9$ composite болно. Prime-ууд $2$,$3$,$5$,$7$.","$3^13$: exponent $13=(1101)$₂. Хэрэгтэй powers нь $3$¹,$3$⁴,$3$⁸.","Modulo $7$ дээр $3^13$ mod $7=3$. Binary exponentiation эдгээр power-ийг square-аар олно."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"Euclid-д $a$=qb+$r$ учраас $a$,$b$-г хуваадаг тоо $b$,$r$-г мөн хуваана; эсрэг чиглэл ч ижил. Sieve-д composite $x$ заавал ≤√$x$ prime factor-той тул тэр factor-ийн multiples-ийг тэмдэглэхэд $x$ олдоно. Fast power loop-д result×base^exponent нь анхны $a^e$-тэй modulo $m$ дээр ижил invariant хадгална; exponent $0$ болоход result хариу болно."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nvector<bool> sieve(int n){\n    assert(n>=0);vector<bool>prime(n+1,true);\n    prime[0]=false;if(n>=1)prime[1]=false;\n    for(int p=2;1LL*p*p<=n;p++)if(prime[p])\n        for(long long x=1LL*p*p;x<=n;x+=p)prime[x]=false;\n    return prime;\n}\nlong long modpow(long long a,long long e,long long m){\n    assert(e>=0&&m>0);a%=m;if(a<0)a+=m;long long r=1%m;\n    while(e){\n        if(e&1)r=(__int128)r*a%m;\n        a=(__int128)a*a%m;e/=2;\n    }\n    return r;\n}"},{"type":"p","text":"Sieve нь $n=0$ болон $n=1$ тохиолдлыг дэмжинэ. modpow нь эерэг modulus, сөрөг биш exponent шаарддаг; $m=1$ үед $0$ буцаана. Prime modulus $m$ болон $m$-д хуваагдахгүй $a$-д inverse нь $a^{m-2}\\bmod m$. Энэ дүрмийг composite modulus-д шууд хэрэглэхгүй. Үржвэрийн overflow-оос сэргийлэхийн тулд код GNU C++17-ийн __int128 ашигласан."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Euclid GCD","$O(\\log  \\mathrm{min}(a,b))$ эерэг оролтод"],["Sieve","$O(N \\log  \\log  N)$ хугацаа, $O(N)$ зай (асимптотик)"],["Fast power","$O(\\log (e+1))$ үржүүлэлт, $O(1)$ зай"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["$0$,$1$-ийг prime гэж тэмдэглэх.","$p*p$-г int дээр overflow болгох.","Composite modulus дээр Fermat inverse хэрэглэх.","Division хийж байгаад modulo авахыг inverse-тэй ижил гэж бодох."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Sieve-ийн бүх $n\\le 100$ утгыг trial division-тай тулга.","$\\mathrm{gcd}(a,b)$ нь ax+by-ийн бүх integer combination-ийг хуваадаг гэдгийг батал.","Mod $8$ дээр $2$-ын inverse яагаад байхгүй вэ? Mod $7$ дээр $3$-ын inverse-г ол."]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"intermediate","order":21,"translations":{"en":{"title":"GCD, sieve & modular arithmetic","summary":"Use Euclid’s algorithm, a prime sieve and binary exponentiation with explicit modular-arithmetic conditions.","prerequisites":"Division, remainders, loops and integer types.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"$\\mathrm{gcd}(a,b)$ is the greatest common divisor; the standard $\\mathrm{gcd}(0,0)$ convention is zero. Euclid repeatedly replaces $(a,b)$ with ($b$,$a$ mod $b$). A sieve marks primes up to $N$. Binary exponentiation computes a power using the exponent’s binary digits."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use gcd for divisibility and simplifying ratios, a sieve for many prime queries, and modular exponentiation for large powers. Modular division is not ordinary division: an inverse exists only when the value and modulus are coprime."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"For a prime $p$, start marking multiples at $p^{2}$ because smaller multiples already have a smaller prime factor. For exponentiation, square the base and halve the exponent; multiply the result by the base whenever the current bit is one."},{"type":"math","tex":"\\gcd(a,b)=\\gcd(b,a\\bmod b),\\qquad a^{2k}=(a^k)^2,\\qquad a^{2k+1}=a(a^k)^2"},{"type":"p","text":"With prime modulus $m$ and a not divisible by $m$, $a$^($m$-$2$) gives the inverse modulo $m$. The rule cannot be applied blindly to composite moduli. Reduce after multiplication and use a wide enough intermediate type."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["Euclid computes $\\mathrm{gcd}(30,18)$ through $(18,12)$, $(12,6)$, then $(6,0)$.","The sieve marks multiples of $2$, then surviving prime $3$, and so on.","For exponent $13$, the binary digits select powers $1$,$4$ and $8$.","Multiply those selected powers modulo $m$ to obtain $a^13$ mod $m$."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"A number divides $a$ and $b$ exactly when it divides $b$ and $a$ mod $b$, preserving the gcd. Every composite has a prime divisor no larger than its square root, so the sieve marks it. Binary exponentiation preserves the result-times-remaining-power invariant as it consumes each bit."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nvector<bool> sieve(int n){\n    assert(n>=0);vector<bool>prime(n+1,true);\n    prime[0]=false;if(n>=1)prime[1]=false;\n    for(int p=2;1LL*p*p<=n;p++)if(prime[p])\n        for(long long x=1LL*p*p;x<=n;x+=p)prime[x]=false;\n    return prime;\n}\nlong long modpow(long long a,long long e,long long m){\n    assert(e>=0&&m>0);a%=m;if(a<0)a+=m;long long r=1%m;\n    while(e){\n        if(e&1)r=(__int128)r*a%m;\n        a=(__int128)a*a%m;e/=2;\n    }\n    return r;\n}"},{"type":"p","text":"The sieve supports bounds $0$ and $1$. modpow returns zero for modulus $1$ and requires a positive modulus and nonnegative exponent. The code uses a wider multiplication intermediate. Compute lcm as ($a$/$\\mathrm{gcd}(a,b)$)*$b$ and still check overflow. The wide intermediate uses GNU C++17 __int128."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Euclid for positive inputs","$O(\\log  \\mathrm{min}(a,b))$ time"],["Sieve","$O(N \\log  \\log  N)$ time; $O(N)$ space"],["Binary exponentiation","$O(\\log (e+1))$ multiplications; $O(1)$ space"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Treating $0$ and $1$ as primes.","Starting a sieve multiple expression in an overflowing int.","Using Fermat’s inverse rule for every modulus.","Multiplying residues without a sufficiently wide intermediate."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Verify all primes through $30$.","Compute a power by both repeated multiplication and binary exponentiation.","Find a value with no inverse modulo a composite modulus."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"combinatorics","title":"Combinatorics & түгээмэл томъёо","category":"Math","level":"Дунд шат","aliases":"combination permutation factorial ncr binomial томъёо хослол сэлгэмэл геометр арифметик","summary":"Counting-д order чухал эсэхийг ялгаж, binomial coefficient болон CP-д хэрэгтэй томъёонуудыг нөхцөлтэй нь ашиглах.","prerequisites":"Factorial, modulo, fast power.","related":["number-theory","dynamic-programming","knapsack"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"Counting бодлогод эхлээд ямар сонголтуудыг ялгаатай гэж тоолохоо тогтооно. $n$ ялгаатай объектоос $k$-г дараалал харгалзахгүй сонгох нь combination, дараалал харгалзан сонгох нь permutation юм. $n$! нь $n$ ялгаатай объектыг дараалуулан байрлуулах тоо. Ижил, ялгагдахгүй объект байвал шууд $n$! хэрэглэхэд давхар тоолно."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Subset size, grid path, coefficients, identical object distribution зэрэгт хэрэглэ. Grid дээр зөвхөн down/right хөдөлж саадгүй бол $(r,c)$ хүрэх зам $C(r+c,r)$. Obstacles байвал шууд энэ томъёо хүрэлцэхгүй. Stars and bars нь xi≥$0$, sum xi=S гэсэн нөхцөлд $C(S+k-1,k-1)$, $k\\ge 1$; upper bound байвал өөр бодлого болно."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"Prime $\\mathrm{MOD}$ дээр $N<\\mathrm{MOD}$ байвал factorial болон inverse factorial-ийг урьдчилан хадгалж $C(n,k)$-г $O(1)$-д олно. $\\mathrm{InvFact}[N]=\\mathrm{fact}[N]^{\\mathrm{MOD}-2}$, дараа доош $\\mathrm{InvFact}[i-1]=\\mathrm{InvFact}[i]\\times i$. $N\\ge \\mathrm{MOD}$ үед $\\mathrm{fact}[N]=0$ modulo $\\mathrm{MOD}$ болж inverse байхгүй; энэ арга шууд тохирохгүй."},{"type":"math","tex":"\\binom nk=\\frac{n!}{k!(n-k)!},\\quad P(n,k)=\\frac{n!}{(n-k)!},\\quad \\sum_{i=1}^{n}i=\\frac{n(n+1)}2"},{"type":"p","text":"Нэмэлт томъёо: arithmetic progression sum нь $n$(first+last)/$2$; geometric sum $a$($1-r^n$)/$(1-r)$, $r$≠$1$, харин $r=1$ бол an. Modular geometric sum-д denominator inverse зөвхөн оршин байвал хэрэглэнэ. Томъёог хэрэглэхийн өмнө бодлогын counting model болон denominator-ийн нөхцөлийг шалга."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$5$ different object-оос $2$-г дараалал харгалзахгүй сонгоход $C(5,2)$=$10$.","Orderтай бол $P$($5$,$2$)=$5\\times 4=20$: {A,B} сонголтын AB,BA хоёр дараалал тусдаа.","Grid дээр down $2$, right $3$ алхамтай зам: нийт $5$ алхмын $2$ байранд down тавина, $C(5,2)$=$10$.","$3$ хүүхдэд $4$ ижил чихэр, $0$ авч болно: x1+x2+x3=$4$ тул $C(6,2)$=$15$. Чихэрүүд ялгаатай бол энэ загвар тохирохгүй."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"$n$ object-ийн permutation-уудаас эхний $k$-д сонгосон set-ийг авч үз. Нэг $k$-элемент subset нь $k$! дотоод order ба $(n-k)$! үлдсэн order-оор $n$!-д давхар тоологддог. Тиймээс $n$!/($k$!$(n-k)$!) combination. Modulo дээр integer хуваалтыг inverse multiplication-аар солихдоо denominator $\\mathrm{MOD}$-той coprime байх ёстой. Prime $\\mathrm{MOD}$ ба $n<\\mathrm{MOD}$ энэ нөхцөлийг батална."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct Combinations{\n    static constexpr long long MOD=1'000'000'007;\n    vector<long long>f,invf;\n    static long long power(long long a,long long e){\n        long long r=1;while(e){if(e&1)r=r*a%MOD;a=a*a%MOD;e/=2;}return r;\n    }\n    Combinations(int n):f(n+1,1),invf(n+1,1){\n        assert(0<=n&&n<MOD);\n        for(int i=1;i<=n;i++)f[i]=f[i-1]*i%MOD;\n        invf[n]=power(f[n],MOD-2);\n        for(int i=n;i>0;i--)invf[i-1]=invf[i]*i%MOD;\n    }\n    long long choose(int n,int k)const{\n        assert(0<=n&&n<(int)f.size());\n        if(k<0||k>n)return 0;\n        return f[n]*invf[k]%MOD*invf[n-k]%MOD;\n    }\n};"},{"type":"p","text":"Preprocessing хийсэн $N$ хязгаар дотор query асууна. Энд $\\mathrm{MOD}=10^9+7$ тул хоёр residue-ийн үржвэр long long-д багтана. Өөр modulus сонговол primality болон overflow-ийг дахин шалгана. Modulus prime байсан ч $n\\ge\\mathrm{MOD}$ үед factorial-ийн inverse байхгүй тул энэ арга шууд тохирохгүй."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Factorial preprocessing","$O(N+\\log  \\mathrm{MOD})$ хугацаа"],["$C(n,k)$ query","$O(1)$"],["Factorial arrays","$O(N)$ зай"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["Orderтай сонголтыг combination-оор тоолох.","Different ба identical объектуудыг хольж тоолох.","$n\\ge \\mathrm{MOD}$ үед factorial inverse аргыг хэрэглэх.","nC0=nCn=$1$, $k>n$ үед $0$ boundary-уудыг мартах."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Pascal recurrence $C(n,k)$=$C(n-1,k-1)$+$C(n-1,k)$-тай жижиг утгуудыг тулга.","Geometric sum-ийн $r=1$ special case-ийг тайлбарла.","xi≥$1$ бол stars and bars-ийн S-ийг хэрхэн өөрчлөх вэ?"]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"intermediate","order":22,"translations":{"en":{"title":"Combinatorics & counting formulas","summary":"Count ordered and unordered choices and answer binomial queries modulo a prime with factorial tables.","prerequisites":"Factorials, modular powers and inverse conditions.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"First decide which outcomes are distinct. Choosing $k$ objects from $n$ without order gives combinations; choosing with order gives permutations. $n$! orders $n$ distinct objects. Repeated indistinguishable objects require correcting overcounting."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use factorial and inverse-factorial tables for many $C(n,k)$ queries when the preprocessing bound $N$ is strictly below a prime modulus $\\mathrm{MOD}$. If $n$ reaches the modulus, factorials become zero modulo $\\mathrm{MOD}$ and this direct method fails."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"Precompute $\\mathrm{fact}[i]$. Obtain the inverse of $\\mathrm{fact}[N]$ with binary exponentiation, then compute inverse factorials downward. A query multiplies $\\mathrm{fact}[n]$, $\\mathrm{invFact}[k]$ and $\\mathrm{invFact}[n-k]$ modulo $\\mathrm{MOD}$."},{"type":"math","tex":"\\binom nk=\\frac{n!}{k!(n-k)!},\\quad P(n,k)=\\frac{n!}{(n-k)!},\\quad \\sum_{i=1}^{n}i=\\frac{n(n+1)}2"},{"type":"p","text":"Use zero for impossible $k$ outside $[0,n]$. For a composite modulus, the needed inverses may not exist even at small $n$. Alternative techniques such as Pascal DP avoid division but have different time and memory costs."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["For $n=5$ and $k=2$, count unordered pairs.","There are $5\\times 4$ ordered choices of two different objects.","Each unordered pair appears in two orders, so $C(5,2)$=$10$.","The modular factorial formula produces the same result when its inverse conditions hold."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"There are $n$! orders of all objects. Fixing an unordered $k$-element subset accounts for $k$! orders inside it and ($n$-$k$)! orders of the remainder. Dividing gives the binomial formula. Modular inverses implement this division only under the stated coprimality conditions."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct Combinations{\n    static constexpr long long MOD=1'000'000'007;\n    vector<long long>f,invf;\n    static long long power(long long a,long long e){\n        long long r=1;while(e){if(e&1)r=r*a%MOD;a=a*a%MOD;e/=2;}return r;\n    }\n    Combinations(int n):f(n+1,1),invf(n+1,1){\n        assert(0<=n&&n<MOD);\n        for(int i=1;i<=n;i++)f[i]=f[i-1]*i%MOD;\n        invf[n]=power(f[n],MOD-2);\n        for(int i=n;i>0;i--)invf[i-1]=invf[i]*i%MOD;\n    }\n    long long choose(int n,int k)const{\n        assert(0<=n&&n<(int)f.size());\n        if(k<0||k>n)return 0;\n        return f[n]*invf[k]%MOD*invf[n-k]%MOD;\n    }\n};"},{"type":"p","text":"Combinations $c$($N$) uses fixed $\\mathrm{MOD}=1000000007$, and products of two residues fit long long. $\\mathrm{choose}(n,k)$ needs a preprocessed $n$. A prime modulus alone does not make $n\\ge \\mathrm{MOD}$ valid."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Preprocessing","$O(N+\\log  \\mathrm{MOD})$ time"],["One binomial query","$O(1)$ time"],["Factorial tables","$O(N)$ space"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Confusing combinations with permutations.","Applying the factorial formula with $n\\ge \\mathrm{MOD}$.","Assuming inverses always exist for a composite modulus.","Counting identical objects as distinct without justification."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Compare small values with Pascal’s triangle.","Derive the number of grid paths using a binomial coefficient.","Explain why $C(n,k)$=$C(n,n-k)$."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"bitmask-dp","title":"Bitmask & subset DP","category":"DP","level":"Ахисан шат","aliases":"bitmask subset dp assignment маск дэд олонлог popcount","summary":"Жижиг $n$-тэй сонголтын олонлогийг binary $\\mathrm{mask}$-аар төлөөлж subset state дээр DP хийх.","prerequisites":"DP, bit operations, exponential complexity.","related":["dynamic-programming","knapsack","number-theory"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"$n$ объектын subset бүрийг $n$ bit-тэй integer-ээр төлөөлж болно. $j$ bit нь $1$ байвал $j$ объект сонгогдсон гэсэн үг. $\\mathrm{mask}\\mathbin{\\&}(1\\ll j)$ нь тухайн bit байгаа эсэхийг, $\\mathrm{mask}\\mathbin{|}(1\\ll j)$ нь түүнийг нэмсэн subset-ийг өгнө. Нийт subset-ийн тоо $2^n$ тул энэ арга зөвхөн жижиг $n$-д тохирно. Энэ хичээлд worker-уудыг job-уудад оноох minimum-cost assignment бодлогыг авч үзнэ."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Assignment, Hamiltonian path/TSP-ийн state, subset coverage зэрэгт хэрэглэнэ. Assignment жишээнд $n$ worker, $n$ job, $\\mathrm{cost}[i][j]$ байна. Worker бүр нэг job, job бүр нэг worker авч нийт cost minimum. $\\mathrm{dp}[\\mathrm{mask}]$ нь эхний $\\mathrm{popcount}(\\mathrm{mask})$ worker-т $\\mathrm{mask}$-ийн job-уудыг оноосон minimum cost."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"State-д аль worker дараа сонгох нь $\\mathrm{popcount}(\\mathrm{mask})$-аар тодорхой тул worker index-ийг тусад нь хадгалах шаардлагагүй. Сонгоогүй job $j$ бүрийг дараагийн worker $i$-д өгч $\\mathrm{newMask}=\\mathrm{mask}\\mathbin{|}(1\\ll j)$ рүү transition хийнэ. Нэмэгдсэн bit нь integer $\\mathrm{mask}$-ийг өсгөдөг тул increasing $\\mathrm{mask}$ order зөв."},{"type":"math","tex":"dp[mask\\cup\\{j\\}]=\\min\\big(dp[mask\\cup\\{j\\}],dp[mask]+cost[|mask|][j]\\big)"},{"type":"p","text":"TSP-д visited set alone хүрэлцэхгүй: одоо аль орой дээр байгаагаас дараагийн cost өөрчлөгдөнө. Тиймээс $\\mathrm{dp}[\\mathrm{mask}][\\mathrm{last}]$ хэрэгтэй. State-ийг багасгах нь зөвхөн цаашдын шийдвэрт мэдээлэл шаардлагагүй гэдгийг баталсны дараа хийнэ."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["Cost matrix [$[3,1]$,$[2,4]$]. $\\mathrm{dp}[00]=0$.","Worker $0$ job $0$ авбал $\\mathrm{dp}[01]=3$; job $1$ авбал $\\mathrm{dp}[10]=1$.","$\\mathrm{dp}[01]$-ээс worker $1$ job $1$: $\\mathrm{dp}[11]=3+4=7$.","$\\mathrm{dp}[10]$-ээс worker $1$ job $0$: $\\mathrm{dp}[11]$=min($7$,$1+2$)=$3$. Optimal assignment $0\\to 1$,$1\\to 0$."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"Mask-ийн хэмжээгээр induction хий. Mask рүү хүрсэн assignment бүр дараагийн worker-т сонгоогүй job өгөх ёстой; transition бүх ийм сонголтыг хамарна. Нэг $\\mathrm{mask}$-ийн өөр assignment-ууд цааш ижил worker index ба ижил сул job set-тэй тул minimum cost-ийг л хадгалахад хангалттай. Full $\\mathrm{mask}$ дээр бүх worker/job яг нэг удаа ашиглагдсан болно."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nlong long assignment(const vector<vector<long long>>& cost){\n    int n=cost.size();assert(n<=20);\n    for(auto&r:cost)assert((int)r.size()==n);\n    const long long INF=4'000'000'000'000'000'000LL;\n    int states=1<<n;vector<long long>dp(states,INF);dp[0]=0;\n    for(int mask=0;mask<states;mask++){\n        int i=__builtin_popcount((unsigned)mask);if(i==n)continue;\n        for(int j=0;j<n;j++)if(!(mask>>j&1)){\n            assert(cost[i][j]>=0&&cost[i][j]<INF/20);\n            int next=mask|(1<<j);\n            dp[next]=min(dp[next],dp[mask]+cost[i][j]);\n        }\n    }\n    return dp.back();\n}"},{"type":"p","text":"Энэ dense assignment жишээнд cost сөрөг биш бөгөөд нийт cost $\\mathrm{INF}$-ээс бага байна. Бүх mask-д хүрэх боломжтой. Forbidden assignment нэмбэл unreachable state-ээс transition хийхгүй байх шалгалт нэмж оруулна. $n=0$ үед хоосон assignment-ийн cost $0$. Кодын хязгаар $n\\le20$."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Subset assignment","$O(n 2^n)$ хугацаа"],["DP table","$O(2^n)$ зай"],["TSP зэрэг last-тай state","Ердийн $O(n^{2} 2^n)$ transition хугацаа"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["$n$ том байхад exponential state memory багтана гэж үзэх.","$1\\ll n$-ийг signed int-ийн bit хязгаараас давуулах.","Mask-аас last vertex-ийг сэргээж болно гэж буруу бодох.","Unreachable $\\mathrm{INF}$ state дээр cost нэмж overflow үүсгэх."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["$n\\le 8$ үед бүх permutation-ийн assignment cost-тай тулга.","TSP-д $\\mathrm{dp}[\\mathrm{mask}][\\mathrm{last}]$ recurrence бич; эхлэх оройг яаж тогтоох вэ?","Subset-уудын бүх submask-ийг enumerate хийх loop яагаад нийт $O(3^n)$ болдог вэ?"]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"advanced","order":23,"translations":{"en":{"title":"Bitmask & subset DP","summary":"Represent small subsets as bitmasks and solve assignment with one state per chosen-job set.","prerequisites":"DP, bit operations and exponential complexity.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"An $n$-bit integer represents a subset of $n$ objects. Bit $j$ indicates whether object $j$ is selected. There are $2^n$ subsets, so this is suitable for small $n$, often around $20$, rather than large inputs."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"In the assignment example, workers are processed in fixed order. $\\mathrm{mask}$ records the already-used jobs; the next worker index is $\\mathrm{popcount}(\\mathrm{mask})$. If a problem also needs the last visited object, that information must be included as another state dimension."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"Initialize $\\mathrm{dp}[0]=0$. For each $\\mathrm{mask}$, give the next worker $i$ an unused job $j$ and update the state with bit $j$ set. Adding a bit increases the integer $\\mathrm{mask}$, so increasing-$\\mathrm{mask}$ iteration respects dependencies."},{"type":"math","tex":"dp[mask\\cup\\{j\\}]=\\min\\big(dp[mask\\cup\\{j\\}],dp[mask]+cost[|mask|][j]\\big)"},{"type":"p","text":"The sample handles a dense nonnegative cost matrix with every total cost below $\\mathrm{INF}$. Forbidden assignments need explicit unreachable-state checks. The empty instance has cost zero."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["For two workers, take costs [$[3,1]$,$[2,4]$].","From $\\mathrm{mask}=0$, worker $0$ can choose job $0$ for cost $3$ or job $1$ for cost $1$.","If job $1$ is chosen first, worker $1$ must take job $0$ for an additional cost $2$.","The full-$\\mathrm{mask}$ optimum is $3$, rather than the other assignment cost $7$."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"For a fixed used-job set, the number of assigned workers is determined. Future options depend only on which jobs remain, so keeping the cheapest cost for that set loses no useful information. Every complete assignment is generated by exactly one sequence of job additions."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nlong long assignment(const vector<vector<long long>>& cost){\n    int n=cost.size();assert(n<=20);\n    for(auto&r:cost)assert((int)r.size()==n);\n    const long long INF=4'000'000'000'000'000'000LL;\n    int states=1<<n;vector<long long>dp(states,INF);dp[0]=0;\n    for(int mask=0;mask<states;mask++){\n        int i=__builtin_popcount((unsigned)mask);if(i==n)continue;\n        for(int j=0;j<n;j++)if(!(mask>>j&1)){\n            assert(cost[i][j]>=0&&cost[i][j]<INF/20);\n            int next=mask|(1<<j);\n            dp[next]=min(dp[next],dp[mask]+cost[i][j]);\n        }\n    }\n    return dp.back();\n}"},{"type":"p","text":"Require $n\\le 20$ in the supplied code and avoid oversized shifts. Use long long for totals. To reconstruct an assignment, store the predecessor $\\mathrm{mask}$ and chosen job for each improving transition."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Assignment DP","$O(n 2^n)$ time"],["One cost per subset","$O(2^n)$ space"],["TSP with a last-vertex dimension","Typically $O(n^{2} 2^n)$ transition time"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Ignoring the exponential number of subsets.","Using signed shifts beyond the integer width.","Omitting a state dimension that affects future choices.","Adding costs to an unreachable $\\mathrm{INF}$ state."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Compare small instances with permutation enumeration.","Add forbidden assignments and handle unreachable masks.","Explain why TSP needs both $\\mathrm{mask}$ and the last vertex."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}},{"id":"lazy-segment-tree","title":"Lazy propagation — range add / sum","category":"Data structures","level":"Ахисан шат","aliases":"lazy propagation segment tree range add range update sum pending","summary":"Бүх leaf-ийг өөрчлөхгүйгээр range add ба range sum-ийг $O(\\log  n)$-д боловсруулах.","prerequisites":"Segment tree, recursion, range sum.","related":["segment-tree","fenwick-tree","prefix-sums"],"sections":[{"title":"1. Гол ойлголт","blocks":[{"type":"p","text":"Lazy propagation нь range update-ийг node-ийн нэгтгэсэн утгад шууд тусгаж, child-уудад дамжуулах ажлыг түр хойшлуулдаг. Хойшлуулсан өөрчлөлтийг $\\mathrm{lazy}$ tag-д хадгална. Ингэснээр update бүрд range-ийн бүх элементийг тойрох шаардлагагүй. Энэ хичээлд зөвхөн range add update болон range sum query-г авч үзнэ."}]},{"title":"2. Хэзээ хэрэглэх вэ?","blocks":[{"type":"p","text":"Олон range add ба range sum ээлжилдэг array бодлогод хэрэглэ. Assign, multiply, min, max зэрэг operation бүр өөр tag composition ба aggregate mapping-тай. Lazy гэх нэртэй учраас дурын operation-ийг залгаад зөв болно гэсэн үг биш. Range add бүх элемент-д ижил $\\mathrm{delta}$ нэмэх тул sum segmentLength×$\\mathrm{delta}$-аар өөрчлөгдөнө."}]},{"title":"3. Санааг нь ойлгох","blocks":[{"type":"p","text":"Node $v$ нь $[l,r)$ segment. apply($v$,$\\mathrm{delta}$) нь $\\mathrm{sum}[v]+=\\mathrm{delta}*(r-l)$, $\\mathrm{lazy}[v]+=\\mathrm{delta}$. Query/update segment-ийг бүтнээр хамарвал apply хийж зогсоно. Хэсэгчлэн хамарвал өмнөх $\\mathrm{lazy}$-г children-д push хийж, children дээр ажиллаад parent sum-ийг дахин merge хийнэ."},{"type":"math","tex":"sum[v]\\leftarrow sum[v]+\\Delta(r-l),\\qquad lazy[v]\\leftarrow lazy[v]+\\Delta"},{"type":"p","text":"Lazy tag нь хүүхдүүдийн aggregate-д хараахан ороогүй өөрчлөлт; харин тухайн node-ийн sum-д аль хэдийн орсон. Push үед parent sum-г дахин нэмэхгүй. Children-д apply хийгээд parent $\\mathrm{lazy}=0$ болгоно. Add tag-ууд нийлбэрээр compose хийгдэх ч assign+add tag-ийн order чухал."}]},{"title":"4. Жишээг алхам алхмаар","blocks":[{"type":"ordered","items":["$a=[1,2,3,4]$, root $\\mathrm{sum}=10$. $[0,4)$-д +$5$ update: root $\\mathrm{sum}=30$,$\\mathrm{lazy}=5$; leaf бүрийг шууд үзэхгүй.","$[1,3)$ query хийхийн өмнө root-ийн +$5$-г хоёр child-д push.","Query нь index $1$-ийн $7$ ба index $2$-ын $8$-г авч $15$.","$[2,4)$-д $-2$ нэмбэл final array $[6,7,6,7]$. Бүтэн $\\mathrm{sum}=26$."]}]},{"title":"5. Яагаад зөв ажилладаг вэ?","blocks":[{"type":"p","text":"Invariant: $\\mathrm{sum}[v]$ нь segment-ийн бодит нийлбэр, $\\mathrm{lazy}[v]$ нь children-д дамжуулаагүй update. Full-cover add бүх элемент-д $\\mathrm{delta}$ нэмэх тул aggregate өөрчлөлт $\\mathrm{delta}$×length зөв. Push хоёр хүүхдэд тэдний length-ээр update хийдэг учир children-ийн sum-ийн нийлбэр parent sum-тай нийцнэ. Partial recursion дараах merge invariant-ийг сэргээдэг тул query/update induction-аар зөв."}]},{"title":"6. C++17 хэрэгжүүлэлт","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct LazySeg{\n    int n;vector<long long>sum,lazy;\n    LazySeg(const vector<long long>&a):n(a.size()),sum(4*n),lazy(4*n){\n        assert(n>0);build(1,0,n,a);\n    }\n    void build(int v,int l,int r,const vector<long long>&a){\n        if(r-l==1){sum[v]=a[l];return;}int m=(l+r)/2;\n        build(v*2,l,m,a);build(v*2+1,m,r,a);sum[v]=sum[v*2]+sum[v*2+1];\n    }\n    void apply(int v,int l,int r,long long x){sum[v]+=x*(r-l);lazy[v]+=x;}\n    void push(int v,int l,int r){\n        if(r-l==1||lazy[v]==0)return;int m=(l+r)/2;\n        apply(v*2,l,m,lazy[v]);apply(v*2+1,m,r,lazy[v]);lazy[v]=0;\n    }\n    void add(int ql,int qr,long long x,int v,int l,int r){\n        if(qr<=l||r<=ql)return;\n        if(ql<=l&&r<=qr){apply(v,l,r,x);return;}\n        push(v,l,r);int m=(l+r)/2;\n        add(ql,qr,x,v*2,l,m);add(ql,qr,x,v*2+1,m,r);\n        sum[v]=sum[v*2]+sum[v*2+1];\n    }\n    long long query(int ql,int qr,int v,int l,int r){\n        if(qr<=l||r<=ql)return 0;if(ql<=l&&r<=qr)return sum[v];\n        push(v,l,r);int m=(l+r)/2;\n        return query(ql,qr,v*2,l,m)+query(ql,qr,v*2+1,m,r);\n    }\n    void add(int l,int r,long long x){assert(0<=l&&l<=r&&r<=n);add(l,r,x,1,0,n);}\n    long long query(int l,int r){assert(0<=l&&l<=r&&r<=n);return query(l,r,1,0,n);}\n};"},{"type":"p","text":"Гаднаас өгөх range нь $[l,r)$, анхны array хоосон биш байна. Sum болон $\\mathrm{delta}\\times\\mathrm{length}$ нь long long-д багтах ёстой. Query нь push хийж дотоод tag-уудыг өөрчилдөг тул const биш. Гэхдээ query хийх нь array-ийн бодит утгуудыг өөрчлөхгүй."}]},{"title":"7. Time ба space complexity","blocks":[{"type":"table","headers":["Хэсэг","Хугацаа / санах ой"],"rows":[["Build","$O(n)$"],["Range add / range sum","$O(\\log  n)$"],["sum ба $\\mathrm{lazy}$ arrays","$O(n)$ зай"]]}]},{"title":"8. Түгээмэл алдаа","blocks":[{"type":"list","items":["Sum-д зөвхөн $\\mathrm{delta}$ нэмэх; segment-ийн length-ээр үржүүлэх хэрэгтэй.","Push хийсний дараа parent $\\mathrm{lazy}$-г тэглэхгүй байх.","Children рүү буухаас өмнө pending update-г push хийхгүй байх.","Assign ба add tag-ийг дараалал харгалзахгүйгээр хольж compose хийх."]}]},{"title":"9. Өөрөө туршаад үз","blocks":[{"type":"ordered","items":["Random range add/query-г naive vector-тай тулга.","Бүтэн range update дараа ганц элемент query турш.","Range assign tag нэмэхэд ямар boolean болон composition rule хэрэгтэй вэ?"]},{"type":"note","text":"Кодыг харалгүй санааг нь өөрийн үгээр тайлбарла. Дараа нь жижиг input дээр гараар ажиллуулж, яагаад зөв болохыг батлаад, дараа нь хэрэгжүүлээрэй."}]},{"title":"10. Цааш унших","blocks":[{"type":"p","text":"Ижил сэдвийг өөр тайлбартай харьцуулж унших эх сурвалжууд. Энэ хичээлийн жишээ болон Монгол тайлбарыг Erdene Club-д зориулан бичсэн."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}],"levelKey":"advanced","order":24,"translations":{"en":{"title":"Lazy propagation — range add / sum","summary":"Delay propagation of range additions while keeping segment sums correct.","prerequisites":"Segment trees, recursion and range-update composition.","sections":[{"title":"1. Core concept","blocks":[{"type":"p","text":"A $\\mathrm{lazy}$ segment tree applies an update to a whole node’s aggregate immediately but postpones updating its children. A pending tag records that delayed work. This lesson supports range addition and range sum only."}]},{"title":"2. When to use it","blocks":[{"type":"p","text":"Use it when point-by-point updates would be too slow. Define how an update changes an aggregate and how updates compose. Range assignment mixed with addition needs a richer tag and careful composition order."}]},{"title":"3. Understanding the idea","blocks":[{"type":"p","text":"For a node covering $[l,r)$, adding $\\mathrm{delta}$ changes its sum by $\\mathrm{delta}$ times the segment length. Accumulate $\\mathrm{delta}$ in the $\\mathrm{lazy}$ tag. On partial overlap, push pending tags to children, recurse, then rebuild the parent sum."},{"type":"math","tex":"sum[v]\\leftarrow sum[v]+\\Delta(r-l),\\qquad lazy[v]\\leftarrow lazy[v]+\\Delta"},{"type":"p","text":"A fully covered query can return the stored sum without descending. A partial query must push first so children are current. The public ranges are half-open and the sample requires a nonempty array."}]},{"title":"4. Worked example","blocks":[{"type":"ordered","items":["Start with $a=[1,2,3,4]$.","Add $5$ to $[1,4)$; the logical array becomes $[1,7,8,9]$.","A fully covered internal segment updates its sum and pending tag without visiting each leaf.","Query $[2,4)$ pushes any required tags and returns $8+9=17$."]}]},{"title":"5. Why it is correct","blocks":[{"type":"p","text":"The invariant is that each node sum includes all updates affecting its segment, while its tag represents changes not yet sent below. apply preserves the sum through $\\mathrm{delta}$ times length. push makes child sums current, and merging them after recursion restores the parent invariant."}]},{"title":"6. C++17 implementation","blocks":[{"type":"code","language":"C++17","text":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct LazySeg{\n    int n;vector<long long>sum,lazy;\n    LazySeg(const vector<long long>&a):n(a.size()),sum(4*n),lazy(4*n){\n        assert(n>0);build(1,0,n,a);\n    }\n    void build(int v,int l,int r,const vector<long long>&a){\n        if(r-l==1){sum[v]=a[l];return;}int m=(l+r)/2;\n        build(v*2,l,m,a);build(v*2+1,m,r,a);sum[v]=sum[v*2]+sum[v*2+1];\n    }\n    void apply(int v,int l,int r,long long x){sum[v]+=x*(r-l);lazy[v]+=x;}\n    void push(int v,int l,int r){\n        if(r-l==1||lazy[v]==0)return;int m=(l+r)/2;\n        apply(v*2,l,m,lazy[v]);apply(v*2+1,m,r,lazy[v]);lazy[v]=0;\n    }\n    void add(int ql,int qr,long long x,int v,int l,int r){\n        if(qr<=l||r<=ql)return;\n        if(ql<=l&&r<=qr){apply(v,l,r,x);return;}\n        push(v,l,r);int m=(l+r)/2;\n        add(ql,qr,x,v*2,l,m);add(ql,qr,x,v*2+1,m,r);\n        sum[v]=sum[v*2]+sum[v*2+1];\n    }\n    long long query(int ql,int qr,int v,int l,int r){\n        if(qr<=l||r<=ql)return 0;if(ql<=l&&r<=qr)return sum[v];\n        push(v,l,r);int m=(l+r)/2;\n        return query(ql,qr,v*2,l,m)+query(ql,qr,v*2+1,m,r);\n    }\n    void add(int l,int r,long long x){assert(0<=l&&l<=r&&r<=n);add(l,r,x,1,0,n);}\n    long long query(int l,int r){assert(0<=l&&l<=r&&r<=n);return query(l,r,1,0,n);}\n};"},{"type":"p","text":"Use LazySeg st($a$), st.add($l$,$r$,$\\mathrm{delta}$) and st.$\\mathrm{query}(l,r)$. All sums and products must fit long long. Query may modify internal tags through push, while leaving the logical array unchanged."}]},{"title":"7. Time and space complexity","blocks":[{"type":"table","headers":["Operation","Time / space"],"rows":[["Build","$O(n)$ time"],["Range addition or range-sum query","$O(\\log  n)$ time"],["Sum and $\\mathrm{lazy}$ arrays","$O(n)$ space"]]}]},{"title":"8. Common mistakes","blocks":[{"type":"list","items":["Adding $\\mathrm{delta}$ instead of $\\mathrm{delta}$ times segment length to a sum.","Descending before pushing pending tags.","Clearing a tag without sending it to both children.","Using addition-tag composition for a range-assignment update."]}]},{"title":"9. Try it yourself","blocks":[{"type":"ordered","items":["Compare overlapping updates against a naive array.","Test empty query ranges and full-array additions.","Derive the tag composition rules for assignment followed by addition."]},{"type":"note","text":"Explain the idea without looking at the code. Trace a small input by hand, justify the invariant, and then implement it. Compare with a brute-force reference on small cases."}]},{"title":"10. Further reading","blocks":[{"type":"p","text":"Read a second explanation and compare its indexing conventions and assumptions. The explanations and examples here were written for Erdene Club."},{"type":"links","items":[{"label":"Competitive Programmer’s Handbook — Antti Laaksonen","url":"https://cses.fi/book/book.pdf"},{"label":"MIT 6.006 — Algorithms lecture notes","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/lecture-notes/"}]}]}]}}}]$tutorial_seed$::jsonb) as seed(x)
